-- The gallery database structure, generated by `npm run db:schema` (scripts/dump-schema.mjs).
-- Read from production at migration 20261105120000, the newest file in supabase/migrations.
-- Structure plus the configuration rows in part 3; no visitor, photo or album rows.
-- README "Database" says how to build a new project from it.

-- 1. Extensions the schemas below use
CREATE EXTENSION IF NOT EXISTS "pg_cron";
CREATE EXTENSION IF NOT EXISTS "pg_trgm" WITH SCHEMA "public";
CREATE EXTENSION IF NOT EXISTS "vector" WITH SCHEMA "public";

-- 2. Schemas public and analytics_private (supabase db dump)
SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "analytics_private";


ALTER SCHEMA "analytics_private" OWNER TO "postgres";


CREATE SCHEMA IF NOT EXISTS "public";


ALTER SCHEMA "public" OWNER TO "pg_database_owner";


COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE TYPE "public"."sport_enum" AS ENUM (
    'volleyball',
    'basketball',
    'soccer',
    'softball',
    'baseball',
    'football',
    'track',
    'cross_country',
    'golf',
    'tennis',
    'bowling',
    'pickleball',
    'other'
);


ALTER TYPE "public"."sport_enum" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics_private"."count_distinct_visitors"("p_start" "date", "p_end" "date", "p_album_keys" "text"[], "p_sport" "text", "p_category" "text", "p_source" "text", "p_event_date" "date", "p_season" "text", "p_album_event_type" "text", "p_measure" "text", "p_traffic" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
  interval_start timestamptz := p_start::timestamp AT TIME ZONE 'America/Chicago';
  interval_end timestamptz := (p_end + 1)::timestamp AT TIME ZONE 'America/Chicago';
  answer bigint;
BEGIN
  IF p_start > p_end
    OR interval_start < now() - interval '90 days'
    OR interval_end > now()
  THEN RETURN NULL;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM generate_series(p_start, p_end, interval '1 day') day
    LEFT JOIN public.analytics_daily_coverage coverage
      ON coverage.bucket_date = day::date
    WHERE coverage.bucket_date IS NULL
      OR coverage.raw_window_start > day::date::timestamp AT TIME ZONE 'America/Chicago'
      OR coverage.raw_window_end < (day::date + 1)::timestamp AT TIME ZONE 'America/Chicago'
      OR coverage.coverage_state <> 'complete'
      OR coverage.frozen_at IS NOT NULL
  ) THEN RETURN NULL;
  END IF;

  SELECT count(DISTINCT e.session_hash) INTO answer
  FROM analytics_private.effective_engagement_events e
  WHERE (e.created_at AT TIME ZONE 'America/Chicago')::date BETWEEN p_start AND p_end
    AND e.session_hash IS NOT NULL
    AND (coalesce(cardinality(p_album_keys), 0) = 0 OR e.resolved_album_key = ANY(p_album_keys))
    AND (p_sport IS NULL OR e.snapshot_sport = p_sport)
    AND (p_category IS NULL OR e.snapshot_photo_category = p_category)
    AND (p_source IS NULL OR coalesce(e.source, 'direct') = p_source)
    AND (p_event_date IS NULL OR e.snapshot_event_date = p_event_date)
    AND (p_season IS NULL OR coalesce(extract(year FROM e.snapshot_event_date)::text,'unknown') = p_season)
    AND (p_album_event_type IS NULL OR e.snapshot_album_event_type = p_album_event_type)
    AND (p_traffic = 'inclusive' OR e.effective_classification IN ('audience', 'unclassified'));
  RETURN answer;
END;
$$;


ALTER FUNCTION "analytics_private"."count_distinct_visitors"("p_start" "date", "p_end" "date", "p_album_keys" "text"[], "p_sport" "text", "p_category" "text", "p_source" "text", "p_event_date" "date", "p_season" "text", "p_album_event_type" "text", "p_measure" "text", "p_traffic" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics_private"."enforce_posthog_outbox_origin"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Delivery workers update status, leases, retries, and receipts after a control
  -- has been created. Only its provenance and payload are protected here.
  IF TG_OP = 'UPDATE' THEN
    IF NEW.origin IS NOT DISTINCT FROM OLD.origin
      AND NEW.target_event_id IS NOT DISTINCT FROM OLD.target_event_id
      AND NEW.payload IS NOT DISTINCT FROM OLD.payload THEN
      RETURN NEW;
    END IF;
  END IF;
  IF NEW.origin = 'classification_control' AND current_setting('analytics.classification_control_write', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'classification controls require the correction RPC' USING ERRCODE = '42501';
  END IF;
  IF NEW.origin = 'event' AND NEW.target_event_id IS NOT NULL THEN
    RAISE EXCEPTION 'ordinary outbox rows cannot name a control target' USING ERRCODE = '23514';
  END IF;
  IF NEW.origin = 'classification_control' AND NEW.target_event_id IS NULL THEN
    RAISE EXCEPTION 'classification controls require a target event' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "analytics_private"."enforce_posthog_outbox_origin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics_private"."prepare_engagement_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
  authoritative_album text;
  target_exists boolean;
  snapshot jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.photo_id, NEW.album_key, NEW.event_type, NEW.session_hash,
      NEW.source, NEW.created_at, NEW.event_day, NEW.traffic_context, NEW.source_kind
    ) IS DISTINCT FROM ROW(
      OLD.photo_id, OLD.album_key, OLD.event_type, OLD.session_hash,
      OLD.source, OLD.created_at, OLD.event_day, OLD.traffic_context, OLD.source_kind
    ) OR (
      OLD.catalogue_snapshot IS NOT NULL
      AND NEW.catalogue_snapshot IS DISTINCT FROM OLD.catalogue_snapshot
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'engagement event facts and attached catalogue snapshot are immutable';
    END IF;
    -- The migration's one allowed attachment is NULL -> first backfill snapshot.
    IF OLD.catalogue_snapshot IS NULL AND NEW.catalogue_snapshot IS NOT NULL THEN
      RETURN NEW;
    END IF;
  END IF;

  IF NEW.photo_id IS NOT NULL THEN
    SELECT pm.album_key INTO authoritative_album
    FROM public.photo_metadata pm
    WHERE pm.photo_id = NEW.photo_id;
    IF NOT FOUND OR authoritative_album IS NULL THEN
      RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'unknown photo target';
    END IF;
    IF NEW.album_key IS NOT NULL AND NEW.album_key <> authoritative_album THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'photo and album targets do not match';
    END IF;
    NEW.album_key := authoritative_album;
  ELSIF NEW.album_key IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.albums a WHERE a.album_key = NEW.album_key
    ) INTO target_exists;
    IF NOT target_exists THEN
      RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'unknown album target';
    END IF;
  END IF;

  CASE NEW.event_type
    WHEN 'view' THEN
      IF NEW.photo_id IS NULL AND NEW.source_kind <> 'tagged_arrival' THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
          MESSAGE = 'photo view requires a photo unless emitted as a tagged arrival';
      END IF;
      IF NEW.photo_id IS NOT NULL AND NEW.source_kind = 'unknown' THEN
        NEW.source_kind := 'internal_open_location';
      END IF;
    WHEN 'album_open' THEN
      IF NEW.photo_id IS NOT NULL OR NEW.album_key IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
          MESSAGE = 'album_open requires an album and no photo';
      END IF;
      IF NEW.source_kind = 'unknown' THEN NEW.source_kind := 'internal_open_location'; END IF;
    WHEN 'favorite', 'download', 'share' THEN
      IF NEW.photo_id IS NULL AND NEW.album_key IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'action requires a photo or album';
      END IF;
      IF NEW.source_kind = 'unknown' THEN NEW.source_kind := 'action'; END IF;
    ELSE
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'unsupported engagement event type';
  END CASE;

  IF NEW.catalogue_snapshot IS NULL THEN
    SELECT jsonb_build_object(
      '_basis', 'event_snapshot',
      'album_key', NEW.album_key,
      'sport', a.sport::text,
      'event_date', a.event_date,
      'album_event_type', NULL::text,
      'publication_at', settings.first_published_at,
      'photo_category', pm.photo_category
    ) INTO snapshot
    FROM (SELECT 1) seed
    LEFT JOIN public.albums a ON a.album_key = NEW.album_key
    LEFT JOIN public.album_settings settings ON settings.album_key = NEW.album_key
    LEFT JOIN public.photo_metadata pm ON pm.photo_id = NEW.photo_id;
    NEW.catalogue_snapshot := snapshot;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "analytics_private"."prepare_engagement_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics_private"."prune_engagement_events_at"("run_at" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
  prune_cutoff timestamptz := run_at - interval '90 days';
  expiring_day date;
  day_start timestamptz;
  day_end timestamptz;
  reconcile_error text;
  existing public.analytics_daily_coverage%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('analytics-reconcile-batch'));
  LOCK TABLE public.engagement_events IN SHARE ROW EXCLUSIVE MODE;

  FOR expiring_day IN
    SELECT DISTINCT (created_at AT TIME ZONE 'America/Chicago')::date
    FROM public.engagement_events
    WHERE created_at < prune_cutoff
    ORDER BY 1
  LOOP
    day_start := expiring_day::timestamp AT TIME ZONE 'America/Chicago';
    day_end := (expiring_day + 1)::timestamp AT TIME ZONE 'America/Chicago';
    reconcile_error := NULL;

    BEGIN
      PERFORM analytics_private.reconcile_daily_actions(expiring_day, run_at);
    EXCEPTION WHEN OTHERS THEN
      reconcile_error := SQLERRM;
      INSERT INTO public.analytics_reconciliation_runs (
        from_day, through_day, cutoff_at, status, completed_at, error_message
      ) VALUES (
        expiring_day, expiring_day, run_at, 'failed', run_at, reconcile_error
      );
    END;

    SELECT * INTO existing
    FROM public.analytics_daily_coverage
    WHERE bucket_date = expiring_day
    FOR UPDATE;

    IF NOT FOUND THEN
      INSERT INTO public.analytics_daily_coverage (
        bucket_date, raw_window_start, raw_window_end, cutoff_at,
        coverage_state, catalogue_basis, definition_version, notes,
        frozen_at, preserved_row_count
      ) VALUES (
        expiring_day,
        greatest(day_start, least(prune_cutoff, day_end)),
        day_end,
        run_at,
        'unavailable',
        'event_snapshot',
        1,
        'Preservation failed before the 90-day privacy cutoff: ' ||
          coalesce(reconcile_error, 'no durable result was produced'),
        run_at,
        0
      );
    ELSE
      UPDATE public.analytics_daily_coverage
      SET frozen_at = coalesce(frozen_at, run_at),
        cutoff_at = run_at,
        reconciled_at = run_at,
        notes = CASE
          WHEN reconcile_error IS NULL THEN notes
          ELSE coalesce(notes || ' ', '') ||
            'Final preservation failed before raw expiry: ' || reconcile_error
        END
      WHERE bucket_date = expiring_day;
    END IF;
  END LOOP;

  DELETE FROM public.engagement_events WHERE created_at < prune_cutoff;
END;
$$;


ALTER FUNCTION "analytics_private"."prune_engagement_events_at"("run_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics_private"."prune_events_v2_at"("run_at" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('analytics-v2-prune'));
 WITH candidates AS MATERIALIZED (
  SELECT e.*, CASE WHEN e.traffic_context <> 'audience' THEN e.traffic_context ELSE coalesce(c.classification,e.traffic_context) END AS effective_context
  FROM public.analytics_events_v2 e LEFT JOIN LATERAL (SELECT classification FROM public.analytics_event_v2_classifications c WHERE c.event_id=e.event_id ORDER BY classification_version DESC LIMIT 1) c ON true
  WHERE e.received_at < run_at-interval '90 days'
 ), removed AS (
  DELETE FROM public.analytics_events_v2 e USING candidates c WHERE e.event_id=c.event_id RETURNING e.event_id
 ), grouped AS (
  SELECT (occurred_at AT TIME ZONE CASE WHEN event_name IN ('site_page_viewed','site_link_clicked','content_progressed','content_active_time','demo_section_viewed') THEN 'UTC' ELSE 'America/Chicago' END)::date AS bucket_date,event_name,effective_context AS traffic_context,album_key,photo_id,
   jsonb_strip_nulls(jsonb_build_object('album_sport',properties->'album_sport','event_date',properties->'event_date','photo_category',properties->'photo_category','tagged_source',properties->'tagged_source','surface',properties->'surface','mode',properties->'mode','outcome',properties->'outcome','content_kind',properties->'content_kind','site_section',properties->'site_section','canonical_path',properties->'canonical_path','target_kind',properties->'target_kind','target_path',properties->'target_path','threshold',properties->'threshold','position',properties->'position','section_count',properties->'section_count')) AS dimensions,
   count(*) AS event_count,count(*) FILTER(WHERE export_eligible) AS export_eligible_count,max(occurred_at) AS last_recorded_at
  FROM candidates WHERE event_id IN (SELECT event_id FROM removed) GROUP BY 1,2,3,4,5,6
 ) INSERT INTO public.analytics_v2_archived_totals SELECT * FROM grouped
 ON CONFLICT(bucket_date,event_name,traffic_context,album_key,photo_id,dimensions)
 DO UPDATE SET event_count=analytics_v2_archived_totals.event_count+EXCLUDED.event_count,
 export_eligible_count=analytics_v2_archived_totals.export_eligible_count+EXCLUDED.export_eligible_count,
 last_recorded_at=greatest(analytics_v2_archived_totals.last_recorded_at,EXCLUDED.last_recorded_at);
 -- Outbox rows cascade with expired raw records. Confirmed delivery receipts have
 -- no further recovery job; keep seven days for inspection before removing them.
 DELETE FROM public.analytics_posthog_outbox WHERE status='confirmed' AND confirmed_at<run_at-interval '7 days';
END $$;


ALTER FUNCTION "analytics_private"."prune_events_v2_at"("run_at" timestamp with time zone) OWNER TO "postgres";


