CREATE OR REPLACE FUNCTION "analytics_private"."reconcile_daily_actions"("target_day" "date", "cutoff_at" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
  day_start timestamptz := target_day::timestamp AT TIME ZONE 'America/Chicago';
  full_day_end timestamptz := (target_day + 1)::timestamp AT TIME ZONE 'America/Chicago';
  aggregate_end timestamptz := least(full_day_end, cutoff_at);
  retention_floor timestamptz := cutoff_at - interval '90 days';
  evidence_start timestamptz;
  evidence_end timestamptz;
  state text;
  day_basis text;
  has_backfill boolean;
  has_snapshot boolean;
  existing public.analytics_daily_coverage%ROWTYPE;
  preserved_count bigint;
BEGIN
  IF cutoff_at <= day_start THEN
    RAISE EXCEPTION 'cutoff must be after the reporting day starts';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('analytics-reconcile:' || target_day::text));

  SELECT * INTO existing
  FROM public.analytics_daily_coverage
  WHERE bucket_date = target_day
  FOR UPDATE;
  IF FOUND AND existing.frozen_at IS NOT NULL THEN RETURN; END IF;

  -- A retry or correction never uses an older cutoff than the generation it
  -- replaces, even when a test invokes the function with a time-travel value.
  aggregate_end := greatest(
    aggregate_end,
    least(coalesce(existing.cutoff_at, aggregate_end), full_day_end)
  );

  evidence_start := CASE
    WHEN existing.bucket_date IS NOT NULL THEN existing.raw_window_start
    ELSE greatest(day_start, least(retention_floor, full_day_end))
  END;
  evidence_end := greatest(
    coalesce(existing.raw_window_end, evidence_start),
    aggregate_end
  );
  evidence_end := least(evidence_end, full_day_end);
  state := CASE
    WHEN evidence_start = day_start AND evidence_end = full_day_end THEN 'complete'
    ELSE 'partial'
  END;

  DELETE FROM public.analytics_daily_actions
  WHERE bucket_date = target_day AND definition_version = 1;

  INSERT INTO public.analytics_daily_actions (
    bucket_date, album_key, photo_id, event_type, source, source_kind, sport,
    event_date, album_event_type, publication_at, photo_category,
    traffic_classification, classification_version, catalogue_basis,
    definition_version, coverage_state, action_count, latest_event_at
  )
  SELECT
    target_day,
    coalesce(e.resolved_album_key, ''),
    coalesce(e.photo_id, ''),
    e.event_type,
    coalesce(e.source, 'direct'),
    e.resolved_source_kind,
    e.snapshot_sport,
    e.snapshot_event_date,
    e.snapshot_album_event_type,
    e.snapshot_publication_at,
    e.snapshot_photo_category,
    e.effective_classification,
    e.effective_classification_version,
    e.catalogue_basis,
    1,
    state,
    count(*),
    max(e.created_at)
  FROM analytics_private.effective_engagement_events e
  WHERE e.created_at >= day_start AND e.created_at < aggregate_end
  GROUP BY e.resolved_album_key, e.photo_id, e.event_type, e.source,
    e.resolved_source_kind, e.snapshot_sport, e.snapshot_event_date,
    e.snapshot_album_event_type, e.snapshot_publication_at,
    e.snapshot_photo_category, e.effective_classification,
    e.effective_classification_version, e.catalogue_basis;

  GET DIAGNOSTICS preserved_count = ROW_COUNT;

  SELECT
    coalesce(bool_or(e.catalogue_basis = 'backfill_current_catalogue'), false),
    coalesce(bool_or(e.catalogue_basis = 'event_snapshot'), false)
  INTO has_backfill, has_snapshot
  FROM analytics_private.effective_engagement_events e
  WHERE e.created_at >= day_start AND e.created_at < aggregate_end;

  day_basis := CASE
    WHEN has_backfill AND has_snapshot THEN 'mixed'
    WHEN has_backfill THEN 'backfill_current_catalogue'
    ELSE 'event_snapshot'
  END;

  INSERT INTO public.analytics_daily_coverage (
    bucket_date, raw_window_start, raw_window_end, cutoff_at, coverage_state,
    catalogue_basis, definition_version, notes, preserved_row_count
  ) VALUES (
    target_day, evidence_start, evidence_end, cutoff_at, state, day_basis, 1,
    CASE WHEN state = 'partial'
      THEN 'Preserved every physically present event; missing hours remain unavailable, not zero.'
    END,
    preserved_count
  )
  ON CONFLICT (bucket_date) DO UPDATE SET
    raw_window_start = EXCLUDED.raw_window_start,
    raw_window_end = EXCLUDED.raw_window_end,
    cutoff_at = EXCLUDED.cutoff_at,
    coverage_state = EXCLUDED.coverage_state,
    catalogue_basis = EXCLUDED.catalogue_basis,
    reconciled_at = now(),
    notes = EXCLUDED.notes,
    preserved_row_count = EXCLUDED.preserved_row_count;
END;
$$;


ALTER FUNCTION "analytics_private"."reconcile_daily_actions"("target_day" "date", "cutoff_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics_private"."reconcile_due_days"("cutoff_at" timestamp with time zone DEFAULT "now"()) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
  first_day date := ((cutoff_at - interval '90 days') AT TIME ZONE 'America/Chicago')::date;
  last_day date := ((cutoff_at AT TIME ZONE 'America/Chicago')::date - 1);
  day_cursor date;
  run_id bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('analytics-reconcile-batch'));
  IF last_day < first_day THEN RETURN; END IF;

  INSERT INTO public.analytics_reconciliation_runs (
    from_day, through_day, cutoff_at, status
  ) VALUES (first_day, last_day, cutoff_at, 'running')
  RETURNING id INTO run_id;

  BEGIN
    day_cursor := first_day;
    WHILE day_cursor <= last_day LOOP
      PERFORM analytics_private.reconcile_daily_actions(day_cursor, cutoff_at);
      day_cursor := day_cursor + 1;
    END LOOP;
    UPDATE public.analytics_reconciliation_runs
    SET status = 'complete', completed_at = now()
    WHERE id = run_id;
  EXCEPTION WHEN OTHERS THEN
    UPDATE public.analytics_reconciliation_runs
    SET status = 'failed', completed_at = now(), error_message = SQLERRM
    WHERE id = run_id;
    RAISE WARNING 'analytics reconciliation run % failed: %', run_id, SQLERRM;
    RETURN;
  END;
END;
$$;


ALTER FUNCTION "analytics_private"."reconcile_due_days"("cutoff_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics_private"."record_initial_classification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
BEGIN
  INSERT INTO public.engagement_event_classifications (
    engagement_event_id, classification, reason_flags, classified_by
  ) VALUES (
    NEW.id,
    CASE NEW.traffic_context
      WHEN 'operator' THEN 'operator'
      WHEN 'test' THEN 'test'
      ELSE 'audience'
    END,
    CASE WHEN NEW.traffic_context = 'audience' THEN ARRAY['collector_accepted']::text[]
      ELSE ARRAY['trusted_context']::text[] END,
    'collector'
  ) ON CONFLICT (engagement_event_id) DO NOTHING;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "analytics_private"."record_initial_classification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics_private"."refresh_site_action_summaries"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
  previous_cutoff timestamptz;
  refreshed_at timestamptz;
  summary_cutoff timestamptz := clock_timestamp();
  failure_code text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('analytics-site-action-summary-refresh'));
  -- Retention hands raw rows to archives atomically relative to this rebuild.
  PERFORM pg_advisory_xact_lock(hashtext('analytics-v2-prune'));

  BEGIN
    SELECT summary_cutoff_at INTO previous_cutoff
    FROM public.analytics_site_action_summary_status
    WHERE report_name = 'site_actions'
    FOR UPDATE;

    IF current_setting('analytics.site_actions_refresh_force_failure', true) = 'on' THEN
      RAISE EXCEPTION 'scheduled-site-refresh-test-failure' USING ERRCODE = 'P0001';
    END IF;

    -- Reconcile every retained raw observation so a later classification or browser
    -- revocation changes the stored result. Archive rows are revisited only when their
    -- source row changed since the prior successful refresh.
    DELETE FROM public.analytics_site_action_daily d
    WHERE d.bucket_date IN (
      SELECT DISTINCT (e.occurred_at AT TIME ZONE 'UTC')::date
      FROM public.analytics_events_v2 e
      WHERE e.event_name IN ('site_page_viewed','site_link_clicked','content_progressed','content_active_time','demo_section_viewed')
        AND e.received_at <= summary_cutoff AND e.occurred_at <= summary_cutoff
      UNION
      SELECT DISTINCT a.bucket_date
      FROM public.analytics_v2_archived_totals a
      WHERE a.event_name IN ('site_page_viewed','site_link_clicked','content_progressed','content_active_time','demo_section_viewed')
        AND a.updated_at <= summary_cutoff
        AND (previous_cutoff IS NULL OR a.updated_at > previous_cutoff)
    );

    WITH affected_days AS (
      SELECT DISTINCT (e.occurred_at AT TIME ZONE 'UTC')::date AS bucket_date
      FROM public.analytics_events_v2 e
      WHERE e.event_name IN ('site_page_viewed','site_link_clicked','content_progressed','content_active_time','demo_section_viewed')
        AND e.received_at <= summary_cutoff AND e.occurred_at <= summary_cutoff
      UNION
      SELECT DISTINCT a.bucket_date
      FROM public.analytics_v2_archived_totals a
      WHERE a.event_name IN ('site_page_viewed','site_link_clicked','content_progressed','content_active_time','demo_section_viewed')
        AND a.updated_at <= summary_cutoff
        AND (previous_cutoff IS NULL OR a.updated_at > previous_cutoff)
    ), observations AS (
      SELECT
        (e.occurred_at AT TIME ZONE 'UTC')::date AS bucket_date,
        e.properties->>'site_section' AS section,
        e.properties->>'canonical_path' AS path,
        e.event_name,
        e.properties AS dimensions,
        CASE
          WHEN r.anonymous_browser_id IS NOT NULL THEN 'self_excluded'
          WHEN e.traffic_context <> 'audience' THEN e.traffic_context
          ELSE coalesce(c.classification, e.traffic_context)
        END AS context,
        1::bigint AS event_count,
        e.occurred_at AS first_recorded_at,
        e.occurred_at AS last_recorded_at
      FROM public.analytics_events_v2 e
      LEFT JOIN LATERAL (
        SELECT c.classification
        FROM public.analytics_event_v2_classifications c
        WHERE c.event_id = e.event_id
        ORDER BY c.classification_version DESC
        LIMIT 1
      ) c ON true
      LEFT JOIN analytics_private.analytics_v2_revoked_browsers r
        ON r.anonymous_browser_id = e.anonymous_browser_id
      WHERE e.event_name IN ('site_page_viewed','site_link_clicked','content_progressed','content_active_time','demo_section_viewed')
        AND e.received_at <= summary_cutoff AND e.occurred_at <= summary_cutoff
        AND (e.occurred_at AT TIME ZONE 'UTC')::date IN (SELECT bucket_date FROM affected_days)

      UNION ALL

      SELECT
        a.bucket_date,
        a.dimensions->>'site_section' AS section,
        a.dimensions->>'canonical_path' AS path,
        a.event_name,
        a.dimensions,
        a.traffic_context AS context,
        a.event_count,
        a.last_recorded_at AS first_recorded_at,
        a.last_recorded_at
      FROM public.analytics_v2_archived_totals a
      WHERE a.event_name IN ('site_page_viewed','site_link_clicked','content_progressed','content_active_time','demo_section_viewed')
        AND a.updated_at <= summary_cutoff
        AND a.bucket_date IN (SELECT bucket_date FROM affected_days)
    )
    INSERT INTO public.analytics_site_action_daily (
      bucket_date, section, path,
      page_views, contact_clicks, external_clicks, reading_90, active_30, demo_last_section,
      excluded_events, first_recorded_at, last_recorded_at
    )
    SELECT
      bucket_date,
      section,
      path,
      coalesce(sum(event_count) FILTER (WHERE context IN ('audience','unclassified') AND event_name = 'site_page_viewed'), 0),
      coalesce(sum(event_count) FILTER (WHERE context IN ('audience','unclassified') AND event_name = 'site_link_clicked' AND dimensions->>'target_kind' IN ('email','phone')), 0),
      coalesce(sum(event_count) FILTER (WHERE context IN ('audience','unclassified') AND event_name = 'site_link_clicked' AND dimensions->>'target_kind' = 'external'), 0),
      coalesce(sum(event_count) FILTER (WHERE context IN ('audience','unclassified') AND event_name = 'content_progressed' AND dimensions->>'threshold' = '90'), 0),
      coalesce(sum(event_count) FILTER (WHERE context IN ('audience','unclassified') AND event_name = 'content_active_time' AND dimensions->>'threshold' = '30'), 0),
      coalesce(sum(event_count) FILTER (WHERE context IN ('audience','unclassified') AND event_name = 'demo_section_viewed' AND dimensions->>'position' = dimensions->>'section_count'), 0),
      coalesce(sum(event_count) FILTER (WHERE context NOT IN ('audience','unclassified')), 0),
      min(first_recorded_at),
      max(last_recorded_at)
    FROM observations
    WHERE section IN ('profile','writing','demos','photography','other')
      AND path IS NOT NULL
    GROUP BY bucket_date, section, path;

    refreshed_at := clock_timestamp();
    UPDATE public.analytics_site_action_summary_status
    SET initialized_at = coalesce(initialized_at, refreshed_at),
        last_successful_at = refreshed_at,
        summary_cutoff_at = summary_cutoff,
        last_error_at = NULL,
        last_error_code = NULL
    WHERE report_name = 'site_actions';

    RETURN jsonb_build_object('ok', true, 'refreshed_at', refreshed_at);
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS failure_code = RETURNED_SQLSTATE;
    UPDATE public.analytics_site_action_summary_status
    SET last_error_at = clock_timestamp(), last_error_code = failure_code
    WHERE report_name = 'site_actions';
    RETURN jsonb_build_object('ok', false, 'error_code', failure_code);
  END;
END;
$$;


ALTER FUNCTION "analytics_private"."refresh_site_action_summaries"() OWNER TO "postgres";


COMMENT ON FUNCTION "analytics_private"."refresh_site_action_summaries"() IS 'Fixed-path atomic reconciliation. The status receipt advances only after stored summaries are rebuilt.';



