CREATE OR REPLACE FUNCTION "public"."analytics_claim_intelligence_deliveries"("p_limit" integer, "p_lease_seconds" integer) RETURNS TABLE("id" "uuid", "channel" "text", "sender" "text", "destinationVerified" boolean, "preferenceEnabled" boolean, "idempotencyKey" "text", "payload" "jsonb", "destination" "jsonb")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_limit NOT BETWEEN 1 AND 20 OR p_lease_seconds NOT BETWEEN 30 AND 900 THEN RAISE EXCEPTION 'invalid intelligence delivery claim'; END IF;
  -- Re-read the owner's current choice before claiming any queued email.
  -- A queued snapshot cannot override a later opt-out or changed destination.
  UPDATE public.analytics_intelligence_deliveries d SET status='suppressed',error_code='preference_changed',updated_at=clock_timestamp()
  WHERE d.status='pending' AND d.channel='email' AND NOT EXISTS (
    SELECT 1 FROM public.analytics_intelligence_briefs b JOIN public.analytics_intelligence_preferences p ON p.owner_id=b.owner_id
    WHERE b.id=d.brief_id AND p.external_enabled AND p.retention_policy IN ('days','until_deleted')
      AND p.destination_verified AND p.destination_verified_at IS NOT NULL AND p.sender=d.sender
      AND lower(p.destination)=lower(d.destination->>'address')
      AND (d.destination->>'verifiedAt')::timestamptz=p.destination_verified_at
  );
  -- An expired lease might have reached a provider. Preserve ambiguity for a
  -- deliberate reconciliation; never silently send it again.
  UPDATE public.analytics_intelligence_deliveries SET status='ambiguous',leased_until=NULL,error_code='lease_expired',updated_at=clock_timestamp()
  WHERE status='leased' AND leased_until<clock_timestamp();
  RETURN QUERY WITH candidates AS (
    SELECT d.id FROM public.analytics_intelligence_deliveries d WHERE d.status='pending' AND d.available_at<=clock_timestamp() ORDER BY d.available_at,d.created_at FOR UPDATE SKIP LOCKED LIMIT p_limit
  ), claimed AS (
    UPDATE public.analytics_intelligence_deliveries d SET status='leased',leased_until=clock_timestamp()+make_interval(secs=>p_lease_seconds),attempts=d.attempts+1,updated_at=clock_timestamp() FROM candidates c WHERE d.id=c.id RETURNING d.*
  ) SELECT c.id,c.channel,c.sender,c.destination_verified,c.preference_enabled,c.idempotency_key,c.payload,c.destination FROM claimed c;
END $$;


ALTER FUNCTION "public"."analytics_claim_intelligence_deliveries"("p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_claim_intelligence_jobs"("p_limit" integer, "p_lease_seconds" integer, "p_now" timestamp with time zone) RETURNS TABLE("id" "uuid", "kind" "text", "scope" "jsonb", "ownerId" "uuid", "intendedPeriod" "date", "late" boolean, "requestId" "uuid", "operation" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_limit NOT BETWEEN 1 AND 4 OR p_lease_seconds NOT BETWEEN 30 AND 900 OR p_now IS NULL THEN RAISE EXCEPTION 'invalid intelligence job claim'; END IF;
  UPDATE public.analytics_intelligence_requests SET status='expired',updated_at=p_now
    WHERE status IN ('pending','leased') AND expires_at<=p_now;
  UPDATE public.analytics_intelligence_jobs j SET status='expired',leased_until=NULL,error_code='request_expired',updated_at=p_now
    FROM public.analytics_intelligence_requests r WHERE j.request_id=r.id AND r.status='expired' AND j.status IN ('pending','retry','leased');
  UPDATE public.analytics_intelligence_jobs SET status='unavailable',error_code='attempts_exhausted',leased_until=NULL,updated_at=p_now
    WHERE status IN ('pending','retry') AND attempts>=20;
  RETURN QUERY WITH candidates AS (
    SELECT j.id FROM public.analytics_intelligence_jobs j
    LEFT JOIN public.analytics_intelligence_requests r ON r.id=j.request_id
    WHERE ((j.status IN ('pending','retry') AND j.available_at<=p_now) OR (j.status='leased' AND j.leased_until<p_now))
      AND j.attempts<20 AND (j.kind<>'request' OR (r.status IN ('pending','leased') AND r.expires_at>p_now))
    ORDER BY CASE WHEN j.kind='request' THEN 0 WHEN j.kind IN ('daily','weekly') AND j.intended_period=(p_now AT TIME ZONE 'America/Chicago')::date THEN 1 WHEN j.kind='refresh' THEN 2 ELSE 3 END,
      CASE WHEN j.kind IN ('daily','weekly') THEN j.intended_period END DESC NULLS LAST, j.available_at, j.created_at
    FOR UPDATE OF j SKIP LOCKED LIMIT p_limit
  ), claimed AS (
    UPDATE public.analytics_intelligence_jobs j SET status='leased',leased_until=p_now+make_interval(secs=>p_lease_seconds),attempts=j.attempts+1,updated_at=p_now
    FROM candidates c WHERE j.id=c.id RETURNING j.*
  ), request_leases AS (
    UPDATE public.analytics_intelligence_requests r SET status='leased',updated_at=p_now FROM claimed c
    WHERE r.id=c.request_id AND r.status IN ('pending','leased') AND r.expires_at>p_now
  ) SELECT c.id,c.kind,c.scope,c.owner_id,c.intended_period,
    (c.intended_period IS NOT NULL AND p_now>(c.intended_period::timestamp AT TIME ZONE 'America/Chicago')+interval '8 hours'),c.request_id,c.operation FROM claimed c;
END $$;


ALTER FUNCTION "public"."analytics_claim_intelligence_jobs"("p_limit" integer, "p_lease_seconds" integer, "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_claim_posthog_events"("p_limit" integer, "p_lease_seconds" integer) RETURNS TABLE("event_id" "uuid", "payload" "jsonb", "attempts" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF current_user <> 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 RETURN QUERY WITH claimed AS (
  SELECT o.event_id FROM public.analytics_posthog_outbox o
  LEFT JOIN public.analytics_events_v2 e ON e.event_id=o.event_id
  LEFT JOIN LATERAL (
    SELECT c.classification FROM public.analytics_event_v2_classifications c
    WHERE c.event_id=e.event_id ORDER BY c.classification_version DESC LIMIT 1
  ) c ON true
  WHERE o.status IN ('pending','failed') AND o.attempts < 12 AND o.next_attempt_at<=now()
    AND (o.locked_until IS NULL OR o.locked_until<now())
    AND (
      o.origin='classification_control'
      OR (e.export_eligible AND e.traffic_context='audience' AND coalesce(c.classification,e.traffic_context) IN ('audience','unclassified'))
    )
  ORDER BY o.next_attempt_at,o.event_id FOR UPDATE OF o SKIP LOCKED
  LIMIT LEAST(GREATEST(p_limit,1),100)
 ), delivered AS (UPDATE public.analytics_posthog_outbox o
 SET locked_until=now()+make_interval(secs=>LEAST(GREATEST(p_lease_seconds,1),300)),attempts=o.attempts+1
 FROM claimed WHERE o.event_id=claimed.event_id RETURNING o.event_id,o.payload,o.attempts), marked AS (
 UPDATE public.analytics_events_v2 e SET posthog_attempted_at=coalesce(e.posthog_attempted_at,now()) FROM delivered d WHERE e.event_id=d.event_id RETURNING e.event_id
 ) SELECT d.event_id,d.payload,d.attempts FROM delivered d;
END $$;


ALTER FUNCTION "public"."analytics_claim_posthog_events"("p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_cleanup_intelligence_private"("p_now" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_now IS NULL THEN RAISE EXCEPTION 'invalid intelligence cleanup time'; END IF;
  DELETE FROM public.analytics_intelligence_outcomes o
  USING public.analytics_intelligence_preferences p
  WHERE p.owner_id = o.owner_id AND p.retention_policy = 'days'
    AND o.created_at < p_now - make_interval(days => p.retention_days);
  DELETE FROM public.analytics_intelligence_actions a
  USING public.analytics_intelligence_preferences p
  WHERE p.owner_id = a.owner_id AND p.retention_policy = 'days'
    AND a.created_at < p_now - make_interval(days => p.retention_days);
  DELETE FROM public.analytics_intelligence_finding_lifecycle l USING public.analytics_intelligence_preferences p
  WHERE p.owner_id=l.owner_id AND p.retention_policy='days' AND l.updated_at < p_now-make_interval(days=>p.retention_days);
  DELETE FROM public.analytics_intelligence_jobs j USING public.analytics_intelligence_requests r
  WHERE j.request_id=r.id AND r.expires_at<p_now;
  DELETE FROM public.analytics_intelligence_requests WHERE expires_at<p_now;
  DELETE FROM public.analytics_intelligence_jobs j USING public.analytics_intelligence_preferences p
  WHERE p.owner_id=j.owner_id AND p.retention_policy='days' AND j.created_at < p_now-make_interval(days=>p.retention_days);
  DELETE FROM public.analytics_intelligence_briefs b
  USING public.analytics_intelligence_preferences p
  WHERE p.owner_id = b.owner_id AND p.retention_policy = 'days'
    AND b.created_at < p_now - make_interval(days => p.retention_days);
END;
$$;


ALTER FUNCTION "public"."analytics_cleanup_intelligence_private"("p_now" timestamp with time zone) OWNER TO "postgres";


