CREATE OR REPLACE FUNCTION "public"."analytics_count_distinct_visitors"("p_start" "date", "p_end" "date", "p_album_keys" "text"[], "p_sport" "text", "p_category" "text", "p_source" "text", "p_event_date" "date", "p_season" "text", "p_album_event_type" "text", "p_measure" "text", "p_traffic" "text") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
  SELECT analytics_private.count_distinct_visitors(
    p_start, p_end, p_album_keys, p_sport, p_category, p_source,
    p_event_date, p_season, p_album_event_type, p_measure, p_traffic
  );
$$;


ALTER FUNCTION "public"."analytics_count_distinct_visitors"("p_start" "date", "p_end" "date", "p_album_keys" "text"[], "p_sport" "text", "p_category" "text", "p_source" "text", "p_event_date" "date", "p_season" "text", "p_album_event_type" "text", "p_measure" "text", "p_traffic" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_count_scheduled_gallery_browsers"("p_start" "date", "p_end" "date", "p_album_keys" "text"[], "p_sport" "text", "p_category" "text", "p_source" "text", "p_event_date" "date", "p_season" "text", "p_album_event_type" "text", "p_measure" "text", "p_traffic" "text", "p_public_only" boolean) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
  interval_start timestamptz := p_start::timestamp AT TIME ZONE 'America/Chicago';
  interval_end timestamptz := (p_end + 1)::timestamp AT TIME ZONE 'America/Chicago';
  answer bigint;
BEGIN
  IF p_start > p_end
    OR interval_start < now() - interval '90 days'
    OR interval_end > now()
  THEN RETURN NULL;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM generate_series(p_start, p_end, interval '1 day') day
    LEFT JOIN public.analytics_daily_coverage coverage
      ON coverage.bucket_date = day::date
    WHERE coverage.bucket_date IS NULL
      OR coverage.raw_window_start > day::date::timestamp AT TIME ZONE 'America/Chicago'
      OR coverage.raw_window_end < (day::date + 1)::timestamp AT TIME ZONE 'America/Chicago'
      OR coverage.coverage_state <> 'complete'
      OR coverage.frozen_at IS NOT NULL
  ) THEN RETURN NULL;
  END IF;

  SELECT count(DISTINCT e.session_hash) INTO answer
  FROM analytics_private.effective_engagement_events e
  WHERE (e.created_at AT TIME ZONE 'America/Chicago')::date BETWEEN p_start AND p_end
    AND e.session_hash IS NOT NULL
    AND (NOT p_public_only OR EXISTS (
      SELECT 1 FROM public.albums a LEFT JOIN public.album_settings s USING(album_key)
      WHERE a.album_key=e.resolved_album_key AND coalesce(s.visibility,'public')<>'unlisted'))
    AND (NOT p_public_only OR coalesce(e.photo_id,'')='' OR EXISTS (
      SELECT 1 FROM public.photo_metadata m WHERE m.photo_id=e.photo_id AND m.album_key=e.resolved_album_key))
    AND (coalesce(cardinality(p_album_keys), 0) = 0 OR e.resolved_album_key = ANY(p_album_keys))
    AND (p_sport IS NULL OR e.snapshot_sport = p_sport)
    AND (p_category IS NULL OR e.snapshot_photo_category = p_category)
    AND (p_source IS NULL OR coalesce(e.source, 'direct') = p_source)
    AND (p_event_date IS NULL OR e.snapshot_event_date = p_event_date)
    AND (p_season IS NULL OR coalesce(extract(year FROM e.snapshot_event_date)::text,'unknown') = p_season)
    AND (p_album_event_type IS NULL OR e.snapshot_album_event_type = p_album_event_type)
    AND (p_traffic = 'inclusive' OR e.effective_classification IN ('audience', 'unclassified'));
  RETURN answer;
END;
$$;


ALTER FUNCTION "public"."analytics_count_scheduled_gallery_browsers"("p_start" "date", "p_end" "date", "p_album_keys" "text"[], "p_sport" "text", "p_category" "text", "p_source" "text", "p_event_date" "date", "p_season" "text", "p_album_event_type" "text", "p_measure" "text", "p_traffic" "text", "p_public_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_delete_intelligence_private_history"("p_owner_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  IF p_owner_id IS NULL THEN RAISE EXCEPTION 'invalid intelligence history owner'; END IF;

  -- Deliveries, requests, jobs, and action children are removed before their
  -- private parents. Aggregate snapshots and visitor/audience data are absent
  -- from this transaction by design.
  DELETE FROM public.analytics_intelligence_outcomes WHERE owner_id = p_owner_id;

  LOOP
    DELETE FROM public.analytics_intelligence_actions a
    WHERE a.owner_id = p_owner_id
      AND NOT EXISTS (
        SELECT 1 FROM public.analytics_intelligence_actions child
        WHERE child.reverses_action_id = a.id AND child.owner_id = p_owner_id
      );
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    EXIT WHEN v_deleted = 0;
  END LOOP;

  IF EXISTS (SELECT 1 FROM public.analytics_intelligence_actions WHERE owner_id = p_owner_id) THEN
    RAISE EXCEPTION 'intelligence action history cannot be safely removed';
  END IF;

  DELETE FROM public.analytics_intelligence_finding_lifecycle WHERE owner_id = p_owner_id;
  DELETE FROM public.analytics_intelligence_deliveries d
  USING public.analytics_intelligence_briefs b
  WHERE d.brief_id = b.id AND b.owner_id = p_owner_id;
  DELETE FROM public.analytics_intelligence_briefs WHERE owner_id = p_owner_id;
  DELETE FROM public.analytics_intelligence_jobs WHERE owner_id = p_owner_id;
  DELETE FROM public.analytics_intelligence_requests WHERE owner_id = p_owner_id;

  -- Preferences remain. Turning schedules and external delivery off prevents
  -- a deleted history from being immediately recreated.
  UPDATE public.analytics_intelligence_preferences
  SET external_enabled = false, updated_at = clock_timestamp()
  WHERE owner_id = p_owner_id;
  INSERT INTO public.analytics_intelligence_schedules(owner_id, daily_enabled, weekly_enabled)
  VALUES (p_owner_id, false, false)
  ON CONFLICT(owner_id) DO UPDATE
    SET daily_enabled = false, weekly_enabled = false, updated_at = clock_timestamp();
END;
$$;


ALTER FUNCTION "public"."analytics_delete_intelligence_private_history"("p_owner_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_finish_intelligence_delivery"("p_delivery_id" "uuid", "p_status" "text", "p_error_code" "text", "p_provider_message_id" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_status NOT IN ('shown','accepted','suppressed','failed','ambiguous') THEN RAISE EXCEPTION 'invalid intelligence delivery status'; END IF;
  UPDATE public.analytics_intelligence_deliveries SET status=p_status, error_code=p_error_code, provider_message_id=p_provider_message_id, leased_until=NULL, available_at=CASE WHEN p_status='failed' THEN clock_timestamp()+interval '5 minutes' ELSE available_at END, updated_at=clock_timestamp() WHERE id=p_delivery_id AND status='leased';
  IF NOT FOUND THEN RAISE EXCEPTION 'intelligence delivery is not leased'; END IF;
END $$;


ALTER FUNCTION "public"."analytics_finish_intelligence_delivery"("p_delivery_id" "uuid", "p_status" "text", "p_error_code" "text", "p_provider_message_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_finish_intelligence_job"("p_job_id" "uuid", "p_status" "text", "p_report_id" "uuid", "p_error_code" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE j public.analytics_intelligence_jobs%ROWTYPE; snapshot_scope text; delay_seconds integer; brief_id uuid; aggregate_findings jsonb; aggregate_ids jsonb; aggregate_windows jsonb; aggregate_suppressions jsonb; brief_body text; should_notify boolean;
BEGIN
  IF p_status NOT IN ('complete','retry') OR p_job_id IS NULL THEN RAISE EXCEPTION 'invalid intelligence job finish'; END IF;
  SELECT * INTO j FROM public.analytics_intelligence_jobs WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND OR j.status <> 'leased' THEN RAISE EXCEPTION 'intelligence job is not leased'; END IF;
  SELECT scope_key INTO snapshot_scope FROM public.analytics_intelligence_snapshots WHERE snapshot_id=p_report_id;
  IF p_status='complete' AND (p_report_id IS NULL OR snapshot_scope IS DISTINCT FROM j.scope_key) THEN RAISE EXCEPTION 'immutable report does not match job scope'; END IF;
  delay_seconds:=CASE WHEN p_error_code='provider_query_pending' THEN 300 ELSE least(3600,30*(2^least(j.attempts,6))) END;
  UPDATE public.analytics_intelligence_jobs SET status=CASE WHEN p_status='complete' THEN 'complete' WHEN attempts>=20 THEN 'unavailable' ELSE 'retry' END,
    report_id=coalesce(p_report_id,report_id),error_code=CASE WHEN p_status='complete' THEN error_code ELSE coalesce(p_error_code,'intelligence_refresh_unavailable') END,
    leased_until=NULL,available_at=CASE WHEN p_status='complete' THEN available_at ELSE clock_timestamp()+make_interval(secs=>delay_seconds) END,updated_at=clock_timestamp() WHERE id=p_job_id;
  IF j.kind IN ('daily','weekly') AND j.owner_id IS NOT NULL THEN
    -- Publish once every scoped job is terminal.  A bounded unavailable scope is
    -- named in the immutable brief; it must not make the period hang forever.
    IF EXISTS(SELECT 1 FROM public.analytics_intelligence_jobs WHERE owner_id=j.owner_id AND kind=j.kind AND intended_period=j.intended_period AND status NOT IN ('complete','unavailable','expired')) THEN RETURN; END IF;
    SELECT coalesce(jsonb_agg(DISTINCT f.value),'[]'::jsonb) INTO aggregate_findings
    FROM public.analytics_intelligence_jobs jobs JOIN public.analytics_intelligence_snapshots snapshot ON snapshot.snapshot_id=jobs.report_id
    CROSS JOIN LATERAL jsonb_array_elements(snapshot.findings) f(value)
    WHERE jobs.owner_id=j.owner_id AND jobs.kind=j.kind AND jobs.intended_period=j.intended_period AND jobs.status='complete';
    SELECT coalesce(jsonb_agg(DISTINCT jobs.report_id),'[]'::jsonb),coalesce(jsonb_agg(DISTINCT jsonb_build_object('snapshotId',snapshot.snapshot_id,'scope',snapshot.scope,'current',CASE WHEN snapshot.scope->>'kind'='gallery' THEN jsonb_build_object('start',snapshot.scope->'query'->>'start','end',snapshot.scope->'query'->>'end') ELSE snapshot.evidence->'siteWindows'->'current' END,'previous',CASE WHEN snapshot.scope->>'kind'='gallery' AND snapshot.scope#>>'{query,compare}'='previous' THEN jsonb_build_object('start',((snapshot.scope#>>'{query,start}')::date-((snapshot.scope#>>'{query,end}')::date-(snapshot.scope#>>'{query,start}')::date+1))::text,'end',((snapshot.scope#>>'{query,start}')::date-1)::text) ELSE snapshot.evidence->'siteWindows'->'previous' END,'cutoff',snapshot.cutoff_at,'timezone',CASE WHEN snapshot.scope->>'kind'='gallery' THEN 'America/Chicago' ELSE 'UTC' END)),'[]'::jsonb)
    INTO aggregate_ids,aggregate_windows FROM public.analytics_intelligence_jobs jobs JOIN public.analytics_intelligence_snapshots snapshot ON snapshot.snapshot_id=jobs.report_id
    WHERE jobs.owner_id=j.owner_id AND jobs.kind=j.kind AND jobs.intended_period=j.intended_period AND jobs.status='complete';
    SELECT coalesce(jsonb_agg(DISTINCT f.value),'[]'::jsonb) INTO aggregate_suppressions
    FROM public.analytics_intelligence_jobs jobs JOIN public.analytics_intelligence_snapshots snapshot ON snapshot.snapshot_id=jobs.report_id
    CROSS JOIN LATERAL jsonb_array_elements(snapshot.suppressions) f(value)
    WHERE jobs.owner_id=j.owner_id AND jobs.kind=j.kind AND jobs.intended_period=j.intended_period AND jobs.status='complete';
    SELECT coalesce(aggregate_suppressions,'[]'::jsonb) || coalesce(jsonb_agg(jsonb_build_object('rule','collection_health','scope',jobs.scope,'reason','Unavailable '||(jobs.scope->>'kind')||' source: '||coalesce(jobs.scope->>'section',jobs.scope#>>'{query,scope}','all')||' ('||coalesce(jobs.error_code,jobs.status)||')','coverage','unavailable')),'[]'::jsonb)
      INTO aggregate_suppressions FROM public.analytics_intelligence_jobs jobs
      WHERE jobs.owner_id=j.owner_id AND jobs.kind=j.kind AND jobs.intended_period=j.intended_period AND jobs.status IN ('unavailable','expired');
    SELECT string_agg((value->>'title') || E'\n' || (value->>'explanation') || E'\n' || (value->>'action'),E'\n\n') INTO brief_body
    FROM (SELECT value FROM jsonb_array_elements(aggregate_findings) ORDER BY CASE value->>'severity' WHEN 'high' THEN 0 WHEN 'medium' THEN 1 ELSE 2 END,value->>'id' LIMIT 6) shortlist;
    brief_body:=left(coalesce(brief_body,'The saved evidence does not support an actionable finding. Review the report limits before interpreting this as quiet traffic.'),11000)||E'\n\nOpen https://analytics.ninochavez.co/ for the full evidence, windows, and limitations.';
    SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(aggregate_findings) f WHERE NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(coalesce((SELECT b.findings FROM public.analytics_intelligence_briefs b WHERE b.owner_id=j.owner_id AND b.kind=j.kind AND b.period_key<j.intended_period ORDER BY b.period_key DESC LIMIT 1),'[]'::jsonb)) prior
      WHERE prior->>'id'=f->>'id'
    )) AND j.intended_period>=CASE WHEN j.kind='daily' THEN (clock_timestamp() AT TIME ZONE 'America/Chicago')::date ELSE date_trunc('week',clock_timestamp() AT TIME ZONE 'America/Chicago')::date END INTO should_notify;
    INSERT INTO public.analytics_intelligence_briefs(owner_id,scope_key,snapshot_id,period_key,kind,late,body,findings,snapshot_ids,source_windows,suppressions)
    VALUES(j.owner_id,NULL,p_report_id,j.intended_period,j.kind,clock_timestamp()>(j.intended_period::timestamp AT TIME ZONE 'America/Chicago')+interval '8 hours',brief_body,aggregate_findings,aggregate_ids,aggregate_windows,aggregate_suppressions)
    ON CONFLICT(owner_id,period_key,kind) WHERE kind IN ('daily','weekly') DO NOTHING RETURNING id INTO brief_id;
    IF brief_id IS NULL THEN RETURN; END IF;
    INSERT INTO public.analytics_intelligence_deliveries(brief_id,channel,sender,destination_verified,preference_enabled,idempotency_key,payload,destination)
    VALUES(brief_id,'dashboard','owned',false,true,'dashboard:'||brief_id::text,jsonb_build_object('subject',initcap(j.kind)||' analytics review','body',brief_body),NULL) ON CONFLICT(idempotency_key) DO NOTHING;
    INSERT INTO public.analytics_intelligence_deliveries(brief_id,channel,sender,destination_verified,preference_enabled,idempotency_key,payload,destination,status,error_code)
    SELECT brief_id,'email',p.sender,true,true,'email:'||brief_id::text,jsonb_build_object('subject',initcap(j.kind)||' analytics review','body',brief_body),jsonb_build_object('channel','email','address',p.destination,'verifiedAt',p.destination_verified_at),CASE WHEN should_notify THEN 'pending' ELSE 'suppressed' END,CASE WHEN should_notify THEN NULL ELSE 'no_new_actionable_information_or_obsolete_period' END
    FROM public.analytics_intelligence_preferences p WHERE p.owner_id=j.owner_id AND p.external_enabled AND p.destination_verified AND p.destination_verified_at IS NOT NULL AND p.destination IS NOT NULL AND p.sender IN ('owned','posthog_native') ON CONFLICT(idempotency_key) DO NOTHING;
  END IF;
  IF j.request_id IS NOT NULL AND p_status='retry' AND j.attempts>=20 THEN UPDATE public.analytics_intelligence_requests SET status='unavailable',updated_at=clock_timestamp() WHERE id=j.request_id AND status IN ('pending','leased'); END IF;
END $$;


ALTER FUNCTION "public"."analytics_finish_intelligence_job"("p_job_id" "uuid", "p_status" "text", "p_report_id" "uuid", "p_error_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_finish_posthog_delivery"("p_event_id" "uuid", "p_status" "text", "p_error_code" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF current_user <> 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 IF p_status NOT IN ('submitted','failed') THEN RAISE EXCEPTION 'invalid status' USING ERRCODE='22023'; END IF;
 UPDATE public.analytics_posthog_outbox
 SET status=p_status,
     locked_until=NULL,
     last_error_code=left(p_error_code,120),
     submitted_at=CASE WHEN p_status='submitted' THEN now() ELSE submitted_at END,
     next_attempt_at=CASE WHEN p_status='failed' THEN now()+make_interval(secs=>LEAST(3600,2^LEAST(attempts,10))) ELSE next_attempt_at END
 WHERE event_id=p_event_id;
END $$;


ALTER FUNCTION "public"."analytics_finish_posthog_delivery"("p_event_id" "uuid", "p_status" "text", "p_error_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_intelligence_action_follow_up"("p_target" "jsonb", "p_primary_measure" "text", "p_actual_at" timestamp with time zone, "p_observation_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE gallery_target boolean; tz text; action_day date; before_start date; before_end date; after_start date; after_end date; after_complete_at timestamptz; before_coverage text; after_coverage text; before_count bigint; after_count bigint; site_complete_through date;
BEGIN
  IF p_target IS NULL OR jsonb_typeof(p_target)<>'object' OR p_target->>'kind' NOT IN ('gallery','album','photo','site','page') OR p_primary_measure NOT IN ('photo_opens','album_opens','downloads','favorites','shares','page_views') OR p_actual_at IS NULL OR p_observation_days NOT BETWEEN 1 AND 365 THEN RAISE EXCEPTION 'invalid action follow-up'; END IF;
  gallery_target := p_target->>'kind' IN ('gallery','album','photo');
  IF gallery_target AND p_primary_measure='page_views' THEN RAISE EXCEPTION 'site measure cannot use gallery target'; END IF;
  IF NOT gallery_target AND p_primary_measure<>'page_views' THEN RAISE EXCEPTION 'gallery measure cannot use site target'; END IF;
  tz := CASE WHEN gallery_target THEN 'America/Chicago' ELSE 'UTC' END;
  action_day := (p_actual_at AT TIME ZONE tz)::date;
  before_start := action_day-p_observation_days; before_end := action_day-1;
  after_start := action_day+1; after_end := action_day+p_observation_days;
  -- The action day is excluded. A follow-up becomes eligible only after the
  -- final complete local calendar day in the after window, including DST.
  after_complete_at := ((after_end + 1)::timestamp AT TIME ZONE tz);
  IF gallery_target THEN
    SELECT CASE WHEN bool_or(coverage_state IS NULL OR coverage_state<>'complete') THEN CASE WHEN bool_or(coverage_state='partial') THEN 'partial' ELSE 'unavailable' END ELSE 'complete' END INTO before_coverage FROM generate_series(before_start,before_end,'1 day') d LEFT JOIN public.analytics_daily_coverage c ON c.bucket_date=d::date;
    SELECT CASE WHEN bool_or(coverage_state IS NULL OR coverage_state<>'complete') THEN CASE WHEN bool_or(coverage_state='partial') THEN 'partial' ELSE 'unavailable' END ELSE 'complete' END INTO after_coverage FROM generate_series(after_start,after_end,'1 day') d LEFT JOIN public.analytics_daily_coverage c ON c.bucket_date=d::date;
    IF before_coverage='complete' THEN SELECT coalesce(sum(action_count),0) INTO before_count FROM public.analytics_daily_actions d WHERE d.bucket_date BETWEEN before_start AND before_end AND (p_target->>'kind'='gallery' OR (p_target->>'kind'='album' AND d.album_key=p_target->>'albumKey') OR (p_target->>'kind'='photo' AND d.photo_id=p_target->>'id')) AND ((p_primary_measure='photo_opens' AND d.event_type='view' AND d.photo_id<>'') OR (p_primary_measure='album_opens' AND d.event_type='album_open' AND d.photo_id='') OR (p_primary_measure='downloads' AND d.event_type='download') OR (p_primary_measure='favorites' AND d.event_type='favorite') OR (p_primary_measure='shares' AND d.event_type='share')); END IF;
    IF after_coverage='complete' THEN SELECT coalesce(sum(action_count),0) INTO after_count FROM public.analytics_daily_actions d WHERE d.bucket_date BETWEEN after_start AND after_end AND (p_target->>'kind'='gallery' OR (p_target->>'kind'='album' AND d.album_key=p_target->>'albumKey') OR (p_target->>'kind'='photo' AND d.photo_id=p_target->>'id')) AND ((p_primary_measure='photo_opens' AND d.event_type='view' AND d.photo_id<>'') OR (p_primary_measure='album_opens' AND d.event_type='album_open' AND d.photo_id='') OR (p_primary_measure='downloads' AND d.event_type='download') OR (p_primary_measure='favorites' AND d.event_type='favorite') OR (p_primary_measure='shares' AND d.event_type='share')); END IF;
  ELSE
    SELECT (summary_cutoff_at AT TIME ZONE 'UTC')::date-1 INTO site_complete_through FROM public.analytics_site_action_summary_status WHERE report_name='site_actions';
    before_coverage := CASE WHEN site_complete_through IS NULL OR before_end>site_complete_through THEN 'partial' ELSE 'complete' END;
    after_coverage := CASE WHEN site_complete_through IS NULL OR after_end>site_complete_through THEN 'partial' ELSE 'complete' END;
    IF before_coverage='complete' THEN SELECT coalesce(sum(page_views),0) INTO before_count FROM public.analytics_site_action_daily d WHERE d.bucket_date BETWEEN before_start AND before_end AND (p_target->>'kind'='site' OR d.path=p_target->>'id'); END IF;
    IF after_coverage='complete' THEN SELECT coalesce(sum(page_views),0) INTO after_count FROM public.analytics_site_action_daily d WHERE d.bucket_date BETWEEN after_start AND after_end AND (p_target->>'kind'='site' OR d.path=p_target->>'id'); END IF;
  END IF;
  RETURN jsonb_build_object('before',CASE WHEN before_coverage='complete' THEN before_count END,'after',CASE WHEN after_coverage='complete' THEN after_count END,'coverage',coalesce(after_coverage,'unavailable'),'previousCoverage',coalesce(before_coverage,'unavailable'),'measure',p_primary_measure,'availableAt',after_complete_at,'window',jsonb_build_object('before',jsonb_build_object('start',before_start,'end',before_end),'after',jsonb_build_object('start',after_start,'end',after_end),'timezone',tz));
END $$;


ALTER FUNCTION "public"."analytics_intelligence_action_follow_up"("p_target" "jsonb", "p_primary_measure" "text", "p_actual_at" timestamp with time zone, "p_observation_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_intelligence_incident_scope"("p_scope" "jsonb", "p_rule" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
 SELECT CASE WHEN p_rule='collection_health' THEN 'collection_health'
 WHEN p_rule='rendering_download_reliability' THEN 'flow:'||md5(((p_scope->'query')-ARRAY['start','end','measure','compare','compareStart','compareEnd'])::text)
 ELSE public.analytics_intelligence_scope_key(p_scope) END;
$$;


ALTER FUNCTION "public"."analytics_intelligence_incident_scope"("p_scope" "jsonb", "p_rule" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_intelligence_scope_key"("p_scope" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$ SELECT p_scope::text $$;


ALTER FUNCTION "public"."analytics_intelligence_scope_key"("p_scope" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_latest_intelligence_outcomes"("p_owner_id" "uuid", "p_action_ids" "uuid"[]) RETURNS TABLE("id" "uuid", "action_id" "uuid", "outcome" "text", "outcome_count" integer, "note" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_owner_id IS NULL
    OR coalesce(cardinality(p_action_ids), 0) NOT BETWEEN 1 AND 20
    OR EXISTS (SELECT 1 FROM unnest(p_action_ids) AS requested(id) WHERE requested.id IS NULL) THEN
    RAISE EXCEPTION 'invalid intelligence outcome query';
  END IF;

  RETURN QUERY
  SELECT DISTINCT ON (stored.action_id)
    stored.id, stored.action_id, stored.outcome, stored.outcome_count,
    stored.note, stored.created_at
  FROM public.analytics_intelligence_outcomes AS stored
  WHERE stored.owner_id = p_owner_id
    AND stored.action_id = ANY(p_action_ids)
  ORDER BY stored.action_id, stored.created_at DESC, stored.id DESC;
END;
$$;


ALTER FUNCTION "public"."analytics_latest_intelligence_outcomes"("p_owner_id" "uuid", "p_action_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_list_ambiguous_intelligence_deliveries"("p_limit" integer) RETURNS TABLE("id" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$ SELECT d.id FROM public.analytics_intelligence_deliveries d WHERE d.status='ambiguous' ORDER BY d.updated_at LIMIT least(greatest(p_limit,1),50) $$;


ALTER FUNCTION "public"."analytics_list_ambiguous_intelligence_deliveries"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_list_submitted_posthog_event_ids"("p_limit" integer) RETURNS TABLE("event_id" "uuid")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF current_user <> 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT o.event_id FROM public.analytics_posthog_outbox o
  WHERE o.status='submitted' AND o.submitted_at <= now()-interval '5 minutes'
    AND (o.origin='classification_control' OR EXISTS (
      SELECT 1 FROM public.analytics_events_v2 e
      LEFT JOIN LATERAL (SELECT classification FROM public.analytics_event_v2_classifications c WHERE c.event_id=e.event_id ORDER BY classification_version DESC LIMIT 1) c ON true
      WHERE e.event_id=o.event_id AND e.received_at >= now()-interval '90 days'
        AND e.export_eligible AND e.traffic_context='audience'
        AND coalesce(c.classification,e.traffic_context) IN ('audience','unclassified')
    ))
  ORDER BY o.last_checked_at NULLS FIRST,o.submitted_at,o.event_id
  LIMIT LEAST(GREATEST(p_limit,1),100);
END $$;


ALTER FUNCTION "public"."analytics_list_submitted_posthog_event_ids"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_posthog_delivery_health"() RETURNS "jsonb"
    LANGUAGE "sql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
 SELECT jsonb_build_object(
  'schema_version',2,
  'pending',count(*) FILTER (WHERE status='pending' AND origin='event'),
  'submitted',count(*) FILTER (WHERE status='submitted' AND origin='event'),
  'confirmed',count(*) FILTER (WHERE status='confirmed' AND origin='event'),
  'failed',count(*) FILTER (WHERE status='failed' AND origin='event'),
  'control_pending',count(*) FILTER (WHERE status IN ('pending','failed') AND origin='classification_control'),
  'terminal_reconciliation_gap',count(*) FILTER (WHERE status='submitted' AND attempts>=12 AND last_error_code='provider_reconciliation_missing'),
  'oldest_pending_at',min(next_attempt_at) FILTER (WHERE status IN ('pending','failed')),
  'oldest_submitted_at',min(submitted_at) FILTER (WHERE status='submitted'),
  'confirmed_watermark',max(confirmed_at) FILTER (WHERE status='confirmed'),
  'collection',coalesce((SELECT jsonb_object_agg(outcome,total) FROM (
    SELECT outcome,sum(count)::bigint AS total FROM public.analytics_collection_delivery_counters
    WHERE bucket_date >= (now() AT TIME ZONE 'America/Chicago')::date-29 GROUP BY outcome
  ) c),'{}'::jsonb),
  'collection_rejected_days',coalesce((SELECT jsonb_agg(jsonb_build_object('day',bucket_date,'reason',reason,'count',total) ORDER BY bucket_date,reason) FROM (
    SELECT bucket_date,reason,sum(count)::bigint AS total FROM public.analytics_collection_delivery_counters
    WHERE outcome='rejected' AND bucket_date >= (now() AT TIME ZONE 'America/Chicago')::date-29 GROUP BY bucket_date,reason
  ) r),'[]'::jsonb),
  'eligible_observations_14d',coalesce((SELECT count(*) FROM public.analytics_events_v2 e
    LEFT JOIN LATERAL (SELECT classification FROM public.analytics_event_v2_classifications c WHERE c.event_id=e.event_id ORDER BY classification_version DESC LIMIT 1) c ON true
    WHERE e.received_at >= now()-interval '14 days' AND e.export_eligible AND coalesce(c.classification,e.traffic_context) IN ('audience','unclassified')),0),
  'eligible_days_observed',coalesce((SELECT count(DISTINCT (received_at AT TIME ZONE 'America/Chicago')::date) FROM public.analytics_events_v2 e
    LEFT JOIN LATERAL (SELECT classification FROM public.analytics_event_v2_classifications c WHERE c.event_id=e.event_id ORDER BY classification_version DESC LIMIT 1) c ON true
    WHERE e.received_at >= now()-interval '14 days' AND e.export_eligible AND coalesce(c.classification,e.traffic_context) IN ('audience','unclassified')),0),
  'quota_billing_state','unknown'
 ) FROM public.analytics_posthog_outbox;
$$;


ALTER FUNCTION "public"."analytics_posthog_delivery_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_prepare_intelligence_periods"("p_daily_period" "date", "p_weekly_period" "date", "p_standard_scopes" "jsonb", "p_refresh_cadence_seconds" integer, "p_provider_pending_retry_seconds" integer, "p_max_catchup_periods" integer, "p_now" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE s jsonb; k text; today date; completed_day date; d date; scheduled_kind text; exhausted uuid;
BEGIN
  IF p_now IS NULL OR jsonb_typeof(p_standard_scopes)<>'array' OR p_refresh_cadence_seconds NOT BETWEEN 60 AND 86400 OR p_provider_pending_retry_seconds NOT BETWEEN 30 AND 86400 OR p_max_catchup_periods NOT BETWEEN 1 AND 31 THEN RAISE EXCEPTION 'invalid intelligence period'; END IF;
  FOR exhausted IN SELECT id FROM public.analytics_intelligence_jobs WHERE attempts>=20 AND (status IN ('pending','retry') OR (status='leased' AND leased_until<p_now)) FOR UPDATE SKIP LOCKED LOOP
    UPDATE public.analytics_intelligence_jobs SET status='leased' WHERE id=exhausted;
    PERFORM public.analytics_finish_intelligence_job(exhausted,'retry',NULL,'attempts_exhausted');
  END LOOP;
  FOR s IN SELECT value FROM jsonb_array_elements(p_standard_scopes) LOOP
    k:=public.analytics_intelligence_scope_key(s);
    IF NOT EXISTS (SELECT 1 FROM public.analytics_intelligence_jobs WHERE kind='refresh' AND scope_key=k AND status IN ('pending','leased','retry'))
       AND NOT EXISTS (SELECT 1 FROM public.analytics_intelligence_snapshot_current WHERE scope_key=k AND updated_at>p_now-make_interval(secs=>p_refresh_cadence_seconds)) THEN
      INSERT INTO public.analytics_intelligence_jobs(kind,scope_key,scope,available_at) VALUES('refresh',k,s,p_now) ON CONFLICT DO NOTHING;
    END IF;
  END LOOP;
  UPDATE public.analytics_intelligence_requests SET status='expired',updated_at=p_now WHERE status IN ('pending','leased') AND expires_at<=p_now;
  UPDATE public.analytics_intelligence_jobs j SET status='expired',leased_until=NULL,error_code='request_expired',updated_at=p_now FROM public.analytics_intelligence_requests r WHERE j.request_id=r.id AND r.status='expired' AND j.status IN ('pending','retry','leased');
  today := (p_now AT TIME ZONE 'America/Chicago')::date; completed_day:=today-1;
  FOREACH scheduled_kind IN ARRAY ARRAY['daily','weekly'] LOOP
    IF (scheduled_kind='daily' AND p_daily_period IS NULL) OR (scheduled_kind='weekly' AND p_weekly_period IS NULL) THEN CONTINUE; END IF;
    d:=CASE WHEN scheduled_kind='daily' THEN p_daily_period ELSE p_weekly_period END;
    -- Periods name the morning due date, while gallery windows end the day before.
    -- Site sources retain their explicitly displayed rolling UTC window; a late
    -- delivery does not claim to reconstruct older provider history.
    IF (d::timestamp + interval '8 hours') AT TIME ZONE 'America/Chicago' > p_now THEN CONTINUE; END IF;
    FOR d IN SELECT candidate::date FROM generate_series(d,d-CASE WHEN scheduled_kind='weekly' THEN 7*(p_max_catchup_periods-1) ELSE p_max_catchup_periods-1 END,CASE WHEN scheduled_kind='weekly' THEN '-7 days'::interval ELSE '-1 day'::interval END) candidate ORDER BY candidate DESC LOOP
      FOR s IN SELECT value FROM jsonb_array_elements(p_standard_scopes) LOOP
        IF scheduled_kind='weekly' AND s->>'kind'='sites' AND (s->>'period')::integer<>7 THEN CONTINUE; END IF;
        IF scheduled_kind='weekly' AND s->>'kind'='gallery' THEN s:=jsonb_set(s,'{query,start}',to_jsonb(((s#>>'{query,end}')::date-6)::text)); END IF;
        IF s->>'kind'='gallery' THEN
          s:=jsonb_set(jsonb_set(s,'{query,start}',to_jsonb((d-1-((s#>>'{query,end}')::date-(s#>>'{query,start}')::date))::text)),'{query,end}',to_jsonb((d-1)::text));
        END IF;
        k:=public.analytics_intelligence_scope_key(s);
        INSERT INTO public.analytics_intelligence_jobs(kind,owner_id,scope_key,scope,intended_period,available_at)
        SELECT scheduled_kind,sch.owner_id,k,s,d,p_now FROM public.analytics_intelligence_schedules sch
        JOIN public.analytics_intelligence_preferences prefs ON prefs.owner_id=sch.owner_id
        WHERE prefs.retention_policy<>'undecided' AND ((scheduled_kind='daily' AND sch.daily_enabled) OR (scheduled_kind='weekly' AND sch.weekly_enabled))
          AND NOT EXISTS(SELECT 1 FROM public.analytics_intelligence_briefs b WHERE b.owner_id=sch.owner_id AND b.kind=scheduled_kind AND b.period_key=d)
        ON CONFLICT DO NOTHING;
      END LOOP;
    END LOOP;
  END LOOP;
END $$;


ALTER FUNCTION "public"."analytics_prepare_intelligence_periods"("p_daily_period" "date", "p_weekly_period" "date", "p_standard_scopes" "jsonb", "p_refresh_cadence_seconds" integer, "p_provider_pending_retry_seconds" integer, "p_max_catchup_periods" integer, "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_queue_intelligence_request"("p_owner_id" "uuid", "p_scope" "jsonb", "p_operation" "text", "p_now" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE k text; request_id uuid;
BEGIN
 IF p_owner_id IS NULL OR p_now IS NULL OR p_scope IS NULL OR jsonb_typeof(p_scope)<>'object' OR coalesce(p_scope->>'kind','') NOT IN ('gallery','sites') OR p_operation NOT IN ('album_comparison','site_retention') THEN RAISE EXCEPTION 'invalid intelligence request'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.analytics_intelligence_preferences WHERE owner_id=p_owner_id AND retention_policy<>'undecided') THEN RAISE EXCEPTION 'intelligence retention decision required'; END IF;
 k:=public.analytics_intelligence_scope_key(p_scope);
 UPDATE public.analytics_intelligence_requests SET status='expired',updated_at=p_now WHERE owner_id=p_owner_id AND status IN ('pending','leased') AND expires_at<=p_now;
 SELECT id INTO request_id FROM public.analytics_intelligence_requests WHERE owner_id=p_owner_id AND scope_key=k AND operation=p_operation AND status IN ('pending','leased');
 IF request_id IS NOT NULL THEN RETURN request_id; END IF;
 IF (SELECT count(*) FROM public.analytics_intelligence_requests WHERE owner_id=p_owner_id AND status IN ('pending','leased'))>=20 THEN RAISE EXCEPTION 'too many active intelligence requests'; END IF;
 INSERT INTO public.analytics_intelligence_requests(owner_id,scope_key,operation,status,expires_at)
 VALUES(p_owner_id,k,p_operation,'pending',p_now+interval '10 minutes')
 ON CONFLICT(owner_id,scope_key,operation) WHERE status IN ('pending','leased') DO NOTHING RETURNING id INTO request_id;
 IF request_id IS NULL THEN SELECT id INTO request_id FROM public.analytics_intelligence_requests WHERE owner_id=p_owner_id AND scope_key=k AND operation=p_operation AND status IN ('pending','leased'); END IF;
 IF request_id IS NULL THEN RAISE EXCEPTION 'intelligence request could not be queued'; END IF;
 INSERT INTO public.analytics_intelligence_jobs(kind,owner_id,scope_key,scope,request_id,operation,available_at)
 VALUES('request',p_owner_id,k,p_scope,request_id,p_operation,p_now) ON CONFLICT DO NOTHING;
 RETURN request_id;
END $$;


ALTER FUNCTION "public"."analytics_queue_intelligence_request"("p_owner_id" "uuid", "p_scope" "jsonb", "p_operation" "text", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_read_launch"("p_album_key" "text", "p_as_of" timestamp with time zone DEFAULT "now"(), "p_days" integer DEFAULT 14, "p_traffic" "text" DEFAULT 'conservative'::"text", "p_public_only" boolean DEFAULT true, "p_window_start" "date" DEFAULT NULL::"date", "p_window_end" "date" DEFAULT NULL::"date", "p_photo_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
 v_today date:=(p_as_of AT TIME ZONE 'America/Chicago')::date;
 v_h integer:=greatest(p_days,7);
 v_target record;
 v_dated boolean;
 v_d0 date;
 v_ws date; v_we date;
 v_exp_since date;
 v_result jsonb;
 v_launches jsonb;
 v_launch jsonb;
 v_all jsonb;
BEGIN
 IF p_album_key IS NULL OR p_as_of IS NULL THEN RAISE EXCEPTION 'album and as-of are required'; END IF;
 IF p_days IS NULL OR p_days<1 OR p_days>365 THEN RAISE EXCEPTION 'invalid launch days'; END IF;
 IF p_traffic IS NULL OR p_traffic NOT IN ('conservative','inclusive') THEN RAISE EXCEPTION 'invalid traffic option'; END IF;
 IF p_photo_limit IS NULL OR p_photo_limit<0 OR p_photo_limit>2000 THEN RAISE EXCEPTION 'invalid photo limit'; END IF;
 IF p_window_start IS NOT NULL AND p_window_end IS NOT NULL AND (p_window_end<p_window_start OR p_window_end-p_window_start+1>365) THEN RAISE EXCEPTION 'invalid window'; END IF;

 SELECT a.album_key,a.album_name,s.visibility,s.first_published_at fp,s.first_published_at_basis fb,s.first_published_at_evidence fe
  INTO v_target FROM public.albums a LEFT JOIN public.album_settings s ON s.album_key=a.album_key WHERE a.album_key=p_album_key;
 IF NOT FOUND THEN RAISE EXCEPTION 'unknown album' USING ERRCODE='23503'; END IF;
 v_dated:=v_target.fp IS NOT NULL;
 IF v_dated THEN
  v_d0:=(v_target.fp AT TIME ZONE 'America/Chicago')::date;
  v_ws:=v_d0; v_we:=least(v_d0+p_days-1,v_today-1);
 ELSE
  v_we:=least(coalesce(p_window_end,v_today-1),v_today);
  v_ws:=coalesce(p_window_start,coalesce(p_window_end,v_today-1)-p_days+1);
 END IF;

 -- First day version-2 exposure collection recorded anything, from raw and archived rows.
 SELECT min(d) INTO v_exp_since FROM (
  SELECT min((e.occurred_at AT TIME ZONE 'America/Chicago')::date) d FROM public.analytics_events_v2 e WHERE e.event_name IN ('photo_exposed','photo_rendered')
  UNION ALL
  SELECT min(t.bucket_date) FROM public.analytics_v2_archived_totals t WHERE t.event_name IN ('photo_exposed','photo_rendered')
 ) x;


 -- The launch list comes from the one copy of the launch rules.
 v_all:=public.analytics_read_launches(p_as_of,p_days,p_traffic,p_public_only);
 v_launches:=v_all->'launches';
 IF v_dated THEN
  v_launch:=(SELECT x FROM jsonb_array_elements(v_launches) x WHERE x->>'albumKey'=p_album_key);
  IF v_launch IS NULL THEN
   -- The requested album is outside the comparison set (currently unlisted, public-only on): it still
   -- answers with its own series and totals, but it is not ranked, and the counts say how many were compared.
   v_launch:=(SELECT x FROM jsonb_array_elements(public.analytics_read_launches(p_as_of,p_days,p_traffic,false)->'launches') x WHERE x->>'albumKey'=p_album_key)
    || jsonb_build_object('rank',jsonb_build_object(
      'day3',jsonb_build_object('rank',NULL::integer,'compared',coalesce(v_launches->0->'rank'->'day3'->'compared','0'::jsonb),'tied',false),
      'day7',jsonb_build_object('rank',NULL::integer,'compared',coalesce(v_launches->0->'rank'->'day7'->'compared','0'::jsonb),'tied',false)));
  END IF;
 END IF;

 WITH
 -- An undated album has the requested window and no day number. A launch needs no grid here: its
 -- series comes from analytics_read_launches.
 grid AS (
  SELECT p_album_key AS album_key,NULL::integer AS day,g::date AS bucket_date FROM generate_series(v_ws,v_we,interval '1 day') g
  WHERE NOT v_dated AND g::date<=v_today
 ),
 state AS (
  SELECT g.album_key,g.day,g.bucket_date,
   CASE WHEN g.bucket_date=v_today THEN CASE WHEN c.coverage_state IS NOT NULL THEN 'partial' ELSE 'unavailable' END
        ELSE coalesce(c.coverage_state,'unavailable') END coverage
  FROM grid g LEFT JOIN public.analytics_daily_coverage c ON c.bucket_date=g.bucket_date
 ),
 sums AS (
  SELECT g.album_key,g.bucket_date,
   sum(d.action_count) FILTER (WHERE d.event_type='view' AND d.photo_id<>'')::bigint po,
   sum(d.action_count) FILTER (WHERE d.event_type='download')::bigint dl,
   sum(d.action_count) FILTER (WHERE d.event_type='album_open' AND d.photo_id='')::bigint ao
  FROM grid g JOIN public.analytics_daily_actions d ON d.bucket_date=g.bucket_date AND d.album_key=g.album_key
  WHERE (p_traffic='inclusive' OR d.traffic_classification IN ('audience','unclassified'))
   AND (NOT p_public_only OR d.photo_id='' OR EXISTS(SELECT 1 FROM public.photo_metadata m WHERE m.photo_id=d.photo_id AND m.album_key=d.album_key))
  GROUP BY g.album_key,g.bucket_date
 ),
 cells AS (
  SELECT s.album_key,s.day,s.bucket_date,s.coverage,
   CASE WHEN s.coverage='complete' THEN coalesce(m.po,0) WHEN s.coverage='partial' THEN m.po END po,
   CASE WHEN s.coverage='complete' THEN coalesce(m.dl,0) WHEN s.coverage='partial' THEN m.dl END dl,
   CASE WHEN s.coverage='complete' THEN coalesce(m.ao,0) WHEN s.coverage='partial' THEN m.ao END ao
  FROM state s LEFT JOIN sums m ON m.album_key=s.album_key AND m.bucket_date=s.bucket_date
 ),
 undated_series AS (
  SELECT coalesce(jsonb_agg(jsonb_build_object('day',NULL,'date',c.bucket_date,'photoOpens',c.po,'downloads',c.dl,'albumOpens',c.ao,'coverage',c.coverage) ORDER BY c.bucket_date) FILTER (WHERE c.bucket_date<v_today),'[]'::jsonb) series,
   (SELECT jsonb_build_object('day',NULL,'date',c2.bucket_date,'photoOpens',c2.po,'downloads',c2.dl,'albumOpens',c2.ao,'coverage',c2.coverage) FROM cells c2 WHERE NOT v_dated AND c2.album_key=p_album_key AND c2.bucket_date=v_today) current_day
  FROM cells c WHERE NOT v_dated AND c.album_key=p_album_key
 ),
 -- Per-photo daily-table counts over the album's window, complete days only.
 pa AS (
  SELECT d.photo_id,
   sum(d.action_count) FILTER (WHERE d.event_type='view')::bigint opens,
   sum(d.action_count) FILTER (WHERE d.event_type='view' AND v_exp_since IS NOT NULL AND d.bucket_date>=v_exp_since)::bigint opens_exp,
   sum(d.action_count) FILTER (WHERE d.event_type='download')::bigint downloads,
   sum(d.action_count) FILTER (WHERE d.event_type='favorite')::bigint favorites
  FROM public.analytics_daily_actions d JOIN public.analytics_daily_coverage c ON c.bucket_date=d.bucket_date AND c.coverage_state='complete'
  WHERE d.album_key=p_album_key AND d.photo_id<>'' AND d.bucket_date BETWEEN v_ws AND v_we AND d.bucket_date<v_today
   AND (p_traffic='inclusive' OR d.traffic_classification IN ('audience','unclassified'))
   AND EXISTS(SELECT 1 FROM public.photo_metadata m WHERE m.photo_id=d.photo_id AND m.album_key=d.album_key)
  GROUP BY d.photo_id
 ),
 -- Version-2 rows, counted here and never returned. Raw rows take the latest classification
 -- correction when the collector called them audience; archived totals already hold the effective one.
 v2 AS (
  SELECT r.photo_id,r.event_name,count(*)::bigint n FROM (
   SELECT e.photo_id,e.event_name,
    CASE WHEN e.traffic_context='audience' THEN coalesce((SELECT k.classification FROM public.analytics_event_v2_classifications k WHERE k.event_id=e.event_id ORDER BY k.classification_version DESC LIMIT 1),'audience') ELSE e.traffic_context END eff
   FROM public.analytics_events_v2 e
   WHERE e.album_key=p_album_key AND e.photo_id IS NOT NULL AND e.event_name IN ('photo_exposed','photo_rendered')
    AND (e.occurred_at AT TIME ZONE 'America/Chicago')::date BETWEEN v_ws AND v_we AND (e.occurred_at AT TIME ZONE 'America/Chicago')::date<v_today
  ) r WHERE (p_traffic='inclusive' AND r.eff<>'self_excluded') OR (p_traffic='conservative' AND r.eff IN ('audience','unclassified'))
  GROUP BY r.photo_id,r.event_name
  UNION ALL
  SELECT t.photo_id,t.event_name,sum(t.event_count)::bigint FROM public.analytics_v2_archived_totals t
  WHERE t.album_key=p_album_key AND t.photo_id IS NOT NULL AND t.event_name IN ('photo_exposed','photo_rendered')
   AND t.bucket_date BETWEEN v_ws AND v_we AND t.bucket_date<v_today
   AND ((p_traffic='inclusive' AND t.traffic_context<>'self_excluded') OR (p_traffic='conservative' AND t.traffic_context IN ('audience','unclassified')))
  GROUP BY t.photo_id,t.event_name
 ),
 v2p AS (
  SELECT photo_id,sum(n) FILTER (WHERE event_name='photo_exposed')::bigint exposures,sum(n) FILTER (WHERE event_name='photo_rendered')::bigint renders FROM v2 GROUP BY photo_id
 ),
 photo_rows AS (
  SELECT m.photo_id,coalesce(a.opens,0) opens,coalesce(a.opens_exp,0) opens_exp,coalesce(a.downloads,0) downloads,coalesce(a.favorites,0) favorites,
   coalesce(v.exposures,0) exposures,coalesce(v.renders,0) renders
  FROM public.photo_metadata m LEFT JOIN pa a ON a.photo_id=m.photo_id LEFT JOIN v2p v ON v.photo_id=m.photo_id
  WHERE m.album_key=p_album_key AND (a.photo_id IS NOT NULL OR v.photo_id IS NOT NULL)
 ),
 photo_json AS (
  SELECT (SELECT count(*) FROM photo_rows) with_activity,
   coalesce((SELECT jsonb_agg(jsonb_build_object('photoId',q.photo_id,'opens',q.opens,'downloads',q.downloads,'favorites',q.favorites,
     'exposureRecorded',v_exp_since IS NOT NULL AND v_exp_since<=v_we,
     'opensInExposureWindow',CASE WHEN v_exp_since IS NOT NULL AND v_exp_since<=v_we THEN q.opens_exp END,
     'exposures',CASE WHEN v_exp_since IS NOT NULL AND v_exp_since<=v_we THEN q.exposures END,
     'renders',CASE WHEN v_exp_since IS NOT NULL AND v_exp_since<=v_we THEN q.renders END) ORDER BY q.opens DESC,q.downloads DESC,q.favorites DESC,q.exposures DESC,q.photo_id)
    FROM (SELECT * FROM photo_rows ORDER BY opens DESC,downloads DESC,favorites DESC,exposures DESC,photo_id LIMIT p_photo_limit) q),'[]'::jsonb) photos
 ),
 album_json AS (
  SELECT CASE WHEN v_dated THEN
    coalesce(v_launch,'{}'::jsonb)
   ELSE jsonb_build_object('albumKey',v_target.album_key,'albumName',v_target.album_name,'firstPublishedAt',NULL,'basis',v_target.fb,'status','no_launch_date',
     'series',(SELECT series FROM undated_series),'currentDay',(SELECT current_day FROM undated_series),'totals',NULL,'rank',NULL)
   END || jsonb_build_object(
    'firstPublishedAtEvidence',v_target.fe,
    'reason',CASE WHEN v_dated THEN NULL
      WHEN v_target.fb='unobserved' THEN jsonb_build_object('code','unobserved','text',v_target.fe)
      WHEN v_target.visibility='unlisted' THEN jsonb_build_object('code','not_published','text','Not published yet.')
      ELSE jsonb_build_object('code','no_record','text','Public with no publication on record.') END,
    'window',jsonb_build_object('start',v_ws,'end',v_we),
    'photosInAlbum',(SELECT count(*) FROM public.photo_metadata WHERE album_key=p_album_key),
    'photosWithActivity',(SELECT with_activity FROM photo_json),
    'photos',(SELECT photos FROM photo_json),
    'exposure',jsonb_build_object('since',v_exp_since,
     'coverage',CASE WHEN v_exp_since IS NULL OR v_exp_since>v_we THEN 'none' WHEN v_exp_since>v_ws THEN 'partial' ELSE 'complete' END)) j
 )
 SELECT jsonb_build_object(
  'asOf',p_as_of,'today',v_today,'lastCompleteDay',v_today-1,'days',p_days,'traffic',p_traffic,
  'album',(SELECT j FROM album_json),
  'launches',v_launches)
 INTO v_result;
 RETURN v_result;
END $$;


ALTER FUNCTION "public"."analytics_read_launch"("p_album_key" "text", "p_as_of" timestamp with time zone, "p_days" integer, "p_traffic" "text", "p_public_only" boolean, "p_window_start" "date", "p_window_end" "date", "p_photo_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."analytics_read_launch"("p_album_key" "text", "p_as_of" timestamp with time zone, "p_days" integer, "p_traffic" "text", "p_public_only" boolean, "p_window_start" "date", "p_window_end" "date", "p_photo_limit" integer) IS 'Launch read model: an album''s days since first publication, totals at day 3 and day 7, and its rank at each age among every launch whose window was complete at the read date (a launch published since can move a rank), per-photo counts, and version-2 exposure where recorded. The median sentence on the report compares earlier launches only. Service role only. Returns no identifiers.';



CREATE OR REPLACE FUNCTION "public"."analytics_read_launches"("p_as_of" timestamp with time zone DEFAULT "now"(), "p_days" integer DEFAULT 14, "p_traffic" "text" DEFAULT 'conservative'::"text", "p_public_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
 v_today date:=(p_as_of AT TIME ZONE 'America/Chicago')::date;
 v_h integer:=greatest(p_days,7);
 v_result jsonb;
BEGIN
 IF p_as_of IS NULL THEN RAISE EXCEPTION 'as-of is required'; END IF;
 IF p_days IS NULL OR p_days<1 OR p_days>365 THEN RAISE EXCEPTION 'invalid launch days'; END IF;
 IF p_traffic IS NULL OR p_traffic NOT IN ('conservative','inclusive') THEN RAISE EXCEPTION 'invalid traffic option'; END IF;

 WITH
 launches AS (
  SELECT a.album_key,a.album_name,s.first_published_at fp,s.first_published_at_basis fb,
   (s.first_published_at AT TIME ZONE 'America/Chicago')::date d0
  FROM public.albums a JOIN public.album_settings s ON s.album_key=a.album_key
  WHERE s.first_published_at IS NOT NULL AND (NOT p_public_only OR s.visibility<>'unlisted')
 ),
 -- One row per launch and Chicago day up to today, counted from day 0.
 grid AS (
  SELECT l.album_key,g.g AS day,l.d0+g.g AS bucket_date
  FROM launches l CROSS JOIN generate_series(0,v_h-1) AS g(g) WHERE l.d0+g.g<=v_today
 ),
 state AS (
  SELECT g.album_key,g.day,g.bucket_date,
   CASE WHEN g.bucket_date=v_today THEN CASE WHEN c.coverage_state IS NOT NULL THEN 'partial' ELSE 'unavailable' END
        ELSE coalesce(c.coverage_state,'unavailable') END coverage
  FROM grid g LEFT JOIN public.analytics_daily_coverage c ON c.bucket_date=g.bucket_date
 ),
 sums AS (
  SELECT g.album_key,g.bucket_date,
   sum(d.action_count) FILTER (WHERE d.event_type='view' AND d.photo_id<>'')::bigint po,
   sum(d.action_count) FILTER (WHERE d.event_type='download')::bigint dl,
   sum(d.action_count) FILTER (WHERE d.event_type='album_open' AND d.photo_id='')::bigint ao
  FROM grid g JOIN public.analytics_daily_actions d ON d.bucket_date=g.bucket_date AND d.album_key=g.album_key
  WHERE (p_traffic='inclusive' OR d.traffic_classification IN ('audience','unclassified'))
   AND (NOT p_public_only OR d.photo_id='' OR EXISTS(SELECT 1 FROM public.photo_metadata m WHERE m.photo_id=d.photo_id AND m.album_key=d.album_key))
  GROUP BY g.album_key,g.bucket_date
 ),
 cells AS (
  SELECT s.album_key,s.day,s.bucket_date,s.coverage,
   CASE WHEN s.coverage='complete' THEN coalesce(m.po,0) WHEN s.coverage='partial' THEN m.po END po,
   CASE WHEN s.coverage='complete' THEN coalesce(m.dl,0) WHEN s.coverage='partial' THEN m.dl END dl,
   CASE WHEN s.coverage='complete' THEN coalesce(m.ao,0) WHEN s.coverage='partial' THEN m.ao END ao
  FROM state s LEFT JOIN sums m ON m.album_key=s.album_key AND m.bucket_date=s.bucket_date
 ),
 tot AS (
  SELECT l.album_key,l.album_name,l.fp,l.fb,l.d0,
   v_today-l.d0 elapsed,
   (v_today-l.d0>=3) reached3,(v_today-l.d0>=7) reached7,
   (count(*) FILTER (WHERE c.day<3 AND c.bucket_date<v_today AND c.coverage='complete'))=3 ok3,
   (count(*) FILTER (WHERE c.day<7 AND c.bucket_date<v_today AND c.coverage='complete'))=7 ok7,
   sum(c.po) FILTER (WHERE c.day<3) po3,sum(c.dl) FILTER (WHERE c.day<3) dl3,sum(c.ao) FILTER (WHERE c.day<3) ao3,
   sum(c.po) FILTER (WHERE c.day<7) po7,sum(c.dl) FILTER (WHERE c.day<7) dl7,sum(c.ao) FILTER (WHERE c.day<7) ao7
  FROM launches l LEFT JOIN cells c ON c.album_key=l.album_key AND c.bucket_date<v_today
  GROUP BY l.album_key,l.album_name,l.fp,l.fb,l.d0
 ),
 totals AS (
  SELECT t.*,CASE WHEN ok3 THEN po3 END t_po3,CASE WHEN ok3 THEN dl3 END t_dl3,CASE WHEN ok3 THEN ao3 END t_ao3,
   CASE WHEN ok7 THEN po7 END t_po7,CASE WHEN ok7 THEN dl7 END t_dl7,CASE WHEN ok7 THEN ao7 END t_ao7
  FROM tot t
 ),
 r3 AS (
  SELECT album_key,rank() OVER (ORDER BY t_po3 DESC) rk,count(*) OVER () n,count(*) OVER (PARTITION BY t_po3) same
  FROM totals WHERE t_po3 IS NOT NULL
 ),
 r7 AS (
  SELECT album_key,rank() OVER (ORDER BY t_po7 DESC) rk,count(*) OVER () n,count(*) OVER (PARTITION BY t_po7) same
  FROM totals WHERE t_po7 IS NOT NULL
 ),
 launch_json AS (
  SELECT t.album_key,t.fp,jsonb_build_object(
   'albumKey',t.album_key,'albumName',t.album_name,'firstPublishedAt',t.fp,'basis',t.fb,
   'status',CASE WHEN t.elapsed<7 THEN 'in_progress' ELSE 'finished' END,
   'elapsedDays',greatest(t.elapsed,0),
   'series',coalesce((SELECT jsonb_agg(jsonb_build_object('day',c.day,'date',c.bucket_date,'photoOpens',c.po,'downloads',c.dl,'albumOpens',c.ao,'coverage',c.coverage) ORDER BY c.day)
     FROM cells c WHERE c.album_key=t.album_key AND c.bucket_date<v_today AND c.day<p_days),'[]'::jsonb),
   'currentDay',(SELECT jsonb_build_object('day',c.day,'date',c.bucket_date,'photoOpens',c.po,'downloads',c.dl,'albumOpens',c.ao,'coverage',c.coverage)
     FROM cells c WHERE c.album_key=t.album_key AND c.bucket_date=v_today AND c.day<p_days),
   'totals',jsonb_build_object(
    'day3',jsonb_build_object('reached',t.reached3,'complete',t.ok3,'photoOpens',t.t_po3,'downloads',t.t_dl3,'albumOpens',t.t_ao3),
    'day7',jsonb_build_object('reached',t.reached7,'complete',t.ok7,'photoOpens',t.t_po7,'downloads',t.t_dl7,'albumOpens',t.t_ao7)),
   'rank',jsonb_build_object(
    'day3',jsonb_build_object('rank',x3.rk,'compared',(SELECT count(*) FROM r3),'tied',coalesce(x3.same>1,false)),
    'day7',jsonb_build_object('rank',x7.rk,'compared',(SELECT count(*) FROM r7),'tied',coalesce(x7.same>1,false)))
  ) j
  FROM totals t LEFT JOIN r3 x3 ON x3.album_key=t.album_key LEFT JOIN r7 x7 ON x7.album_key=t.album_key
 )
 SELECT jsonb_build_object(
  'asOf',p_as_of,'today',v_today,'lastCompleteDay',v_today-1,'days',p_days,'traffic',p_traffic,
  'launches',coalesce((SELECT jsonb_agg(j ORDER BY fp DESC,album_key) FROM launch_json),'[]'::jsonb))
 INTO v_result;
 RETURN v_result;
END $$;


ALTER FUNCTION "public"."analytics_read_launches"("p_as_of" timestamp with time zone, "p_days" integer, "p_traffic" "text", "p_public_only" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."analytics_read_launches"("p_as_of" timestamp with time zone, "p_days" integer, "p_traffic" "text", "p_public_only" boolean) IS 'Every launch with a first publication, each with its daily series, totals and rank at day 3 and day 7 against the others. The one copy of the launch rules: analytics_read_launch returns this list unchanged. Service role only. Returns no identifiers.';



CREATE OR REPLACE FUNCTION "public"."analytics_read_report_evidence"("p_start" "date", "p_end" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
  WITH clock AS (
    SELECT statement_timestamp() AS cutoff,
      (statement_timestamp() AT TIME ZONE 'America/Chicago')::date AS today
  ), live_rows AS (
    SELECT min(e.id) AS id, clock.today AS bucket_date,
      coalesce(e.resolved_album_key, '') AS album_key, coalesce(e.photo_id, '') AS photo_id,
      e.event_type, coalesce(e.source, 'direct') AS source, e.resolved_source_kind AS source_kind,
      e.snapshot_sport AS sport, e.snapshot_event_date AS event_date,
      e.snapshot_album_event_type AS album_event_type, e.snapshot_publication_at AS publication_at,
      e.snapshot_photo_category AS photo_category, e.effective_classification AS traffic_classification,
      e.effective_classification_version AS classification_version, e.catalogue_basis,
      1 AS definition_version, 'partial'::text AS coverage_state, count(*) AS action_count,
      max(e.created_at) AS latest_event_at, clock.cutoff AS reconciled_at
    FROM analytics_private.effective_engagement_events e CROSS JOIN clock
    WHERE clock.today BETWEEN p_start AND p_end
      AND e.created_at >= clock.today::timestamp AT TIME ZONE 'America/Chicago'
      AND e.created_at < clock.cutoff
    GROUP BY clock.today, clock.cutoff, e.resolved_album_key, e.photo_id, e.event_type,
      e.source, e.resolved_source_kind, e.snapshot_sport, e.snapshot_event_date,
      e.snapshot_album_event_type, e.snapshot_publication_at, e.snapshot_photo_category,
      e.effective_classification, e.effective_classification_version, e.catalogue_basis
  ), evidence_rows AS (
    SELECT to_jsonb(actions) AS payload FROM public.analytics_daily_actions actions CROSS JOIN clock
    WHERE actions.bucket_date BETWEEN p_start AND p_end AND actions.bucket_date <> clock.today
    UNION ALL SELECT to_jsonb(live_rows) FROM live_rows
  ), evidence_coverage AS (
    SELECT to_jsonb(coverage)-'notes' AS payload FROM public.analytics_daily_coverage coverage CROSS JOIN clock
    WHERE coverage.bucket_date BETWEEN p_start AND p_end AND coverage.bucket_date <> clock.today
    UNION ALL
    SELECT jsonb_build_object('bucket_date',clock.today,'cutoff_at',clock.cutoff,
      'raw_window_start',clock.today::timestamp AT TIME ZONE 'America/Chicago',
      'raw_window_end',clock.cutoff,'coverage_state','partial','definition_version',1,
      'reconciled_at',clock.cutoff,'frozen_at',NULL,
      'catalogue_basis',CASE WHEN (SELECT count(DISTINCT catalogue_basis) FROM live_rows)>1 THEN 'mixed'
        ELSE coalesce((SELECT min(catalogue_basis) FROM live_rows),'event_snapshot') END)
    FROM clock WHERE clock.today BETWEEN p_start AND p_end
  )
  SELECT jsonb_build_object(
    'rows',coalesce((SELECT jsonb_agg(payload ORDER BY payload->>'bucket_date',payload->>'id') FROM evidence_rows),'[]'::jsonb),
    'coverage',coalesce((SELECT jsonb_agg(payload ORDER BY payload->>'bucket_date') FROM evidence_coverage),'[]'::jsonb)
  ) WHERE p_start <= p_end;
$$;


ALTER FUNCTION "public"."analytics_read_report_evidence"("p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_read_report_evidence_compact"("p_start" "date", "p_end" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
  WITH clock AS (
    SELECT statement_timestamp() AS cutoff,
      (statement_timestamp() AT TIME ZONE 'America/Chicago')::date AS today
  ), live_rows AS (
    SELECT min(e.id) AS id, clock.today AS bucket_date,
      coalesce(e.resolved_album_key, '') AS album_key, coalesce(e.photo_id, '') AS photo_id,
      e.event_type, coalesce(e.source, 'direct') AS source, e.resolved_source_kind AS source_kind,
      e.snapshot_sport AS sport, e.snapshot_event_date AS event_date,
      e.snapshot_album_event_type AS album_event_type, e.snapshot_publication_at AS publication_at,
      e.snapshot_photo_category AS photo_category, e.effective_classification AS traffic_classification,
      e.effective_classification_version AS classification_version, e.catalogue_basis,
      1 AS definition_version, 'partial'::text AS coverage_state, count(*) AS action_count,
      max(e.created_at) AS latest_event_at, clock.cutoff AS reconciled_at
    FROM analytics_private.effective_engagement_events e CROSS JOIN clock
    WHERE clock.today BETWEEN p_start AND p_end
      AND e.created_at >= clock.today::timestamp AT TIME ZONE 'America/Chicago'
      AND e.created_at < clock.cutoff
    GROUP BY clock.today, clock.cutoff, e.resolved_album_key, e.photo_id, e.event_type,
      e.source, e.resolved_source_kind, e.snapshot_sport, e.snapshot_event_date,
      e.snapshot_album_event_type, e.snapshot_publication_at, e.snapshot_photo_category,
      e.effective_classification, e.effective_classification_version, e.catalogue_basis
  ), evidence_rows AS (
    SELECT actions.bucket_date, actions.album_key, actions.photo_id, actions.event_type, actions.source, actions.source_kind, actions.sport, actions.event_date, actions.album_event_type, actions.publication_at, actions.photo_category, actions.traffic_classification, actions.action_count, actions.coverage_state, actions.latest_event_at FROM public.analytics_daily_actions actions CROSS JOIN clock
    WHERE actions.bucket_date BETWEEN p_start AND p_end AND actions.bucket_date <> clock.today
    UNION ALL SELECT live_rows.bucket_date, live_rows.album_key, live_rows.photo_id, live_rows.event_type, live_rows.source, live_rows.source_kind, live_rows.sport, live_rows.event_date, live_rows.album_event_type, live_rows.publication_at, live_rows.photo_category, live_rows.traffic_classification, live_rows.action_count, live_rows.coverage_state, live_rows.latest_event_at FROM live_rows
  ), evidence_coverage AS (
    SELECT to_jsonb(coverage)-'notes' AS payload FROM public.analytics_daily_coverage coverage CROSS JOIN clock
    WHERE coverage.bucket_date BETWEEN p_start AND p_end AND coverage.bucket_date <> clock.today
    UNION ALL
    SELECT jsonb_build_object('bucket_date',clock.today,'cutoff_at',clock.cutoff,
      'raw_window_start',clock.today::timestamp AT TIME ZONE 'America/Chicago',
      'raw_window_end',clock.cutoff,'coverage_state','partial','definition_version',1,
      'reconciled_at',clock.cutoff,'frozen_at',NULL,
      'catalogue_basis',CASE WHEN (SELECT count(DISTINCT catalogue_basis) FROM live_rows)>1 THEN 'mixed'
        ELSE coalesce((SELECT min(catalogue_basis) FROM live_rows),'event_snapshot') END)
    FROM clock WHERE clock.today BETWEEN p_start AND p_end
  )
  SELECT jsonb_build_object(
    'columns',jsonb_build_array('bucket_date', 'album_key', 'photo_id', 'event_type', 'source', 'source_kind', 'sport', 'event_date', 'album_event_type', 'publication_at', 'photo_category', 'traffic_classification', 'action_count', 'coverage_state', 'latest_event_at'),
    'rows',coalesce((SELECT jsonb_agg(jsonb_build_array(bucket_date, album_key, photo_id, event_type, source, source_kind, sport, event_date, album_event_type, publication_at, photo_category, traffic_classification, action_count, coverage_state, latest_event_at) ORDER BY bucket_date,album_key,photo_id,event_type,source,traffic_classification) FROM evidence_rows),'[]'::jsonb),
    'coverage',coalesce((SELECT jsonb_agg(payload ORDER BY payload->>'bucket_date') FROM evidence_coverage),'[]'::jsonb)
  ) WHERE p_start <= p_end;
$$;


ALTER FUNCTION "public"."analytics_read_report_evidence_compact"("p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_read_scheduled_gallery_report"("p_start" "date", "p_end" "date", "p_measure" "text", "p_scope" "text", "p_album_keys" "text"[], "p_sport" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT NULL::"text", "p_event_date" "date" DEFAULT NULL::"date", "p_season" "text" DEFAULT NULL::"text", "p_album_event_type" "text" DEFAULT NULL::"text", "p_compare" "text" DEFAULT 'previous'::"text", "p_compare_start" "date" DEFAULT NULL::"date", "p_compare_end" "date" DEFAULT NULL::"date", "p_traffic" "text" DEFAULT 'conservative'::"text", "p_public_only" boolean DEFAULT false, "p_photo_page" integer DEFAULT 0, "p_photo_page_size" integer DEFAULT 24, "p_photo_rank" "text" DEFAULT 'popular'::"text", "p_export" boolean DEFAULT false, "p_include_today" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
 v_compare_start date; v_compare_end date; v_today date:=(statement_timestamp() AT TIME ZONE 'America/Chicago')::date;
 v_current_days integer; v_previous_days integer; v_result jsonb;
BEGIN
 IF p_start IS NULL OR p_end IS NULL OR p_start>p_end THEN RAISE EXCEPTION 'invalid report dates'; END IF;
 v_current_days:=p_end-p_start+1;
 IF v_current_days>3650 THEN RAISE EXCEPTION 'report range exceeds 3650 days'; END IF;
 IF p_measure NOT IN ('photo_opens','album_opens','downloads','favorites','shares') THEN RAISE EXCEPTION 'invalid report measure'; END IF;
 IF p_scope NOT IN ('all','album','selected') OR p_traffic NOT IN ('inclusive','conservative') OR p_compare NOT IN ('previous','custom','publication_age','none') OR p_photo_rank NOT IN ('popular','rising','recent') THEN RAISE EXCEPTION 'invalid report option'; END IF;
 IF p_photo_page<0 OR p_photo_page_size<0 OR p_photo_page_size>100 THEN RAISE EXCEPTION 'invalid photo page'; END IF;
 IF p_scope='album' AND coalesce(cardinality(p_album_keys),0)<>1 THEN RAISE EXCEPTION 'album scope requires one album'; END IF;
 IF p_scope='selected' AND coalesce(cardinality(p_album_keys),0)<2 THEN RAISE EXCEPTION 'selected scope requires two albums'; END IF;
 IF p_compare='previous' THEN v_compare_end:=p_start-1;v_compare_start:=v_compare_end-(p_end-p_start);
 ELSIF p_compare='custom' THEN
  IF p_compare_start IS NULL OR p_compare_end IS NULL THEN RAISE EXCEPTION 'custom comparison requires dates'; END IF;
  v_compare_start:=least(p_compare_start,p_compare_end);v_compare_end:=greatest(p_compare_start,p_compare_end);
  IF v_compare_end-v_compare_start+1>3650 THEN RAISE EXCEPTION 'comparison range exceeds 3650 days'; END IF;
 END IF;
 v_previous_days:=CASE WHEN v_compare_start IS NULL THEN 0 ELSE v_compare_end-v_compare_start+1 END;

 WITH visible_albums AS (
  SELECT a.album_key,a.sport::text sport,a.event_date,s.first_published_at AS published_at FROM public.albums a
  LEFT JOIN public.album_settings s USING(album_key) WHERE NOT p_public_only OR coalesce(s.visibility,'public')<>'unlisted'
 ),eligible_catalogue AS (
  SELECT v.album_key,v.published_at FROM visible_albums v WHERE (p_scope='all' OR v.album_key=ANY(p_album_keys))
   AND (p_sport IS NULL OR v.sport=p_sport) AND (p_event_date IS NULL OR v.event_date=p_event_date)
   AND (p_season IS NULL OR coalesce(extract(year FROM v.event_date)::text,'unknown')=p_season) AND (p_album_event_type IS NULL OR p_album_event_type='unknown')
 ),days AS (
  SELECT g::date bucket_date FROM generate_series(least(p_start,coalesce(v_compare_start,p_start)),greatest(p_end,coalesce(v_compare_end,p_end)),interval '1 day') g
 ),coverage AS (
  SELECT d.bucket_date,CASE WHEN d.bucket_date>v_today THEN NULL WHEN d.bucket_date=v_today AND c.coverage_state IS NOT NULL THEN 'partial' ELSE c.coverage_state END coverage_state,c.cutoff_at,c.reconciled_at,c.catalogue_basis FROM days d LEFT JOIN public.analytics_daily_coverage c USING(bucket_date)
 ),cc AS (
  SELECT CASE WHEN bool_or(coverage_state IS NULL OR coverage_state='unavailable') THEN 'unavailable' WHEN bool_or(coverage_state='partial') THEN 'partial' ELSE 'complete' END state FROM coverage WHERE bucket_date BETWEEN p_start AND p_end
 ),pc AS (
  SELECT CASE WHEN v_compare_start IS NULL THEN 'unavailable' WHEN bool_or(coverage_state IS NULL OR coverage_state='unavailable') THEN 'unavailable' WHEN bool_or(coverage_state='partial') THEN 'partial' ELSE 'complete' END state FROM coverage WHERE v_compare_start IS NOT NULL AND bucket_date BETWEEN v_compare_start AND v_compare_end
 ),base AS (
  SELECT d.bucket_date,d.album_key,d.photo_id,d.event_type,d.source,d.source_kind,d.traffic_classification,d.action_count,d.latest_event_at FROM public.analytics_daily_actions d WHERE d.bucket_date BETWEEN least(p_start,coalesce(v_compare_start,p_start)) AND greatest(p_end,coalesce(v_compare_end,p_end))
   AND (p_scope='all' OR d.album_key=ANY(p_album_keys)) AND (NOT p_public_only OR EXISTS(SELECT 1 FROM visible_albums v WHERE v.album_key=d.album_key))
   AND (NOT p_public_only OR d.photo_id='' OR EXISTS(SELECT 1 FROM public.photo_metadata m JOIN visible_albums v ON v.album_key=m.album_key WHERE m.photo_id=d.photo_id AND m.album_key=d.album_key))
   AND (p_sport IS NULL OR d.sport=p_sport) AND (p_category IS NULL OR d.photo_category=p_category) AND (p_source IS NULL OR d.source=p_source)
   AND (p_event_date IS NULL OR d.event_date=p_event_date) AND (p_season IS NULL OR coalesce(extract(year FROM d.event_date)::text,'unknown')=p_season)
   AND (p_album_event_type IS NULL OR d.album_event_type=p_album_event_type)
 ),cur_all AS (SELECT * FROM base WHERE bucket_date BETWEEN p_start AND p_end),prev_all AS (SELECT * FROM base WHERE v_compare_start IS NOT NULL AND bucket_date BETWEEN v_compare_start AND v_compare_end),
 cur AS (SELECT * FROM cur_all WHERE p_traffic='inclusive' OR traffic_classification IN('audience','unclassified')),
 prev AS (SELECT * FROM prev_all WHERE p_traffic='inclusive' OR traffic_classification IN('audience','unclassified')),
 cm AS (SELECT * FROM cur WHERE (p_measure='photo_opens' AND event_type='view' AND photo_id<>'') OR (p_measure='album_opens' AND event_type='album_open' AND photo_id='') OR (p_measure='downloads' AND event_type='download') OR (p_measure='favorites' AND event_type='favorite') OR (p_measure='shares' AND event_type='share')),
 pm AS (SELECT * FROM prev WHERE (p_measure='photo_opens' AND event_type='view' AND photo_id<>'') OR (p_measure='album_opens' AND event_type='album_open' AND photo_id='') OR (p_measure='downloads' AND event_type='download') OR (p_measure='favorites' AND event_type='favorite') OR (p_measure='shares' AND event_type='share')),
 daily_counts AS (SELECT bucket_date,sum(action_count)::bigint n FROM cm GROUP BY bucket_date),
 ca AS (SELECT album_key,sum(action_count)::bigint n,max(latest_event_at) last_at FROM cm GROUP BY album_key),
 pa AS (SELECT album_key,sum(action_count)::bigint n FROM pm GROUP BY album_key),
 am AS (SELECT album_key,sum(action_count)FILTER(WHERE event_type='view' AND photo_id<>'')::bigint po,sum(action_count)FILTER(WHERE event_type='album_open' AND photo_id='')::bigint ao,sum(action_count)FILTER(WHERE event_type='download')::bigint dl,sum(action_count)FILTER(WHERE event_type='favorite')::bigint fa,sum(action_count)FILTER(WHERE event_type='share')::bigint sh FROM cur GROUP BY album_key),
 album_keys AS (SELECT album_key,published_at FROM eligible_catalogue UNION SELECT ca.album_key,v.published_at FROM ca LEFT JOIN visible_albums v USING(album_key) UNION SELECT pa.album_key,v.published_at FROM pa LEFT JOIN visible_albums v USING(album_key)),
 albums AS (
  SELECT k.album_key,CASE WHEN ca.album_key IS NOT NULL THEN ca.n WHEN cc.state='complete' THEN 0 END n,CASE WHEN pa.album_key IS NOT NULL THEN pa.n WHEN pc.state='complete' THEN 0 END pn,ca.last_at,max(k.published_at) published_at,
   CASE WHEN cc.state='complete' THEN jsonb_build_object('photo_opens',coalesce(am.po,0),'album_opens',coalesce(am.ao,0),'downloads',coalesce(am.dl,0),'favorites',coalesce(am.fa,0),'shares',coalesce(am.sh,0)) ELSE jsonb_build_object('photo_opens',NULL,'album_opens',NULL,'downloads',NULL,'favorites',NULL,'shares',NULL) END measures
  FROM album_keys k CROSS JOIN cc CROSS JOIN pc LEFT JOIN ca USING(album_key) LEFT JOIN pa USING(album_key) LEFT JOIN am USING(album_key)
  GROUP BY k.album_key,ca.album_key,ca.n,ca.last_at,pa.album_key,pa.n,cc.state,pc.state,am.po,am.ao,am.dl,am.fa,am.sh
 ),photo_events AS (
  -- Aggregate every photo once. Joining several unindexed CTE groups can become
  -- quadratic after a burst when the planner still estimates a single row.
  SELECT b.*,bucket_date BETWEEN p_start AND p_end is_current,
   v_compare_start IS NOT NULL AND bucket_date BETWEEN v_compare_start AND v_compare_end is_previous,
   (p_measure='photo_opens' AND event_type='view') OR (p_measure='downloads' AND event_type='download') OR (p_measure='favorites' AND event_type='favorite') OR (p_measure='shares' AND event_type='share') matches_measure
  FROM base b WHERE photo_id<>'' AND (p_traffic='inclusive' OR traffic_classification IN('audience','unclassified'))
 ),photo_aggregates AS (
  SELECT photo_id,album_key,
   sum(action_count)FILTER(WHERE is_current AND matches_measure)::bigint n,
   sum(action_count)FILTER(WHERE is_previous AND matches_measure)::bigint pn,
   max(latest_event_at)FILTER(WHERE is_current AND matches_measure) last_at,
   sum(action_count)FILTER(WHERE is_current AND event_type='view')::bigint po,
   sum(action_count)FILTER(WHERE is_current AND event_type='download')::bigint dl,
   sum(action_count)FILTER(WHERE is_current AND event_type='favorite')::bigint fa,
   sum(action_count)FILTER(WHERE is_current AND event_type='share')::bigint sh
  FROM photo_events GROUP BY photo_id,album_key HAVING bool_or(matches_measure AND (is_current OR is_previous))
 ),photos0 AS (
  SELECT a.photo_id,a.album_key,CASE WHEN a.n IS NOT NULL THEN a.n WHEN cc.state='complete' THEN 0 END n,
   CASE WHEN a.pn IS NOT NULL THEN a.pn WHEN pc.state='complete' THEN 0 END pn,a.last_at,
   CASE WHEN cc.state='complete' THEN jsonb_build_object('photo_opens',coalesce(a.po,0),'album_opens',0,'downloads',coalesce(a.dl,0),'favorites',coalesce(a.fa,0),'shares',coalesce(a.sh,0)) ELSE jsonb_build_object('photo_opens',NULL,'album_opens',NULL,'downloads',NULL,'favorites',NULL,'shares',NULL) END measures,
   CASE WHEN cc.state='complete' AND pc.state='complete' THEN CASE WHEN v_current_days=v_previous_days THEN coalesce(a.n,0)-coalesce(a.pn,0) ELSE coalesce(a.n,0)::numeric/v_current_days-coalesce(a.pn,0)::numeric/v_previous_days END END rising
  FROM photo_aggregates a CROSS JOIN cc CROSS JOIN pc
 ),ranked AS (
  SELECT f.*,count(*)OVER()::integer total,row_number()OVER(ORDER BY CASE WHEN p_photo_rank='recent' THEN last_at END DESC NULLS LAST,CASE WHEN p_photo_rank='rising' THEN rising END DESC NULLS LAST,CASE WHEN p_photo_rank='popular' THEN n END DESC NULLS LAST,n DESC NULLS LAST,photo_id,album_key) rn FROM photos0 f
   -- Rising needs a comparison. A photo whose album was first published after the
   -- comparison window ended had nothing to compare, so it is left out of Rising
   -- (and its total) rather than ranked by its whole count. Same rule as
   -- publishedAfterComparison() in src/lib/analytics/report-contract.ts: the
   -- recorded publication time's Chicago date is after the comparison end.
   -- Never inferred from event or import dates. Popular and Recent are unchanged.
   WHERE p_photo_rank<>'rising' OR v_compare_end IS NULL OR NOT EXISTS(
    SELECT 1 FROM album_keys k WHERE k.album_key=f.album_key AND (k.published_at AT TIME ZONE 'America/Chicago')::date>v_compare_end)
 ),page_meta AS (SELECT coalesce(max(total),0)::integer total,CASE WHEN p_export OR p_photo_page_size=0 OR coalesce(max(total),0)=0 THEN 0 ELSE least(p_photo_page,(coalesce(max(total),0)-1)/p_photo_page_size) END::integer page FROM ranked),
 page AS (SELECT r.* FROM ranked r CROSS JOIN page_meta x WHERE p_export OR (p_photo_page_size>0 AND r.rn>x.page*p_photo_page_size AND r.rn<=(x.page+1)*p_photo_page_size)),
 cao AS (SELECT album_key,sum(action_count)::bigint n,max(latest_event_at) last_at FROM cm WHERE photo_id='' GROUP BY album_key),pao AS (SELECT album_key,sum(action_count)::bigint n FROM pm WHERE photo_id='' GROUP BY album_key),aok AS (SELECT album_key FROM cao UNION SELECT album_key FROM pao),
 sources AS (SELECT source_kind,CASE WHEN source='direct' THEN 'Unknown / no tag' ELSE source END source,sum(action_count)::bigint n FROM cur GROUP BY source_kind,CASE WHEN source='direct' THEN 'Unknown / no tag' ELSE source END),
 traffic AS (SELECT traffic_classification classification,sum(action_count)::bigint n FROM cur_all WHERE (p_measure='photo_opens' AND event_type='view' AND photo_id<>'') OR (p_measure='album_opens' AND event_type='album_open' AND photo_id='') OR (p_measure='downloads' AND event_type='download') OR (p_measure='favorites' AND event_type='favorite') OR (p_measure='shares' AND event_type='share') GROUP BY traffic_classification),
 impact0 AS (SELECT album_key,sum(action_count)::bigint inclusive,coalesce(sum(action_count)FILTER(WHERE traffic_classification IN('audience','unclassified')),0)::bigint conservative FROM cur_all WHERE (p_measure='photo_opens' AND event_type='view' AND photo_id<>'') OR (p_measure='album_opens' AND event_type='album_open' AND photo_id='') OR (p_measure='downloads' AND event_type='download') OR (p_measure='favorites' AND event_type='favorite') OR (p_measure='shares' AND event_type='share') GROUP BY album_key),
 impact AS (SELECT i.*,row_number()OVER(ORDER BY inclusive DESC,album_key)::integer ir,row_number()OVER(ORDER BY conservative DESC,album_key)::integer cr FROM impact0 i),
 today_cov AS (SELECT cutoff_at FROM public.analytics_daily_coverage WHERE bucket_date=v_today AND coverage_state IN ('complete','partial') AND cutoff_at>=v_today::timestamp AT TIME ZONE 'America/Chicago'),
 today_actions AS (SELECT sum(d.action_count)::bigint n FROM public.analytics_daily_actions d WHERE p_include_today AND d.bucket_date=v_today AND (p_scope='all' OR d.album_key=ANY(p_album_keys)) AND (NOT p_public_only OR EXISTS(SELECT 1 FROM visible_albums v WHERE v.album_key=d.album_key)) AND (NOT p_public_only OR d.photo_id='' OR EXISTS(SELECT 1 FROM public.photo_metadata m JOIN visible_albums v ON v.album_key=m.album_key WHERE m.photo_id=d.photo_id AND m.album_key=d.album_key)) AND (p_sport IS NULL OR d.sport=p_sport) AND (p_category IS NULL OR d.photo_category=p_category) AND (p_source IS NULL OR d.source=p_source) AND (p_event_date IS NULL OR d.event_date=p_event_date) AND (p_season IS NULL OR coalesce(extract(year FROM d.event_date)::text,'unknown')=p_season) AND (p_album_event_type IS NULL OR d.album_event_type=p_album_event_type) AND (p_traffic='inclusive' OR d.traffic_classification IN('audience','unclassified')) AND ((p_measure='photo_opens' AND d.event_type='view' AND d.photo_id<>'') OR (p_measure='album_opens' AND d.event_type='album_open' AND d.photo_id='') OR (p_measure='downloads' AND d.event_type='download') OR (p_measure='favorites' AND d.event_type='favorite') OR (p_measure='shares' AND d.event_type='share'))),
 pub_albums AS (SELECT album_key,max(published_at) published_at FROM album_keys GROUP BY album_key),
 age_days AS (SELECT p.album_key,p.published_at,g n,(p.published_at AT TIME ZONE 'America/Chicago')::date+g bucket_date FROM pub_albums p CROSS JOIN generate_series(0,v_current_days-1) g WHERE p_compare='publication_age' AND p.published_at IS NOT NULL),
 age_series AS (SELECT a.*,CASE WHEN a.bucket_date>=v_today THEN 'partial' ELSE c.coverage_state END coverage_state,CASE WHEN c.coverage_state='complete' AND a.bucket_date<v_today THEN coalesce(sum(d.action_count),0)::bigint END n_actions FROM age_days a LEFT JOIN public.analytics_daily_coverage c USING(bucket_date) LEFT JOIN public.analytics_daily_actions d ON d.bucket_date=a.bucket_date AND d.album_key=a.album_key AND (NOT p_public_only OR d.photo_id='' OR EXISTS(SELECT 1 FROM public.photo_metadata m JOIN visible_albums v ON v.album_key=m.album_key WHERE m.photo_id=d.photo_id AND m.album_key=d.album_key)) AND (p_sport IS NULL OR d.sport=p_sport) AND (p_category IS NULL OR d.photo_category=p_category) AND (p_source IS NULL OR d.source=p_source) AND (p_event_date IS NULL OR d.event_date=p_event_date) AND (p_season IS NULL OR coalesce(extract(year FROM d.event_date)::text,'unknown')=p_season) AND (p_album_event_type IS NULL OR d.album_event_type=p_album_event_type) AND (p_traffic='inclusive' OR d.traffic_classification IN('audience','unclassified')) AND ((p_measure='photo_opens' AND d.event_type='view' AND d.photo_id<>'') OR (p_measure='album_opens' AND d.event_type='album_open' AND d.photo_id='') OR (p_measure='downloads' AND d.event_type='download') OR (p_measure='favorites' AND d.event_type='favorite') OR (p_measure='shares' AND d.event_type='share')) GROUP BY a.album_key,a.published_at,a.n,a.bucket_date,c.coverage_state),
 age_albums AS (SELECT album_key,published_at,CASE WHEN bool_and(coverage_state='complete') THEN sum(n_actions) END total,CASE WHEN bool_or(coverage_state IS NULL OR coverage_state='unavailable') THEN 'unavailable' WHEN bool_or(coverage_state='partial') THEN 'partial' ELSE 'complete' END coverage,jsonb_agg(to_jsonb(n_actions)ORDER BY n) series FROM age_series GROUP BY album_key,published_at)
 SELECT jsonb_build_object(
  'coverage',cc.state,'previousCoverage',pc.state,'observedTotal',coalesce((SELECT sum(action_count)FROM cm),0),'total',CASE WHEN cc.state='complete'THEN coalesce((SELECT sum(action_count)FROM cm),0)END,'previousTotal',CASE WHEN pc.state='complete'THEN coalesce((SELECT sum(action_count)FROM pm),0)END,
  'daily',(SELECT coalesce(jsonb_agg(jsonb_build_object('date',c.bucket_date,'coverage',coalesce(c.coverage_state,'unavailable'),'observed',CASE WHEN c.coverage_state IN ('complete','partial') THEN coalesce(d.n,0)END,'count',CASE WHEN c.coverage_state='complete'THEN coalesce(d.n,0)END)ORDER BY c.bucket_date),'[]')FROM coverage c LEFT JOIN daily_counts d USING(bucket_date) WHERE c.bucket_date BETWEEN p_start AND p_end),
  'albums',(SELECT coalesce(jsonb_agg(jsonb_build_object('albumKey',a.album_key,'count',a.n,'previousCount',a.pn,'difference',CASE WHEN cc.state='complete'AND pc.state='complete'THEN a.n-a.pn END,'risingValue',CASE WHEN cc.state='complete'AND pc.state='complete'THEN CASE WHEN v_current_days=v_previous_days THEN a.n-a.pn ELSE a.n::numeric/v_current_days-a.pn::numeric/v_previous_days END END,'measures',a.measures,'lastActivity',a.last_at,'publicationAt',a.published_at)ORDER BY a.n DESC NULLS LAST,a.album_key),'[]')FROM albums a),
  'photos',(SELECT coalesce(jsonb_agg(jsonb_build_object('photoId',p.photo_id,'albumKey',p.album_key,'count',p.n,'previousCount',p.pn,'difference',CASE WHEN cc.state='complete'AND pc.state='complete'THEN p.n-p.pn END,'risingValue',p.rising,'measures',p.measures,'lastActivity',p.last_at,'imageUrl',NULL)ORDER BY p.rn),'[]')FROM page p),
  'photoPagination',jsonb_build_object('page',x.page,'pageSize',CASE WHEN p_export THEN 0 ELSE p_photo_page_size END,'total',x.total,'pageCount',CASE WHEN p_export OR p_photo_page_size=0 THEN 0 ELSE ceil(x.total::numeric/p_photo_page_size)::integer END,'rank',p_photo_rank),
  'albumOnlyActions',(SELECT coalesce(jsonb_agg(jsonb_build_object('albumKey',k.album_key,'count',CASE WHEN c.album_key IS NOT NULL THEN c.n WHEN cc.state='complete'THEN 0 END,'previousCount',CASE WHEN p.album_key IS NOT NULL THEN p.n WHEN pc.state='complete'THEN 0 END,'difference',CASE WHEN cc.state='complete'AND pc.state='complete'THEN coalesce(c.n,0)-coalesce(p.n,0)END,'lastActivity',c.last_at)ORDER BY coalesce(c.n,0)DESC,k.album_key),'[]')FROM aok k LEFT JOIN cao c USING(album_key)LEFT JOIN pao p USING(album_key)),
  'sources',jsonb_build_object('arrivals',(SELECT coalesce(jsonb_agg(jsonb_build_object('source',source,'count',n)ORDER BY n DESC,source),'[]')FROM sources WHERE source_kind='tagged_arrival'),'openLocations',(SELECT coalesce(jsonb_agg(jsonb_build_object('source',source,'count',n)ORDER BY n DESC,source),'[]')FROM sources WHERE source_kind='internal_open_location'),'unknown',coalesce((SELECT sum(n)FROM sources WHERE source_kind='unknown'),0)),
  'traffic',(SELECT coalesce(jsonb_agg(jsonb_build_object('classification',classification,'count',n)ORDER BY n DESC,classification),'[]')FROM traffic),
  'trafficImpact',(SELECT coalesce(jsonb_agg(jsonb_build_object('albumKey',album_key,'inclusive',inclusive,'conservative',conservative,'excluded',inclusive-conservative,'inclusiveRank',ir,'conservativeRank',cr)ORDER BY ir,album_key),'[]')FROM impact),
  'today',jsonb_build_object('date',v_today,'count',CASE WHEN p_include_today AND EXISTS(SELECT 1 FROM today_cov)THEN coalesce((SELECT n FROM today_actions),0)END,'asOf',CASE WHEN p_include_today THEN(SELECT cutoff_at FROM today_cov)END),
  'dataAsOf',(SELECT max(reconciled_at)FROM coverage WHERE bucket_date BETWEEN p_start AND p_end),'preservedSince',(SELECT min(bucket_date)FROM public.analytics_daily_coverage),'catalogueBasis',coalesce((SELECT string_agg(DISTINCT catalogue_basis,', ')FROM coverage WHERE bucket_date BETWEEN p_start AND p_end),'unavailable'),
  'publicationAge',CASE WHEN p_compare='publication_age'THEN jsonb_build_object('available',EXISTS(SELECT 1 FROM age_albums),'label',CASE WHEN EXISTS(SELECT 1 FROM age_albums)THEN format('Each album uses its first %s calendar day%s after the recorded first publication time. Albums with missing daily history remain unavailable.',v_current_days,CASE WHEN v_current_days=1 THEN '' ELSE 's' END)ELSE'No selected album has a recorded first publication time.'END,'days',v_current_days,'albums',(SELECT coalesce(jsonb_agg(jsonb_build_object('albumKey',album_key,'publishedAt',published_at,'total',total,'coverage',coverage,'series',series)ORDER BY total DESC NULLS LAST,album_key),'[]')FROM age_albums),'missingAlbumKeys',(SELECT coalesce(jsonb_agg(album_key ORDER BY album_key),'[]')FROM pub_albums WHERE published_at IS NULL))ELSE jsonb_build_object('available',false,'label','Choose publication-age comparison to align albums from their recorded first publication dates.','days',v_current_days,'albums','[]'::jsonb,'missingAlbumKeys','[]'::jsonb)END
 ) INTO v_result FROM cc CROSS JOIN pc CROSS JOIN page_meta x;
 RETURN v_result;
END $$;


ALTER FUNCTION "public"."analytics_read_scheduled_gallery_report"("p_start" "date", "p_end" "date", "p_measure" "text", "p_scope" "text", "p_album_keys" "text"[], "p_sport" "text", "p_category" "text", "p_source" "text", "p_event_date" "date", "p_season" "text", "p_album_event_type" "text", "p_compare" "text", "p_compare_start" "date", "p_compare_end" "date", "p_traffic" "text", "p_public_only" boolean, "p_photo_page" integer, "p_photo_page_size" integer, "p_photo_rank" "text", "p_export" boolean, "p_include_today" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_recheck_posthog_event_eligibility"("p_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE e public.analytics_events_v2%ROWTYPE; result jsonb; effective_classification text; origin_value text;
BEGIN
 IF current_user <> 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 SELECT payload, origin INTO result, origin_value FROM public.analytics_posthog_outbox WHERE event_id=p_event_id FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF origin_value='classification_control' THEN
   IF result->>'server_provenance'='classification_correction' AND result ? 'target_event_id' AND result ? 'classification_version' AND result ? 'classification' THEN RETURN result; END IF;
   RETURN NULL;
 END IF;
 SELECT * INTO e FROM public.analytics_events_v2 WHERE event_id=p_event_id;
 IF NOT FOUND THEN
  DELETE FROM public.analytics_posthog_outbox WHERE event_id=p_event_id AND origin='event' AND status IN ('pending','failed');
  RETURN NULL;
 END IF;
 SELECT classification INTO effective_classification FROM public.analytics_event_v2_classifications
   WHERE event_id=p_event_id ORDER BY classification_version DESC LIMIT 1;
 IF NOT e.export_eligible OR e.traffic_context<>'audience' OR coalesce(effective_classification,e.traffic_context) NOT IN ('audience','unclassified')
   OR e.anonymous_browser_id IS NULL OR e.visit_id IS NULL OR e.received_at<now()-interval '90 days' THEN
  DELETE FROM public.analytics_posthog_outbox WHERE event_id=p_event_id AND origin='event' AND status IN ('pending','failed');
  RETURN NULL;
 END IF;
 IF (SELECT locked_until>now() FROM public.analytics_posthog_outbox WHERE event_id=p_event_id) IS NOT TRUE THEN RETURN NULL; END IF;
 RETURN result || jsonb_build_object('export_eligible',e.export_eligible,'traffic_context',coalesce(effective_classification,e.traffic_context),'properties',e.properties,'anonymous_browser_id',e.anonymous_browser_id,'visit_id',e.visit_id);
END $$;


ALTER FUNCTION "public"."analytics_recheck_posthog_event_eligibility"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_reconcile_intelligence_delivery"("p_delivery_id" "uuid", "p_state" "text", "p_provider_message_id" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_state NOT IN ('accepted','missing','unavailable') THEN RAISE EXCEPTION 'invalid intelligence delivery reconciliation'; END IF;
  UPDATE public.analytics_intelligence_deliveries SET status=CASE WHEN p_state='accepted' THEN 'accepted' WHEN p_state='missing' THEN 'pending' ELSE 'unavailable' END, provider_message_id=coalesce(p_provider_message_id,provider_message_id), leased_until=NULL, available_at=CASE WHEN p_state='missing' THEN clock_timestamp() ELSE available_at END, updated_at=clock_timestamp() WHERE id=p_delivery_id AND status='ambiguous';
  IF NOT FOUND THEN RAISE EXCEPTION 'intelligence delivery is not ambiguous'; END IF;
END $$;


ALTER FUNCTION "public"."analytics_reconcile_intelligence_delivery"("p_delivery_id" "uuid", "p_state" "text", "p_provider_message_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_record_classification_correction"("p_event_id" bigint, "p_classification" "text", "p_note" "text", "p_corrected_by" "uuid", "p_reverse" boolean DEFAULT false) RETURNS TABLE("correction_id" bigint, "classification" "text", "classification_version" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
  event_row public.engagement_events%ROWTYPE;
  event_day_chicago date;
  current_version integer;
  target_classification text;
  inserted_id bigint;
BEGIN
  IF char_length(trim(p_note)) NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'an auditable reason is required';
  END IF;
  IF p_classification NOT IN (
    'audience', 'operator', 'test', 'known_crawler', 'suspected_automation', 'unclassified'
  ) THEN RAISE EXCEPTION 'unsupported classification';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('analytics-classification:' || p_event_id::text));
  SELECT * INTO event_row
  FROM public.engagement_events
  WHERE id = p_event_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'retained event is unavailable'; END IF;

  event_day_chicago := (event_row.created_at AT TIME ZONE 'America/Chicago')::date;
  IF EXISTS (
    SELECT 1 FROM public.analytics_daily_coverage
    WHERE bucket_date = event_day_chicago AND frozen_at IS NOT NULL
  ) THEN RAISE EXCEPTION 'that day is frozen after raw expiry';
  END IF;

  SELECT greatest(
    coalesce((
      SELECT max(correction.classification_version)
      FROM public.engagement_classification_corrections correction
      WHERE correction.engagement_event_id = p_event_id
    ), 1),
    coalesce((
      SELECT base.classification_version
      FROM public.engagement_event_classifications base
      WHERE base.engagement_event_id = p_event_id
    ), 1)
  ) INTO current_version;

  IF p_reverse THEN
    SELECT prior.classification INTO target_classification
    FROM (
      SELECT correction.classification,
        row_number() OVER (
          ORDER BY correction.classification_version DESC,
            correction.corrected_at DESC, correction.id DESC
        ) AS position
      FROM public.engagement_classification_corrections correction
      WHERE correction.engagement_event_id = p_event_id
    ) prior
    WHERE prior.position = 2;

    IF target_classification IS NULL THEN
      SELECT effective.effective_classification INTO target_classification
      FROM analytics_private.effective_engagement_events effective
      WHERE effective.id = p_event_id;
      -- The current latest correction is what the view exposes. With no prior
      -- correction, reconstruct the base/heuristic state explicitly.
      IF EXISTS (
        SELECT 1 FROM public.engagement_classification_corrections
        WHERE engagement_event_id = p_event_id
      ) THEN
        SELECT CASE
          WHEN event_row.traffic_context = 'operator' THEN 'operator'
          WHEN event_row.traffic_context = 'test' THEN 'test'
          WHEN EXISTS (
            SELECT 1 FROM analytics_private.suspected_automation_sessions suspected
            WHERE suspected.session_hash = event_row.session_hash
          ) THEN 'suspected_automation'
          ELSE coalesce(base.classification, 'unclassified')
        END INTO target_classification
        FROM (SELECT 1) seed
        LEFT JOIN public.engagement_event_classifications base
          ON base.engagement_event_id = p_event_id;
      END IF;
    END IF;
  ELSE
    target_classification := p_classification;
  END IF;

  INSERT INTO public.engagement_classification_corrections (
    engagement_event_id, classification, classification_version,
    note, corrected_by, reason_flags
  ) VALUES (
    p_event_id, target_classification, current_version + 1,
    trim(p_note), p_corrected_by,
    CASE WHEN p_reverse THEN ARRAY['manual_reversal']::text[]
      ELSE ARRAY['manual_correction']::text[] END
  ) RETURNING id INTO inserted_id;

  PERFORM analytics_private.reconcile_daily_actions(event_day_chicago, now());
  REFRESH MATERIALIZED VIEW public.photo_popularity;
  REFRESH MATERIALIZED VIEW public.album_popularity;
  REFRESH MATERIALIZED VIEW public.album_top_photo;

  RETURN QUERY SELECT inserted_id, target_classification, current_version + 1;
END;
$$;


ALTER FUNCTION "public"."analytics_record_classification_correction"("p_event_id" bigint, "p_classification" "text", "p_note" "text", "p_corrected_by" "uuid", "p_reverse" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_record_collection_delivery"("p_schema_version" smallint, "p_outcome" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_reason text := CASE WHEN p_outcome = 'rejected' THEN coalesce(p_reason, 'not_recorded') ELSE coalesce(p_reason, 'none') END;
BEGIN
 IF current_user <> 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 IF p_schema_version NOT IN (1,2) OR p_outcome NOT IN ('accepted','rejected','duplicate')
  OR (p_outcome = 'rejected' AND v_reason NOT IN ('known_crawler','invalid_json','invalid_event','unknown_target','target_lookup_failed','album_lookup_failed','accept_failed','not_recorded'))
  OR (p_outcome <> 'rejected' AND v_reason <> 'none')
 THEN RAISE EXCEPTION 'invalid collection counter' USING ERRCODE='22023'; END IF;
 INSERT INTO public.analytics_collection_delivery_counters(bucket_date,schema_version,outcome,reason,count)
 VALUES ((now() AT TIME ZONE 'America/Chicago')::date,p_schema_version,p_outcome,v_reason,1)
 ON CONFLICT(bucket_date,schema_version,outcome,reason) DO UPDATE SET count=analytics_collection_delivery_counters.count+1;
END $$;


ALTER FUNCTION "public"."analytics_record_collection_delivery"("p_schema_version" smallint, "p_outcome" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_record_event_v2_classification"("p_event_id" "uuid", "p_classification" "text", "p_note" "text", "p_corrected_by" "uuid", "p_reverse" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
DECLARE
  event_row public.analytics_events_v2%ROWTYPE;
  next_version integer;
  effective_classification text;
  control_id uuid;
  delivery_potentially_attempted boolean;
  eligible_for_export boolean;
BEGIN
  IF current_user <> 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE = '42501'; END IF;
  IF p_corrected_by IS NULL OR p_note IS NULL OR char_length(btrim(p_note)) NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'valid correction evidence is required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO event_row FROM public.analytics_events_v2 WHERE event_id = p_event_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'retained event not found' USING ERRCODE = 'P0002'; END IF;
  effective_classification := CASE WHEN p_reverse THEN event_row.traffic_context ELSE p_classification END;
  IF effective_classification NOT IN ('audience','operator','test','known_crawler','suspected_automation','unclassified','self_excluded') THEN
    RAISE EXCEPTION 'invalid classification' USING ERRCODE = '22023';
  END IF;
  SELECT coalesce(max(classification_version), 0) + 1 INTO next_version
    FROM public.analytics_event_v2_classifications WHERE event_id = p_event_id;
  INSERT INTO public.analytics_event_v2_classifications(event_id, classification_version, classification, note, corrected_by, reversed)
    VALUES (p_event_id, next_version, effective_classification, btrim(p_note), p_corrected_by, p_reverse);

  -- A lease means a worker may already be transmitting the original event. Capture
  -- that fact before changing queued receipts so a correction is never stranded.
  SELECT event_row.posthog_attempted_at IS NOT NULL OR EXISTS(
    SELECT 1 FROM public.analytics_posthog_outbox
    WHERE event_id = p_event_id AND origin = 'event'
      AND (status IN ('submitted','confirmed') OR attempts > 0 OR locked_until IS NOT NULL)
  ) INTO delivery_potentially_attempted;
  eligible_for_export := event_row.export_eligible
    AND event_row.traffic_context = 'audience'
    AND effective_classification IN ('audience','unclassified')
    AND event_row.anonymous_browser_id IS NOT NULL AND event_row.visit_id IS NOT NULL
    AND event_row.received_at >= now()-interval '90 days';
  IF NOT eligible_for_export THEN
    -- A queued record has not been accepted by the provider and can be suppressed.
    DELETE FROM public.analytics_posthog_outbox
      WHERE event_id = p_event_id AND origin = 'event' AND status IN ('pending','failed');
  ELSIF NOT EXISTS (SELECT 1 FROM public.analytics_posthog_outbox WHERE event_id=p_event_id AND origin='event') THEN
    -- A correction to audience/unclassified restores an eligible retained event,
    -- but never creates an export for an originally unconsented event.
    INSERT INTO public.analytics_posthog_outbox(event_id,payload)
    VALUES (event_row.event_id, jsonb_build_object(
      'event_id',event_row.event_id,'schema_version',event_row.schema_version,'event_name',event_row.event_name,
      'occurred_at',event_row.occurred_at,'received_at',event_row.received_at,'anonymous_browser_id',event_row.anonymous_browser_id,
      'visit_id',event_row.visit_id,'traffic_context',event_row.traffic_context,'export_eligible',event_row.export_eligible,'properties',event_row.properties
    ));
  END IF;
  IF delivery_potentially_attempted THEN
    control_id := gen_random_uuid();
    PERFORM set_config('analytics.classification_control_write', 'on', true);
    INSERT INTO public.analytics_posthog_outbox(event_id, payload, origin, target_event_id)
    VALUES (
      control_id,
      jsonb_build_object(
        'event_id', control_id,
        'event_name', 'analytics_classification_changed',
        'occurred_at', now(),
        'target_event_id', p_event_id,
        'classification_version', next_version,
        'classification', effective_classification,
        'server_provenance', 'classification_correction'
      ),
      'classification_control', p_event_id
    );
    PERFORM set_config('analytics.classification_control_write', 'off', true);
  END IF;
  RETURN jsonb_build_object(
    'event_id', p_event_id, 'classification_version', next_version,
    'classification', effective_classification, 'control_event_id', control_id
  );
END;
$$;


ALTER FUNCTION "public"."analytics_record_event_v2_classification"("p_event_id" "uuid", "p_classification" "text", "p_note" "text", "p_corrected_by" "uuid", "p_reverse" boolean) OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."analytics_intelligence_actions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "scope_key" "text" NOT NULL,
    "kind" "text" NOT NULL,
    "finding_id" "text",
    "target" "jsonb",
    "actual_at" timestamp with time zone,
    "hypothesis" "text",
    "primary_measure" "text",
    "follow_up_at" timestamp with time zone,
    "note" "text",
    "reverses_action_id" "uuid",
    "change_type" "text",
    "channel" "text",
    "campaign" "text",
    "release" "text",
    "variant" "text",
    "outcome" "text",
    "outcome_count" integer,
    "observation_days" integer,
    "target_context" "jsonb",
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "analytics_intelligence_action_target_contract" CHECK (((("kind" = 'record'::"text") AND ("target" IS NOT NULL)) OR (("kind" = ANY (ARRAY['dismiss'::"text", 'snooze'::"text"])) AND ("finding_id" IS NOT NULL) AND ("target" IS NOT NULL)) OR (("kind" = 'undo'::"text") AND ("reverses_action_id" IS NOT NULL)))),
    CONSTRAINT "analytics_intelligence_actions_campaign_check" CHECK ((("campaign" IS NULL) OR ("length"("campaign") <= 120))),
    CONSTRAINT "analytics_intelligence_actions_change_type_check" CHECK ((("change_type" IS NULL) OR ("change_type" = ANY (ARRAY['promotion'::"text", 'cover'::"text", 'headline'::"text", 'cta'::"text", 'search_fix'::"text", 'download_repair'::"text", 'shooting'::"text", 'editing'::"text", 'other'::"text"])))),
    CONSTRAINT "analytics_intelligence_actions_channel_check" CHECK ((("channel" IS NULL) OR ("length"("channel") <= 80))),
    CONSTRAINT "analytics_intelligence_actions_check" CHECK ((("kind" = 'record'::"text") = (("actual_at" IS NOT NULL) AND ("hypothesis" IS NOT NULL) AND ("primary_measure" IS NOT NULL) AND ("follow_up_at" IS NOT NULL)))),
    CONSTRAINT "analytics_intelligence_actions_check1" CHECK ((("kind" = 'undo'::"text") = ("reverses_action_id" IS NOT NULL))),
    CONSTRAINT "analytics_intelligence_actions_hypothesis_check" CHECK ((("hypothesis" IS NULL) OR ("length"("hypothesis") <= 500))),
    CONSTRAINT "analytics_intelligence_actions_kind_check" CHECK (("kind" = ANY (ARRAY['record'::"text", 'dismiss'::"text", 'snooze'::"text", 'undo'::"text"]))),
    CONSTRAINT "analytics_intelligence_actions_note_check" CHECK ((("note" IS NULL) OR ("length"("note") <= 1000))),
    CONSTRAINT "analytics_intelligence_actions_observation_days_check" CHECK ((("observation_days" IS NULL) OR (("observation_days" >= 1) AND ("observation_days" <= 365)))),
    CONSTRAINT "analytics_intelligence_actions_outcome_check" CHECK ((("outcome" IS NULL) OR ("outcome" = ANY (ARRAY['unknown'::"text", 'inquiry'::"text", 'booking'::"text", 'other'::"text"])))),
    CONSTRAINT "analytics_intelligence_actions_outcome_count_check" CHECK ((("outcome_count" IS NULL) OR (("outcome_count" >= 0) AND ("outcome_count" <= 100000)))),
    CONSTRAINT "analytics_intelligence_actions_primary_measure_check" CHECK ((("primary_measure" IS NULL) OR ("primary_measure" = ANY (ARRAY['photo_opens'::"text", 'album_opens'::"text", 'downloads'::"text", 'favorites'::"text", 'shares'::"text", 'page_views'::"text"])))),
    CONSTRAINT "analytics_intelligence_actions_release_check" CHECK ((("release" IS NULL) OR ("length"("release") <= 120))),
    CONSTRAINT "analytics_intelligence_actions_target_context_check" CHECK ((("target_context" IS NULL) OR ("jsonb_typeof"("target_context") = 'object'::"text"))),
    CONSTRAINT "analytics_intelligence_actions_variant_check" CHECK ((("variant" IS NULL) OR ("length"("variant") <= 120)))
);


ALTER TABLE "public"."analytics_intelligence_actions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_record_intelligence_action"("p_owner_id" "uuid", "p_scope_key" "text", "p_kind" "text", "p_finding_id" "text", "p_target" "jsonb", "p_actual_at" timestamp with time zone, "p_hypothesis" "text", "p_primary_measure" "text", "p_follow_up_at" timestamp with time zone, "p_note" "text", "p_reverses_action_id" "uuid", "p_change_type" "text", "p_channel" "text", "p_campaign" "text", "p_release" "text", "p_variant" "text", "p_outcome" "text", "p_outcome_count" integer, "p_observation_days" integer, "p_target_context" "jsonb") RETURNS "public"."analytics_intelligence_actions"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE original public.analytics_intelligence_actions%ROWTYPE; result public.analytics_intelligence_actions%ROWTYPE; policy text; incident_scope text;
BEGIN
  SELECT retention_policy INTO policy FROM public.analytics_intelligence_preferences WHERE owner_id=p_owner_id FOR UPDATE;
  IF coalesce(policy,'undecided')='undecided' THEN RAISE EXCEPTION 'retention decision required before private intelligence writes'; END IF;
  IF p_kind NOT IN ('record','dismiss','snooze','undo') THEN RAISE EXCEPTION 'invalid intelligence action'; END IF;
  IF p_kind='undo' THEN
    SELECT * INTO original FROM public.analytics_intelligence_actions WHERE id=p_reverses_action_id AND owner_id=p_owner_id FOR UPDATE;
    IF NOT FOUND OR original.kind NOT IN ('dismiss','snooze') THEN RAISE EXCEPTION 'undo action is not owned or reversible'; END IF;
    IF EXISTS (SELECT 1 FROM public.analytics_intelligence_actions later WHERE later.owner_id=p_owner_id AND later.scope_key=original.scope_key AND later.finding_id=original.finding_id AND later.kind IN ('dismiss','snooze') AND later.created_at>original.created_at) THEN RAISE EXCEPTION 'undo action is no longer the active lifecycle action'; END IF;
    SELECT * INTO result FROM public.analytics_intelligence_actions WHERE owner_id=p_owner_id AND reverses_action_id=p_reverses_action_id AND kind='undo'; IF FOUND THEN RETURN result; END IF;
    INSERT INTO public.analytics_intelligence_actions(owner_id,scope_key,kind,finding_id,target,reverses_action_id,target_context)
    VALUES(p_owner_id,original.scope_key,'undo',original.finding_id,original.target,p_reverses_action_id,original.target_context) RETURNING * INTO result;
    INSERT INTO public.analytics_intelligence_finding_lifecycle(owner_id,scope_key,finding_id,status,snoozed_until,updated_at)
    VALUES(p_owner_id,original.scope_key,original.finding_id,'open',NULL,clock_timestamp())
    ON CONFLICT(owner_id,scope_key,finding_id) DO UPDATE SET status='open',snoozed_until=NULL,updated_at=excluded.updated_at;
    SELECT i.scope_key INTO incident_scope FROM public.analytics_intelligence_incidents i
      JOIN public.analytics_intelligence_snapshots s ON s.snapshot_id=i.opened_snapshot_id
      CROSS JOIN LATERAL jsonb_array_elements(s.findings) f
      WHERE i.finding_id=original.finding_id AND (i.scope_key=original.scope_key OR i.scope_key='collection_health' OR i.scope_key=(SELECT public.analytics_intelligence_incident_scope(snap.scope,'rendering_download_reliability') FROM public.analytics_intelligence_snapshot_current c JOIN public.analytics_intelligence_snapshots snap ON snap.snapshot_id=c.snapshot_id WHERE c.scope_key=original.scope_key))
        AND f->>'id'=i.finding_id AND (f->>'rule'='collection_health' OR (f->>'rule'='rendering_download_reliability' AND f->>'id'<>'download-unknown-terminal'))
      ORDER BY (i.scope_key=original.scope_key) DESC LIMIT 1 FOR UPDATE OF i;
    UPDATE public.analytics_intelligence_incidents SET status='open',acknowledged_until=NULL,updated_at=clock_timestamp()
      WHERE scope_key=incident_scope AND finding_id=original.finding_id AND status='acknowledged';
    RETURN result;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.analytics_intelligence_snapshot_current WHERE scope_key=p_scope_key) THEN RAISE EXCEPTION 'unknown intelligence scope'; END IF;
  IF p_target IS NULL OR jsonb_typeof(p_target)<>'object' OR p_target->>'kind' NOT IN ('gallery','album','photo','site','page') THEN RAISE EXCEPTION 'public action target required'; END IF;
  IF (p_target->>'kind'='album' AND nullif(p_target->>'albumKey','') IS NULL) OR (p_target->>'kind' IN ('photo','page') AND nullif(p_target->>'id','') IS NULL) THEN RAISE EXCEPTION 'invalid public action target'; END IF;
  IF p_kind='record' THEN p_follow_up_at:=(((p_actual_at AT TIME ZONE CASE WHEN p_target->>'kind' IN ('gallery','album','photo') THEN 'America/Chicago' ELSE 'UTC' END)::date+p_observation_days+1)::timestamp AT TIME ZONE CASE WHEN p_target->>'kind' IN ('gallery','album','photo') THEN 'America/Chicago' ELSE 'UTC' END); END IF;
  IF p_kind='record' AND (p_actual_at IS NULL OR p_actual_at>clock_timestamp() OR nullif(p_hypothesis,'') IS NULL OR p_primary_measure NOT IN ('photo_opens','album_opens','downloads','favorites','shares','page_views') OR p_follow_up_at IS NULL OR p_follow_up_at<=p_actual_at OR p_change_type IS NULL OR p_observation_days NOT BETWEEN 1 AND 365 OR p_outcome_count NOT BETWEEN 0 AND 100000) THEN RAISE EXCEPTION 'record action context required'; END IF;
  IF p_kind IN ('dismiss','snooze') AND p_finding_id IS NULL THEN RAISE EXCEPTION 'finding reference required'; END IF;
  INSERT INTO public.analytics_intelligence_actions(owner_id,scope_key,kind,finding_id,target,actual_at,hypothesis,primary_measure,follow_up_at,note,change_type,channel,campaign,release,variant,outcome,outcome_count,observation_days,target_context)
  VALUES(p_owner_id,p_scope_key,p_kind,p_finding_id,p_target,p_actual_at,p_hypothesis,p_primary_measure,p_follow_up_at,p_note,p_change_type,p_channel,p_campaign,p_release,p_variant,p_outcome,p_outcome_count,p_observation_days,p_target_context) RETURNING * INTO result;
  IF p_kind IN ('dismiss','snooze') THEN
    INSERT INTO public.analytics_intelligence_finding_lifecycle(owner_id,scope_key,finding_id,status,snoozed_until,updated_at)
    VALUES(p_owner_id,p_scope_key,p_finding_id,p_kind,CASE WHEN p_kind='snooze' THEN clock_timestamp()+interval '7 days' END,clock_timestamp())
    ON CONFLICT(owner_id,scope_key,finding_id) DO UPDATE SET status=excluded.status,snoozed_until=excluded.snoozed_until,updated_at=excluded.updated_at;
    SELECT i.scope_key INTO incident_scope FROM public.analytics_intelligence_incidents i
      JOIN public.analytics_intelligence_snapshots s ON s.snapshot_id=i.opened_snapshot_id
      CROSS JOIN LATERAL jsonb_array_elements(s.findings) f
      WHERE i.finding_id=p_finding_id AND (i.scope_key=p_scope_key OR i.scope_key='collection_health' OR i.scope_key=(SELECT public.analytics_intelligence_incident_scope(snap.scope,'rendering_download_reliability') FROM public.analytics_intelligence_snapshot_current c JOIN public.analytics_intelligence_snapshots snap ON snap.snapshot_id=c.snapshot_id WHERE c.scope_key=p_scope_key))
        AND f->>'id'=i.finding_id AND (f->>'rule'='collection_health' OR (f->>'rule'='rendering_download_reliability' AND f->>'id'<>'download-unknown-terminal'))
      ORDER BY (i.scope_key=p_scope_key) DESC LIMIT 1 FOR UPDATE OF i;
    UPDATE public.analytics_intelligence_incidents SET status='acknowledged',acknowledged_until=clock_timestamp()+CASE WHEN p_kind='dismiss' THEN interval '30 days' ELSE interval '7 days' END,updated_at=clock_timestamp()
      WHERE scope_key=incident_scope AND finding_id=p_finding_id AND status IN ('open','acknowledged');
  END IF;
  RETURN result;
END $$;


ALTER FUNCTION "public"."analytics_record_intelligence_action"("p_owner_id" "uuid", "p_scope_key" "text", "p_kind" "text", "p_finding_id" "text", "p_target" "jsonb", "p_actual_at" timestamp with time zone, "p_hypothesis" "text", "p_primary_measure" "text", "p_follow_up_at" timestamp with time zone, "p_note" "text", "p_reverses_action_id" "uuid", "p_change_type" "text", "p_channel" "text", "p_campaign" "text", "p_release" "text", "p_variant" "text", "p_outcome" "text", "p_outcome_count" integer, "p_observation_days" integer, "p_target_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_record_intelligence_lifecycle"("p_report_id" "uuid", "p_now" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_scope text; v_coverage text; v_evidence jsonb; v_scope_json jsonb; v_source_window jsonb; v_finding jsonb; v_key text; v_rule text; v_operational boolean; v_compatible boolean; v_prior public.analytics_intelligence_incidents%ROWTYPE; v_incident public.analytics_intelligence_incidents%ROWTYPE; owner uuid; brief_id uuid; brief_body text; brief_subject text;
BEGIN
  SELECT scope_key,coverage,evidence,scope INTO v_scope,v_coverage,v_evidence,v_scope_json FROM public.analytics_intelligence_snapshots WHERE snapshot_id=p_report_id;
  IF v_scope IS NULL OR p_now IS NULL THEN RAISE EXCEPTION 'invalid intelligence lifecycle report'; END IF;
  v_source_window:=jsonb_build_array(jsonb_build_object('snapshotId',p_report_id,'scope',v_scope_json,'cutoff',(SELECT cutoff_at FROM public.analytics_intelligence_snapshots WHERE snapshot_id=p_report_id),'timezone',CASE WHEN v_scope_json->>'kind'='gallery' THEN 'America/Chicago' ELSE 'UTC' END,'current',CASE WHEN v_scope_json->>'kind'='gallery' THEN jsonb_build_object('start',v_scope_json#>>'{query,start}','end',v_scope_json#>>'{query,end}') ELSE v_evidence#>'{siteWindows,current}' END,'previous',v_evidence#>'{siteWindows,previous}'));
  FOR v_finding IN SELECT value FROM jsonb_array_elements((SELECT findings FROM public.analytics_intelligence_snapshots WHERE snapshot_id=p_report_id)) LOOP
    v_rule:=v_finding->>'rule';
    v_operational:=v_rule='collection_health' OR (v_rule='rendering_download_reliability' AND v_finding->>'id'<>'download-unknown-terminal');
    -- Collection health is shared by cause; render/download failures remain bound to the exact report scope.
    v_key:=public.analytics_intelligence_incident_scope(v_scope_json,v_rule);
    IF v_coverage<>'complete' AND v_key<>'collection_health' THEN CONTINUE; END IF;
    SELECT * INTO v_prior FROM public.analytics_intelligence_incidents WHERE scope_key=v_key AND finding_id=v_finding->>'id' FOR UPDATE;
    INSERT INTO public.analytics_intelligence_incidents(scope_key,finding_id,opened_snapshot_id,last_snapshot_id,status,updated_at)
    VALUES(v_key,v_finding->>'id',p_report_id,p_report_id,'open',p_now)
    ON CONFLICT(scope_key,finding_id) DO UPDATE SET
      opened_snapshot_id=CASE WHEN public.analytics_intelligence_incidents.status='recovered' THEN excluded.opened_snapshot_id ELSE public.analytics_intelligence_incidents.opened_snapshot_id END,
      last_snapshot_id=excluded.last_snapshot_id,recovered_at=NULL,
      status=CASE WHEN public.analytics_intelligence_incidents.status='acknowledged' AND public.analytics_intelligence_incidents.acknowledged_until>p_now THEN 'acknowledged' ELSE 'open' END,updated_at=p_now
    RETURNING * INTO v_incident;
    IF v_operational AND (v_prior.finding_id IS NULL OR v_prior.status='recovered') THEN
      FOR owner IN SELECT owner_id FROM public.analytics_intelligence_preferences WHERE retention_policy<>'undecided' AND dashboard_enabled LOOP
        brief_subject:=CASE WHEN v_rule='collection_health' THEN 'Collection needs attention' ELSE 'Visitor flow needs attention' END;
        brief_body:=coalesce(v_finding->>'title',brief_subject)||E'\n'||coalesce(v_finding->>'explanation','')||E'\n'||coalesce(v_finding->>'action','Inspect the affected flow.')||E'\nThis is an operational incident, not evidence of falling audience activity.';
        INSERT INTO public.analytics_intelligence_briefs(owner_id,scope_key,snapshot_id,period_key,kind,body,findings,snapshot_ids,source_windows,incident_key)
        VALUES(owner,NULL,p_report_id,(p_now AT TIME ZONE 'America/Chicago')::date,'operational',brief_body,jsonb_build_array(v_finding),jsonb_build_array(p_report_id),v_source_window,v_incident.opened_snapshot_id::text||':open')
        ON CONFLICT(owner_id,incident_key) WHERE kind='operational' DO NOTHING RETURNING id INTO brief_id;
        IF brief_id IS NOT NULL THEN
          INSERT INTO public.analytics_intelligence_deliveries(brief_id,channel,sender,destination_verified,preference_enabled,idempotency_key,payload)
          VALUES(brief_id,'dashboard','owned',false,true,'dashboard:'||brief_id::text,jsonb_build_object('subject',brief_subject,'body',brief_body));
          INSERT INTO public.analytics_intelligence_deliveries(brief_id,channel,sender,destination_verified,preference_enabled,idempotency_key,payload,destination)
          SELECT brief_id,'email',p.sender,true,true,'email:'||brief_id::text,jsonb_build_object('subject',brief_subject,'body',brief_body),jsonb_build_object('channel','email','address',p.destination,'verifiedAt',p.destination_verified_at)
          FROM public.analytics_intelligence_preferences p WHERE p.owner_id=owner AND p.external_enabled AND p.destination_verified AND p.destination_verified_at IS NOT NULL AND p.destination IS NOT NULL AND p.sender IN ('owned','posthog_native') ON CONFLICT(idempotency_key) DO NOTHING;
        END IF;
      END LOOP;
    END IF;
  END LOOP;
  -- Recovery needs this exact scope (except shared health), complete report coverage,
  -- and the same compatible provider cohort. An absent cohort is not a zero.
  FOR v_incident IN SELECT * FROM public.analytics_intelligence_incidents i
    WHERE (i.scope_key=v_scope OR i.scope_key='collection_health' OR i.scope_key=public.analytics_intelligence_incident_scope(v_scope_json,'rendering_download_reliability')) AND i.status IN ('open','acknowledged') AND (v_coverage='complete' OR i.scope_key='collection_health')
    FOR UPDATE LOOP
    IF EXISTS(SELECT 1 FROM jsonb_array_elements((SELECT findings FROM public.analytics_intelligence_snapshots WHERE snapshot_id=p_report_id)) f WHERE f->>'id'=v_incident.finding_id) THEN CONTINUE; END IF;
    SELECT f->>'rule' INTO v_rule FROM public.analytics_intelligence_snapshots s CROSS JOIN LATERAL jsonb_array_elements(s.findings) f WHERE s.snapshot_id=v_incident.opened_snapshot_id AND f->>'id'=v_incident.finding_id LIMIT 1;
    v_compatible:=CASE
      WHEN v_rule='collection_health' THEN jsonb_typeof(v_evidence->'diagnostics')='array' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_evidence->'diagnostics') d WHERE d->>'type' LIKE '%unavailable%')
      WHEN v_rule='rendering_download_reliability' AND v_incident.finding_id='render-failures' THEN jsonb_typeof(v_evidence->'rendering')='object' AND jsonb_typeof(v_evidence#>'{rendering,observedTerminal}')='number' AND jsonb_typeof(v_evidence#>'{rendering,failed}')='number' AND (v_evidence#>>'{rendering,observedTerminal}')::numeric>=20 AND (v_evidence#>>'{rendering,failed}')::numeric BETWEEN 0 AND 1
      WHEN v_rule='rendering_download_reliability' AND v_incident.finding_id='download-failures' THEN jsonb_typeof(v_evidence->'download')='object' AND jsonb_typeof(v_evidence#>'{download,requests}')='number' AND jsonb_typeof(v_evidence#>'{download,failed}')='number' AND (v_evidence#>>'{download,requests}')::numeric>=20 AND (v_evidence#>>'{download,failed}')::numeric=0
      WHEN v_rule='search_usefulness' THEN jsonb_typeof(v_evidence->'search')='object'
      WHEN v_rule='strong_photo_response' THEN jsonb_typeof(v_evidence->'linkedPhotoResponse')='array' AND jsonb_array_length(v_evidence->'linkedPhotoResponse')>0
      WHEN v_rule='discovery_friction' THEN jsonb_typeof(v_evidence->'albumDiscovery')='array' AND jsonb_array_length(v_evidence->'albumDiscovery')>0
      WHEN v_rule IN ('profile_response','writing_demo_response') THEN jsonb_typeof(v_evidence->'siteJourneys')='array' AND jsonb_array_length(v_evidence->'siteJourneys')>0
      WHEN v_rule='distribution' THEN jsonb_typeof(v_evidence->'distribution')='object'
      WHEN v_rule='follow_up' THEN jsonb_typeof(v_evidence->'followUp')='object'
      WHEN v_rule='momentum' THEN jsonb_typeof(v_evidence->'current')='number' AND jsonb_typeof(v_evidence->'previous')='number' AND v_evidence->>'previousCoverage'='complete'
      ELSE false END;
    IF v_compatible IS NOT TRUE THEN CONTINUE; END IF;
    IF v_rule='rendering_download_reliability' AND EXISTS(SELECT 1 FROM public.analytics_intelligence_snapshots prior WHERE prior.snapshot_id=v_incident.last_snapshot_id AND (prior.scope#>>'{query,end}')::date>(v_scope_json#>>'{query,end}')::date) THEN CONTINUE; END IF;
    UPDATE public.analytics_intelligence_incidents SET status='recovered',recovered_at=p_now,last_snapshot_id=p_report_id,updated_at=p_now WHERE scope_key=v_incident.scope_key AND finding_id=v_incident.finding_id;
    v_operational:=v_rule='collection_health' OR (v_rule='rendering_download_reliability' AND v_incident.finding_id<>'download-unknown-terminal');
    IF v_operational THEN
      FOR owner IN SELECT owner_id FROM public.analytics_intelligence_preferences WHERE retention_policy<>'undecided' AND dashboard_enabled LOOP
        brief_subject:=CASE WHEN v_rule='collection_health' THEN 'Collection recovered' ELSE 'Visitor flow recovered' END;
        brief_body:=brief_subject||E'\nThe same eligible cohort no longer crosses the alert threshold in a complete report. This does not establish that audience behavior changed.';
        INSERT INTO public.analytics_intelligence_briefs(owner_id,scope_key,snapshot_id,period_key,kind,body,snapshot_ids,source_windows,incident_key)
        VALUES(owner,NULL,p_report_id,(p_now AT TIME ZONE 'America/Chicago')::date,'operational',brief_body,jsonb_build_array(p_report_id),v_source_window,v_incident.opened_snapshot_id::text||':recovered')
        ON CONFLICT(owner_id,incident_key) WHERE kind='operational' DO NOTHING RETURNING id INTO brief_id;
        IF brief_id IS NOT NULL THEN
          INSERT INTO public.analytics_intelligence_deliveries(brief_id,channel,sender,destination_verified,preference_enabled,idempotency_key,payload)
          VALUES(brief_id,'dashboard','owned',false,true,'dashboard:'||brief_id::text,jsonb_build_object('subject',brief_subject,'body',brief_body));
          INSERT INTO public.analytics_intelligence_deliveries(brief_id,channel,sender,destination_verified,preference_enabled,idempotency_key,payload,destination)
          SELECT brief_id,'email',p.sender,true,true,'email:'||brief_id::text,jsonb_build_object('subject',brief_subject,'body',brief_body),jsonb_build_object('channel','email','address',p.destination,'verifiedAt',p.destination_verified_at)
          FROM public.analytics_intelligence_preferences p WHERE p.owner_id=owner AND p.external_enabled AND p.destination_verified AND p.destination_verified_at IS NOT NULL AND p.destination IS NOT NULL AND p.sender IN ('owned','posthog_native') ON CONFLICT(idempotency_key) DO NOTHING;
        END IF;
      END LOOP;
    END IF;
  END LOOP;
END $$;


ALTER FUNCTION "public"."analytics_record_intelligence_lifecycle"("p_report_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."analytics_intelligence_outcomes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "action_id" "uuid" NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "outcome" "text" NOT NULL,
    "outcome_count" integer,
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "analytics_intelligence_outcomes_note_check" CHECK ((("note" IS NULL) OR ("length"("note") <= 500))),
    CONSTRAINT "analytics_intelligence_outcomes_outcome_check" CHECK (("outcome" = ANY (ARRAY['unknown'::"text", 'inquiry'::"text", 'booking'::"text", 'other'::"text"]))),
    CONSTRAINT "analytics_intelligence_outcomes_outcome_count_check" CHECK ((("outcome_count" IS NULL) OR (("outcome_count" >= 0) AND ("outcome_count" <= 100000))))
);


ALTER TABLE "public"."analytics_intelligence_outcomes" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_record_intelligence_outcome"("p_owner_id" "uuid", "p_action_id" "uuid", "p_outcome" "text", "p_outcome_count" integer, "p_note" "text") RETURNS "public"."analytics_intelligence_outcomes"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_result public.analytics_intelligence_outcomes;
BEGIN
  IF p_owner_id IS NULL OR p_action_id IS NULL
    OR p_outcome NOT IN ('unknown','inquiry','booking','other')
    OR (p_outcome_count IS NOT NULL AND p_outcome_count NOT BETWEEN 0 AND 100000)
    OR (p_note IS NOT NULL AND (length(p_note) = 0 OR length(p_note) > 500)) THEN
    RAISE EXCEPTION 'invalid intelligence outcome';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.analytics_intelligence_preferences p
    WHERE p.owner_id = p_owner_id AND p.retention_policy <> 'undecided'
  ) THEN
    RAISE EXCEPTION 'intelligence retention decision required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.analytics_intelligence_actions a
    WHERE a.id = p_action_id AND a.owner_id = p_owner_id AND a.kind = 'record'
  ) THEN
    RAISE EXCEPTION 'recorded intelligence action not found for owner';
  END IF;

  INSERT INTO public.analytics_intelligence_outcomes(action_id, owner_id, outcome, outcome_count, note)
  VALUES (p_action_id, p_owner_id, p_outcome, p_outcome_count, p_note)
  RETURNING * INTO v_result;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."analytics_record_intelligence_outcome"("p_owner_id" "uuid", "p_action_id" "uuid", "p_outcome" "text", "p_outcome_count" integer, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_requeue_missing_posthog_events"("p_event_ids" "uuid"[]) RETURNS TABLE("event_id" "uuid")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE requested_ids uuid[];
BEGIN
 IF current_user <> 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 SELECT coalesce(array_agg(value ORDER BY value), ARRAY[]::uuid[]) INTO requested_ids
 FROM (SELECT DISTINCT value FROM unnest(coalesce(p_event_ids, ARRAY[]::uuid[])) value ORDER BY value LIMIT 100) requested;
 UPDATE public.analytics_posthog_outbox o
 SET last_checked_at=now(), last_error_code='provider_reconciliation_missing'
 WHERE o.status='submitted' AND o.event_id=ANY(requested_ids);
 RETURN QUERY WITH requested AS (
  SELECT value AS event_id FROM unnest(requested_ids) value
 ), eligible AS (
  SELECT o.event_id FROM requested r
  JOIN public.analytics_posthog_outbox o ON o.event_id=r.event_id
  LEFT JOIN public.analytics_events_v2 e ON e.event_id=o.event_id
  LEFT JOIN LATERAL (SELECT classification FROM public.analytics_event_v2_classifications c WHERE c.event_id=e.event_id ORDER BY classification_version DESC LIMIT 1) c ON true
  WHERE o.status='submitted' AND o.attempts<12 AND o.submitted_at <= now()-interval '5 minutes'
    AND (o.origin='classification_control' OR (
      e.received_at >= now()-interval '90 days' AND e.export_eligible AND e.traffic_context='audience'
      AND coalesce(c.classification,e.traffic_context) IN ('audience','unclassified')
    ))
 ) UPDATE public.analytics_posthog_outbox o
 SET status='pending', locked_until=NULL, next_attempt_at=now()+interval '30 seconds', last_error_code='provider_reconciliation_missing'
 FROM eligible WHERE o.event_id=eligible.event_id
 RETURNING o.event_id;
END $$;


ALTER FUNCTION "public"."analytics_requeue_missing_posthog_events"("p_event_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_revoke_browser_exports_v2"("p_browser_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
BEGIN
  IF current_user <> 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE = '42501'; END IF;
  INSERT INTO analytics_private.analytics_v2_revoked_browsers(anonymous_browser_id) VALUES (p_browser_id)
  ON CONFLICT (anonymous_browser_id) DO UPDATE SET revoked_at = EXCLUDED.revoked_at;
  -- Preserve submitted/confirmed rows: a provider may already have received them. They are not
  -- a claim that this function deleted provider data. Pending/failed rows have not been accepted
  -- by the provider and are removed before any future claim can deliver them.
  DELETE FROM public.analytics_posthog_outbox o
  USING public.analytics_events_v2 e
  WHERE o.event_id = e.event_id
    AND e.anonymous_browser_id = p_browser_id
    AND o.status IN ('pending','failed');
  UPDATE public.analytics_events_v2
  SET export_eligible = false
  WHERE anonymous_browser_id = p_browser_id AND export_eligible;
END;
$$;


ALTER FUNCTION "public"."analytics_revoke_browser_exports_v2"("p_browser_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_set_intelligence_preferences"("p_owner_id" "uuid", "p_retention_policy" "text", "p_retention_days" integer, "p_daily_enabled" boolean, "p_weekly_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- This is service-only. The server route verifies the signed-in owner before
  -- this atomic preference-and-schedule write; browser roles have no EXECUTE.
  IF p_retention_policy NOT IN ('undecided','until_deleted','days')
     OR (p_retention_policy = 'days' AND (p_retention_days IS NULL OR p_retention_days NOT BETWEEN 1 AND 3650))
     OR (p_retention_policy <> 'days' AND p_retention_days IS NOT NULL) THEN RAISE EXCEPTION 'invalid intelligence retention preference'; END IF;
  INSERT INTO public.analytics_intelligence_preferences(owner_id, retention_policy, retention_days)
  VALUES (p_owner_id, p_retention_policy, p_retention_days)
  ON CONFLICT(owner_id) DO UPDATE SET retention_policy=excluded.retention_policy, retention_days=excluded.retention_days, updated_at=clock_timestamp();
  INSERT INTO public.analytics_intelligence_schedules(owner_id, daily_enabled, weekly_enabled)
  VALUES (p_owner_id, p_daily_enabled, p_weekly_enabled)
  ON CONFLICT(owner_id) DO UPDATE SET daily_enabled=excluded.daily_enabled, weekly_enabled=excluded.weekly_enabled, updated_at=clock_timestamp();
END $$;


ALTER FUNCTION "public"."analytics_set_intelligence_preferences"("p_owner_id" "uuid", "p_retention_policy" "text", "p_retention_days" integer, "p_daily_enabled" boolean, "p_weekly_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_site_actions"("p_period" integer DEFAULT 30, "p_section" "text" DEFAULT 'all'::"text", "p_page" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  output jsonb;
  status_row public.analytics_site_action_summary_status%ROWTYPE;
  end_date date := (now() AT TIME ZONE 'UTC')::date - 1;
  start_date date;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'service role required' USING ERRCODE = '42501';
  END IF;
  IF p_period NOT IN (7,30,90)
    OR p_section NOT IN ('all','profile','writing','demos','photography','other')
    OR p_page NOT BETWEEN 0 AND 1000 THEN
    RAISE EXCEPTION 'invalid report scope' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO status_row
  FROM public.analytics_site_action_summary_status
  WHERE report_name = 'site_actions';
  IF NOT FOUND OR status_row.last_successful_at IS NULL THEN
    RETURN jsonb_build_object(
      'available', false,
      'reason', 'Action summaries have not completed their first refresh. This is not a report of zero activity.'
    );
  END IF;

  -- A snapshot from before midnight cannot certify the rest of that day.
  end_date := least(end_date, (status_row.summary_cutoff_at AT TIME ZONE 'UTC')::date - 1);
  start_date := end_date - p_period + 1;
  WITH scoped AS (
    SELECT *
    FROM public.analytics_site_action_daily
    WHERE p_section = 'all' OR section = p_section
  ), current_pages AS (
    SELECT
      path,
      section,
      coalesce(sum(page_views), 0) AS views,
      jsonb_strip_nulls(jsonb_build_object(
        'page_views', nullif(sum(page_views), 0),
        'contact_clicks', nullif(sum(contact_clicks), 0),
        'external_clicks', nullif(sum(external_clicks), 0),
        'reading_90', nullif(sum(reading_90), 0),
        'active_30', nullif(sum(active_30), 0),
        'demo_last_section', nullif(sum(demo_last_section), 0)
      )) AS measures
    FROM scoped
    WHERE bucket_date BETWEEN start_date AND end_date
      AND page_views + contact_clicks + external_clicks + reading_90 + active_30 + demo_last_section > 0
    GROUP BY path, section
  ), page_info AS (
    SELECT greatest(1, ceil(count(*) / 8.0)::integer) AS page_count
    FROM current_pages
  ), page_window AS (
    SELECT least(p_page, greatest(0, page_count - 1)) AS page, page_count
    FROM page_info
  ), current_totals AS (
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'page_views', nullif(sum(page_views), 0),
      'contact_clicks', nullif(sum(contact_clicks), 0),
      'external_clicks', nullif(sum(external_clicks), 0),
      'reading_90', nullif(sum(reading_90), 0),
      'active_30', nullif(sum(active_30), 0),
      'demo_last_section', nullif(sum(demo_last_section), 0)
    )) AS totals
    FROM scoped WHERE bucket_date BETWEEN start_date AND end_date
  ), previous_totals AS (
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'page_views', nullif(sum(page_views), 0),
      'contact_clicks', nullif(sum(contact_clicks), 0),
      'external_clicks', nullif(sum(external_clicks), 0),
      'reading_90', nullif(sum(reading_90), 0),
      'active_30', nullif(sum(active_30), 0),
      'demo_last_section', nullif(sum(demo_last_section), 0)
    )) AS totals
    FROM scoped WHERE bucket_date BETWEEN start_date - p_period AND start_date - 1
  ), today_totals AS (
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'page_views', nullif(sum(page_views), 0),
      'contact_clicks', nullif(sum(contact_clicks), 0),
      'external_clicks', nullif(sum(external_clicks), 0),
      'reading_90', nullif(sum(reading_90), 0),
      'active_30', nullif(sum(active_30), 0),
      'demo_last_section', nullif(sum(demo_last_section), 0)
    )) AS totals
    FROM scoped WHERE bucket_date = (now() AT TIME ZONE 'UTC')::date
      AND (status_row.summary_cutoff_at AT TIME ZONE 'UTC')::date = (now() AT TIME ZONE 'UTC')::date
  )
  SELECT jsonb_build_object(
    'available', true,
    'start', start_date,
    'end', end_date,
    'firstRecordedAt', (SELECT min(first_recorded_at) FROM scoped),
    'excludedEvents', coalesce((SELECT sum(excluded_events) FROM scoped WHERE bucket_date BETWEEN start_date AND end_date), 0),
    'totals', coalesce((SELECT totals FROM current_totals), '{}'::jsonb),
    'previousTotals', coalesce((SELECT totals FROM previous_totals), '{}'::jsonb),
    'todayTotals', coalesce((SELECT totals FROM today_totals), '{}'::jsonb),
    'recordedSections', coalesce((SELECT jsonb_agg(DISTINCT section ORDER BY section) FROM scoped WHERE bucket_date <= end_date), '[]'::jsonb),
    'page', (SELECT page FROM page_window),
    'pageCount', (SELECT page_count FROM page_window),
    'pages', coalesce((
      SELECT jsonb_agg(jsonb_build_object('path', path, 'section', section, 'measures', measures) ORDER BY views DESC, path, section)
      FROM (
        SELECT p.path, p.section, p.measures, p.views
        FROM current_pages p CROSS JOIN page_window w
        ORDER BY p.views DESC, p.path, p.section
        LIMIT 8 OFFSET ((SELECT page FROM page_window) * 8)
      ) page_rows
    ), '[]'::jsonb),
    'freshness', jsonb_build_object(
      'status', CASE WHEN status_row.last_error_at > status_row.last_successful_at
        OR status_row.last_successful_at < statement_timestamp() - interval '45 minutes' THEN 'stale' ELSE 'current' END,
      'refreshedAt', status_row.last_successful_at,
      'todayAvailable', (status_row.summary_cutoff_at AT TIME ZONE 'UTC')::date = (now() AT TIME ZONE 'UTC')::date,
      'completedThrough', end_date,
      'summaryCutoffAt', status_row.summary_cutoff_at,
      'lastFailureAt', CASE WHEN status_row.last_error_at > status_row.last_successful_at THEN status_row.last_error_at ELSE NULL END
    )
  ) INTO output;
  RETURN output;
END;
$$;


ALTER FUNCTION "public"."analytics_site_actions"("p_period" integer, "p_section" "text", "p_page" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."analytics_site_actions"("p_period" integer, "p_section" "text", "p_page" integer) IS 'Reads only identifier-free stored UTC summaries. The refresh cutoff, not the current time, bounds today partial totals.';



CREATE OR REPLACE FUNCTION "public"."enforce_album_sport"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  SELECT a.sport::text INTO NEW.sport_type FROM albums a WHERE a.album_key = NEW.album_key;
  RETURN NEW;   -- album unknown → sport_type NULL (cannot invent a sport)
END $$;


