CREATE OR REPLACE FUNCTION "public"."exec_sql"("sql" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  DECLARE
    result jsonb;
    normalized_sql text;
  BEGIN
    -- Normalize the SQL: remove ALL leading/trailing whitespace and newlines
    -- This handles multiline SQL strings with indentation
    normalized_sql := regexp_replace(trim(sql), '^\s+', '', 'g');
    normalized_sql := lower(normalized_sql);

    -- Security check: Only allow SELECT statements
    IF NOT (normalized_sql LIKE 'select%') THEN
      RAISE EXCEPTION 'Only SELECT queries are allowed. Query must start with SELECT.';
    END IF;

    -- Additional security: Block dangerous keywords even in SELECT statements
    IF normalized_sql ~* '\b(insert|update|delete|drop|truncate|alter|create|grant|revoke)\b' THEN
      RAISE EXCEPTION 'Query contains forbidden SQL keywords';
    END IF;

    -- Execute the query and convert results to JSONB
    EXECUTE format('SELECT jsonb_agg(row_to_json(t)) FROM (%s) t', sql) INTO result;

    -- Return empty array if no results
    RETURN COALESCE(result, '[]'::jsonb);

  EXCEPTION
    WHEN OTHERS THEN
      -- Log the error and re-raise with context
      RAISE WARNING 'exec_sql error: % (SQL: %)', SQLERRM, sql;
      RAISE;
  END;
  $$;


ALTER FUNCTION "public"."exec_sql"("sql" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."exec_sql"("sql" "text") IS 'Execute a read-only SQL query and return results as JSONB. Only SELECT queries are allowed. Used for efficient aggregation queries like sport/category distributions. Updated to handle multiline SQL with 
  leading whitespace.';



CREATE OR REPLACE FUNCTION "public"."find_photos_by_jersey"("p_jersey" "text", "p_album_key" "text" DEFAULT NULL::"text", "p_team_color" "text" DEFAULT NULL::"text", "p_sport" "public"."sport_enum" DEFAULT NULL::"public"."sport_enum", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("photo_id" "text", "image_key" "text", "album_key" "text", "album_name" "text", "sport_type" "text", "cf_image_id" "text", "quality_score" numeric, "jersey_number" "text", "team_color" "text", "team_side" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH hits AS (
    SELECT DISTINCT ON (pm.photo_id)
           pm.photo_id, pm.image_key, pm.album_key, a.album_name, pm.sport_type,
           pm.cf_image_id, pm.quality_score, s.jersey_number, s.team_color, s.team_side
    FROM photo_jersey_sightings s
    JOIN photo_metadata pm   ON pm.photo_id = s.photo_id
    LEFT JOIN albums a       ON a.album_key = pm.album_key
    LEFT JOIN album_settings aset ON aset.album_key = pm.album_key
    WHERE s.jersey_number = btrim(p_jersey)
      AND pm.sharpness IS NOT NULL
      AND (aset.visibility IS NULL OR aset.visibility <> 'unlisted')  -- privacy gate (from 210000)
      AND (p_album_key  IS NULL OR pm.album_key = p_album_key)
      AND (p_sport      IS NULL OR a.sport = p_sport)
      AND (p_team_color IS NULL OR norm_color(s.team_color) = norm_color(p_team_color))
    ORDER BY pm.photo_id
  )
  SELECT hits.photo_id, hits.image_key, hits.album_key, hits.album_name, hits.sport_type,
         hits.cf_image_id, hits.quality_score, hits.jersey_number, hits.team_color, hits.team_side
  FROM hits
  LEFT JOIN public.photo_popularity pp ON pp.photo_id = hits.photo_id
  ORDER BY hits.quality_score DESC NULLS LAST,
           COALESCE(pp.trending_score, 0) DESC,
           hits.photo_id
  LIMIT p_limit OFFSET p_offset;
$$;


ALTER FUNCTION "public"."find_photos_by_jersey"("p_jersey" "text", "p_album_key" "text", "p_team_color" "text", "p_sport" "public"."sport_enum", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_similar_photos"("target_image_key" "text", "limit_count" integer DEFAULT 10, "min_similarity" double precision DEFAULT 0.5) RETURNS TABLE("image_key" "text", "sport_type" "text", "photo_category" "text", "similarity" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  target_embedding public.vector(768);
BEGIN
  -- Get the embedding for the target photo
  SELECT pm.embedding INTO target_embedding
  FROM public.photo_metadata pm
  WHERE pm.image_key = target_image_key;

  IF target_embedding IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    pm.image_key::text,
    pm.sport_type::text,
    pm.photo_category::text,
    (1 - (pm.embedding <=> target_embedding))::double precision AS similarity
  FROM public.photo_metadata pm
  WHERE pm.image_key != target_image_key
    AND pm.embedding IS NOT NULL
    AND 1 - (pm.embedding <=> target_embedding) >= min_similarity
  ORDER BY pm.embedding <=> target_embedding
  LIMIT limit_count;
END;
$$;


ALTER FUNCTION "public"."find_similar_photos"("target_image_key" "text", "limit_count" integer, "min_similarity" double precision) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."find_similar_photos"("target_image_key" "text", "limit_count" integer, "min_similarity" double precision) IS 'Find similar photos by image_key with secure search_path';



