CREATE OR REPLACE FUNCTION "public"."match_photos"("query_embedding" "public"."vector", "match_threshold" double precision DEFAULT 0.25, "match_count" integer DEFAULT 10) RETURNS TABLE("image_key" "text", "sport_type" "text", "photo_category" "text", "play_type" "text", "similarity" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT pm.image_key::text, pm.sport_type::text, pm.photo_category::text, pm.play_type::text,
         (1 - (pm.image_embedding <=> query_embedding))::double precision AS similarity
  FROM public.photo_metadata pm
  WHERE pm.image_embedding IS NOT NULL
    AND 1 - (pm.image_embedding <=> query_embedding) >= match_threshold
  ORDER BY pm.image_embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


ALTER FUNCTION "public"."match_photos"("query_embedding" "public"."vector", "match_threshold" double precision, "match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_photos_hybrid"("query_embedding" "public"."vector", "match_count" integer DEFAULT 24, "match_threshold" double precision DEFAULT 0.15, "p_sport" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_play_type" "text" DEFAULT NULL::"text", "p_album_key" "text" DEFAULT NULL::"text", "p_date_from" timestamp without time zone DEFAULT NULL::timestamp without time zone, "p_date_to" timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE("image_key" "text", "similarity" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT pm.image_key::text,
         (1 - (pm.image_embedding <=> query_embedding))::double precision AS similarity
  FROM public.photo_metadata pm
  WHERE pm.image_embedding IS NOT NULL
    AND pm.sharpness IS NOT NULL
    AND (p_sport     IS NULL OR pm.sport_type     = p_sport)
    AND (p_category  IS NULL OR pm.photo_category  = p_category)
    AND (p_play_type IS NULL OR pm.play_type       = p_play_type)
    AND (p_album_key IS NULL OR pm.album_key       = p_album_key)
    AND (p_date_from IS NULL OR pm.photo_date      >= p_date_from)
    AND (p_date_to   IS NULL OR pm.photo_date      <= p_date_to)
    AND (1 - (pm.image_embedding <=> query_embedding)) >= match_threshold
  ORDER BY pm.image_embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


ALTER FUNCTION "public"."match_photos_hybrid"("query_embedding" "public"."vector", "match_count" integer, "match_threshold" double precision, "p_sport" "text", "p_category" "text", "p_play_type" "text", "p_album_key" "text", "p_date_from" timestamp without time zone, "p_date_to" timestamp without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."norm_color"("c" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  SELECT nullif(
    regexp_replace(
      regexp_replace(
        regexp_replace(pg_catalog.lower(pg_catalog.btrim(c)), '\s+', ' ', 'g'),
        '[.,;:]+$', ''),
      '\mgrey\M', 'gray', 'g'),
    '');
$_$;


ALTER FUNCTION "public"."norm_color"("c" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_engagement_events"() RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'analytics_private'
    AS $$
