    "album_key" "text",
    "event_type" "text" NOT NULL,
    "session_hash" "text",
    "source" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "event_day" "date" DEFAULT (("now"() AT TIME ZONE 'UTC'::"text"))::"date" NOT NULL,
    "traffic_context" "text" DEFAULT 'audience'::"text" NOT NULL,
    "source_kind" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "catalogue_snapshot" "jsonb",
    CONSTRAINT "engagement_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['view'::"text", 'favorite'::"text", 'download'::"text", 'share'::"text", 'album_open'::"text"]))),
    CONSTRAINT "engagement_events_source_kind_check" CHECK (("source_kind" = ANY (ARRAY['tagged_arrival'::"text", 'internal_open_location'::"text", 'action'::"text", 'unknown'::"text"]))),
    CONSTRAINT "engagement_events_traffic_context_check" CHECK (("traffic_context" = ANY (ARRAY['audience'::"text", 'operator'::"text", 'test'::"text", 'self_excluded'::"text"])))
);


