CREATE OR REPLACE VIEW "analytics_private"."suspected_automation_sessions" WITH ("security_invoker"='true') AS
 SELECT DISTINCT "session_hash"
   FROM "public"."engagement_events" "e"
  WHERE (("event_type" = 'view'::"text") AND ("photo_id" IS NOT NULL) AND ("session_hash" IS NOT NULL) AND ("traffic_context" = 'audience'::"text"))
  GROUP BY "session_hash", "event_day"
 HAVING ("count"(*) > 500);


