    "corrected_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "corrected_by" "uuid",
    CONSTRAINT "engagement_classification_correcti_classification_version_check" CHECK (("classification_version" > 1)),
    CONSTRAINT "engagement_classification_corrections_classification_check" CHECK (("classification" = ANY (ARRAY['audience'::"text", 'operator'::"text", 'test'::"text", 'known_crawler'::"text", 'suspected_automation'::"text", 'unclassified'::"text"]))),
    CONSTRAINT "engagement_classification_corrections_note_check" CHECK ((("char_length"(TRIM(BOTH FROM "note")) >= 1) AND ("char_length"(TRIM(BOTH FROM "note")) <= 1000)))
);


ALTER TABLE "public"."engagement_classification_corrections" OWNER TO "postgres";


