    CONSTRAINT "engagement_event_classifications_classification_check" CHECK (("classification" = ANY (ARRAY['audience'::"text", 'operator'::"text", 'test'::"text", 'known_crawler'::"text", 'suspected_automation'::"text", 'unclassified'::"text"]))),
    CONSTRAINT "engagement_event_classifications_classification_version_check" CHECK (("classification_version" = 1))
);


ALTER TABLE "public"."engagement_event_classifications" OWNER TO "postgres";


CREATE OR REPLACE VIEW "analytics_private"."effective_engagement_events" WITH ("security_invoker"='true') AS
 WITH "latest_correction" AS (
         SELECT DISTINCT ON ("correction"."engagement_event_id") "correction"."engagement_event_id",
            "correction"."classification",
            "correction"."classification_version",
            "correction"."reason_flags"
           FROM "public"."engagement_classification_corrections" "correction"
          ORDER BY "correction"."engagement_event_id", "correction"."classification_version" DESC, "correction"."corrected_at" DESC, "correction"."id" DESC
        )
 SELECT "e"."id",
    "e"."photo_id",
    "e"."album_key",
    "e"."event_type",
    "e"."session_hash",
    "e"."source",
    "e"."created_at",
    "e"."event_day",
    "e"."traffic_context",
    "e"."source_kind",
    "e"."catalogue_snapshot",
    COALESCE(NULLIF(("e"."catalogue_snapshot" ->> 'album_key'::"text"), ''::"text"), "e"."album_key") AS "resolved_album_key",
    COALESCE(("e"."catalogue_snapshot" ->> '_basis'::"text"), 'backfill_current_catalogue'::"text") AS "catalogue_basis",
    COALESCE(("e"."catalogue_snapshot" ->> 'sport'::"text"), 'unknown'::"text") AS "snapshot_sport",
    (("e"."catalogue_snapshot" ->> 'event_date'::"text"))::"date" AS "snapshot_event_date",
    COALESCE(("e"."catalogue_snapshot" ->> 'album_event_type'::"text"), 'unknown'::"text") AS "snapshot_album_event_type",
    (("e"."catalogue_snapshot" ->> 'publication_at'::"text"))::timestamp with time zone AS "snapshot_publication_at",
    COALESCE(("e"."catalogue_snapshot" ->> 'photo_category'::"text"), 'unknown'::"text") AS "snapshot_photo_category",
        CASE
            WHEN ("e"."source_kind" <> 'unknown'::"text") THEN "e"."source_kind"
            WHEN (("e"."event_type" = 'view'::"text") AND ("e"."photo_id" IS NULL) AND (COALESCE("e"."source", 'direct'::"text") <> 'direct'::"text")) THEN 'tagged_arrival'::"text"
            WHEN ("e"."event_type" = ANY (ARRAY['view'::"text", 'album_open'::"text"])) THEN 'internal_open_location'::"text"
            WHEN ("e"."event_type" = ANY (ARRAY['favorite'::"text", 'download'::"text", 'share'::"text"])) THEN 'action'::"text"
            ELSE 'unknown'::"text"
        END AS "resolved_source_kind",
        CASE
            WHEN ("latest"."classification" IS NOT NULL) THEN "latest"."classification"
            WHEN ("e"."traffic_context" = 'operator'::"text") THEN 'operator'::"text"
            WHEN ("e"."traffic_context" = 'test'::"text") THEN 'test'::"text"
            WHEN ("suspected"."session_hash" IS NOT NULL) THEN 'suspected_automation'::"text"
            WHEN ("base"."classification" IS NOT NULL) THEN "base"."classification"
            ELSE 'unclassified'::"text"
        END AS "effective_classification",
    COALESCE("latest"."classification_version", "base"."classification_version", 1) AS "effective_classification_version",
    COALESCE("latest"."reason_flags", "base"."reason_flags", ARRAY['unclassified'::"text"]) AS "effective_reason_flags"
   FROM ((("public"."engagement_events" "e"
     LEFT JOIN "public"."engagement_event_classifications" "base" ON (("base"."engagement_event_id" = "e"."id")))
     LEFT JOIN "latest_correction" "latest" ON (("latest"."engagement_event_id" = "e"."id")))
     LEFT JOIN "analytics_private"."suspected_automation_sessions" "suspected" ON (("suspected"."session_hash" = "e"."session_hash")));


ALTER VIEW "analytics_private"."effective_engagement_events" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."album_settings" (
    "album_key" "text" NOT NULL,
    "visibility" "text" DEFAULT 'public'::"text" NOT NULL,
    "share_token" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "gallery_scope" "text",
    "published_at" timestamp with time zone,
    "published_at_basis" "text",
    "published_at_evidence" "text",
    "first_published_at" timestamp with time zone,
    "first_published_at_basis" "text",
    "first_published_at_evidence" "text",
    CONSTRAINT "album_settings_first_published_at_basis_check" CHECK (("first_published_at_basis" = ANY (ARRAY['recorded'::"text", 'inferred'::"text", 'unobserved'::"text"]))),
    CONSTRAINT "album_settings_first_published_at_basis_present" CHECK ((("first_published_at" IS NOT NULL) = COALESCE(("first_published_at_basis" = ANY (ARRAY['recorded'::"text", 'inferred'::"text"])), false))),
    CONSTRAINT "album_settings_first_published_at_evidence_present" CHECK ((COALESCE(("first_published_at_basis" = ANY (ARRAY['inferred'::"text", 'unobserved'::"text"])), false) = ("first_published_at_evidence" IS NOT NULL))),
    CONSTRAINT "album_settings_first_published_at_order" CHECK ((("first_published_at" IS NULL) OR ("published_at" IS NULL) OR ("first_published_at" <= "published_at"))),
    CONSTRAINT "album_settings_published_at_basis_check" CHECK (("published_at_basis" = ANY (ARRAY['recorded'::"text", 'inferred'::"text"]))),
    CONSTRAINT "album_settings_published_at_basis_present" CHECK ((("published_at" IS NULL) = ("published_at_basis" IS NULL))),
    CONSTRAINT "album_settings_published_at_evidence_present" CHECK ((("published_at_basis" = 'inferred'::"text") = ("published_at_evidence" IS NOT NULL))),
    CONSTRAINT "album_settings_visibility_check" CHECK (("visibility" = ANY (ARRAY['public'::"text", 'unlisted'::"text"])))
);


ALTER TABLE "public"."album_settings" OWNER TO "postgres";


COMMENT ON COLUMN "public"."album_settings"."published_at" IS 'When this album LAST went from unlisted to public. Stamped by the album_settings_stamp_published_at trigger for every writer; a republish replaces it. Drives the latest-gallery ranking. Analytics album age uses first_published_at instead. NULL when no publication was ever observed: legacy albums public before any record existed, and albums whose row was inserted already public. See published_at_basis.';



COMMENT ON COLUMN "public"."album_settings"."published_at_basis" IS 'How published_at was obtained. recorded = stamped by the trigger at the write. inferred = recovered afterwards from a log of the write (see published_at_evidence). NULL exactly when published_at is NULL.';



COMMENT ON COLUMN "public"."album_settings"."published_at_evidence" IS 'For an inferred published_at: the log that observed the unlisted -> public write. NULL otherwise.';



COMMENT ON COLUMN "public"."album_settings"."first_published_at" IS 'When this album FIRST went from unlisted to public, as far as any record shows. Set once by the album_settings_stamp_published_at trigger and never moved by a republish. Anchors every analytics album-age comparison (new-album rule, publication-age comparison, Rising). NULL when no publication was seen yet or the album was public before anything recorded it; never later than published_at. Analytics treats NULL as "no launch date". See first_published_at_basis.';



COMMENT ON COLUMN "public"."album_settings"."first_published_at_basis" IS 'How first_published_at was obtained. recorded = stamped by the trigger at the write. inferred = recovered afterwards from a log of the write (see first_published_at_evidence); an inferred first publication is the earliest write that log search found, so an earlier unlogged one is possible. unobserved = the album was public before anything recorded it, so there is no time (first_published_at is NULL, evidence says why) and a republish never invents one. NULL = no publication seen yet.';



COMMENT ON COLUMN "public"."album_settings"."first_published_at_evidence" IS 'For an inferred first_published_at: the log that observed the write. For unobserved: why there is no time. NULL otherwise.';



CREATE OR REPLACE VIEW "public"."album_engagement_30d" WITH ("security_invoker"='true') AS
 SELECT "e"."resolved_album_key" AS "album_key",
    "count"(DISTINCT "e"."session_hash") AS "engaged_visitors",
    "count"(*) FILTER (WHERE ("e"."event_type" = 'album_open'::"text")) AS "album_opens",
    "count"(*) FILTER (WHERE (("e"."event_type" = 'view'::"text") AND ("e"."photo_id" IS NOT NULL))) AS "photo_opens",
    "count"(*) FILTER (WHERE ("e"."event_type" = 'favorite'::"text")) AS "favorites",
    "count"(*) FILTER (WHERE ("e"."event_type" = 'download'::"text")) AS "downloads",
    "count"(*) FILTER (WHERE ("e"."event_type" = 'share'::"text")) AS "shares",
    "max"("e"."created_at") AS "last_event"
   FROM ("analytics_private"."effective_engagement_events" "e"
     LEFT JOIN "public"."album_settings" "settings" ON (("settings"."album_key" = "e"."resolved_album_key")))
  WHERE (("e"."created_at" >= ("now"() - '30 days'::interval)) AND ("e"."resolved_album_key" IS NOT NULL) AND ("e"."effective_classification" = ANY (ARRAY['audience'::"text", 'unclassified'::"text"])) AND (COALESCE("settings"."visibility", 'public'::"text") <> 'unlisted'::"text"))
  GROUP BY "e"."resolved_album_key";


ALTER VIEW "public"."album_engagement_30d" OWNER TO "postgres";


COMMENT ON VIEW "public"."album_engagement_30d" IS 'Per-album 30-day reach. engaged_visitors is a privacy-preserving IP+UA estimate; album_opens and photo_opens are separate deduped events. Automated sessions are excluded.';



