CREATE TABLE IF NOT EXISTS "public"."photo_metadata" (
    "photo_id" "text" NOT NULL,
    "image_key" "text" NOT NULL,
    "sharpness" numeric(3,1),
    "exposure_accuracy" numeric(3,1),
    "composition_score" numeric(3,1),
    "emotional_impact" numeric(3,1),
    "play_type" "text",
    "ai_provider" "text",
    "ai_cost" numeric(8,6),
    "enriched_at" timestamp without time zone DEFAULT "now"(),
    "album_key" "text",
    "ImageUrl" "text",
    "OriginalUrl" "text",
    "ThumbnailUrl" "text",
    "album_name" "text",
    "photo_date" timestamp without time zone DEFAULT "now"(),
    "upload_date" timestamp without time zone,
    "date_added" timestamp without time zone,
    "width" integer,
    "height" integer,
    "file_name" "text",
    "aspect_ratio" numeric(5,3),
    "latitude" numeric(10,8),
    "longitude" numeric(11,8),
    "location_name" "text",
    "camera_make" "text",
    "camera_model" "text",
    "lens_model" "text",
    "focal_length" "text",
    "aperture" "text",
    "shutter_speed" "text",
    "iso" integer,
    "sport_type" character varying(50),
    "photo_category" character varying(50),
    "time_in_game" "text",
    "jersey_number" integer,
    "embedding" "public"."vector"(768),
    "players" "jsonb" DEFAULT '[]'::"jsonb",
    "team_colors" "jsonb",
    "cf_image_id" "text",
    "caption" "text",
    "quality_score" numeric GENERATED ALWAYS AS (((((COALESCE("sharpness", (0)::numeric) * 0.35) + (COALESCE("composition_score", (0)::numeric) * 0.30)) + (COALESCE("emotional_impact", (0)::numeric) * 0.25)) + (COALESCE("exposure_accuracy", (0)::numeric) * 0.10))) STORED,
    "extraction_version" "text",
    "visible_text" "text"[],
    "visible_text_flat" "text" GENERATED ALWAYS AS ("lower"("public"."immutable_text_array_join"("visible_text", ' '::"text"))) STORED,
    "content_hash" "text",
    "image_embedding" "public"."vector"(768),
    "sharpness_measured" double precision,
    "hdr_web_available" boolean DEFAULT false NOT NULL,
    "alt_text" "text",
    CONSTRAINT "valid_photo_category" CHECK ((("photo_category" IS NULL) OR (("photo_category")::"text" = ANY ((ARRAY['action'::character varying, 'celebration'::character varying, 'candid'::character varying, 'portrait'::character varying, 'warmup'::character varying, 'ceremony'::character varying])::"text"[])))),
    CONSTRAINT "valid_play_for_sport" CHECK ((("play_type" IS NULL) OR (("sport_type" IS NOT NULL) AND (((("sport_type")::"text" = 'volleyball'::"text") AND ("play_type" = ANY (ARRAY['spike'::"text", 'block'::"text", 'dig'::"text", 'set'::"text", 'serve'::"text", 'pass'::"text"]))) OR ((("sport_type")::"text" = 'basketball'::"text") AND ("play_type" = ANY (ARRAY['dunk'::"text", 'layup'::"text", 'jump_shot'::"text", 'rebound'::"text", 'block'::"text", 'pass'::"text", 'dribble'::"text"]))) OR ((("sport_type")::"text" = 'soccer'::"text") AND ("play_type" = ANY (ARRAY['kick'::"text", 'header'::"text", 'tackle'::"text", 'save'::"text", 'dribble'::"text", 'pass'::"text"]))) OR ((("sport_type")::"text" = 'softball'::"text") AND ("play_type" = ANY (ARRAY['pitch'::"text", 'hit'::"text", 'catch'::"text", 'throw'::"text", 'slide'::"text", 'run'::"text"]))) OR ((("sport_type")::"text" = 'baseball'::"text") AND ("play_type" = ANY (ARRAY['pitch'::"text", 'hit'::"text", 'catch'::"text", 'throw'::"text", 'slide'::"text", 'run'::"text"]))) OR ((("sport_type")::"text" = 'football'::"text") AND ("play_type" = ANY (ARRAY['throw'::"text", 'catch'::"text", 'run'::"text", 'tackle'::"text", 'block'::"text", 'kick'::"text"]))) OR ((("sport_type")::"text" = 'track'::"text") AND ("play_type" = ANY (ARRAY['sprint'::"text", 'hurdle'::"text", 'relay'::"text", 'long_jump'::"text", 'high_jump'::"text", 'pole_vault'::"text", 'shot_put'::"text", 'discus'::"text", 'javelin'::"text"]))) OR ((("sport_type")::"text" = 'cross_country'::"text") AND ("play_type" = ANY (ARRAY['running'::"text", 'start'::"text", 'finish'::"text", 'pack_running'::"text", 'hill_climb'::"text"]))) OR ((("sport_type")::"text" = 'golf'::"text") AND ("play_type" = ANY (ARRAY['swing'::"text", 'putt'::"text", 'chip'::"text", 'drive'::"text"]))) OR ((("sport_type")::"text" = 'tennis'::"text") AND ("play_type" = ANY (ARRAY['serve'::"text", 'forehand'::"text", 'backhand'::"text", 'volley'::"text", 'smash'::"text"]))) OR ((("sport_type")::"text" = 'bowling'::"text") AND ("play_type" = ANY (ARRAY['delivery'::"text", 'release'::"text", 'approach'::"text"]))) OR ((("sport_type")::"text" = 'pickleball'::"text") AND ("play_type" = ANY (ARRAY['serve'::"text", 'dink'::"text", 'volley'::"text", 'smash'::"text", 'drive'::"text"]))))))),
    CONSTRAINT "valid_play_type" CHECK ((("play_type" IS NULL) OR ("play_type" = ANY (ARRAY['approach'::"text", 'backhand'::"text", 'block'::"text", 'catch'::"text", 'chip'::"text", 'delivery'::"text", 'dig'::"text", 'dink'::"text", 'discus'::"text", 'dribble'::"text", 'drive'::"text", 'dunk'::"text", 'finish'::"text", 'forehand'::"text", 'header'::"text", 'high_jump'::"text", 'hill_climb'::"text", 'hit'::"text", 'hurdle'::"text", 'javelin'::"text", 'jump_shot'::"text", 'kick'::"text", 'layup'::"text", 'long_jump'::"text", 'pack_running'::"text", 'pass'::"text", 'pitch'::"text", 'pole_vault'::"text", 'putt'::"text", 'rebound'::"text", 'relay'::"text", 'release'::"text", 'run'::"text", 'running'::"text", 'save'::"text", 'serve'::"text", 'set'::"text", 'shot_put'::"text", 'slide'::"text", 'smash'::"text", 'spike'::"text", 'sprint'::"text", 'start'::"text", 'swing'::"text", 'tackle'::"text", 'throw'::"text", 'volley'::"text"])))),
    CONSTRAINT "valid_sport_type" CHECK ((("sport_type" IS NULL) OR (("sport_type")::"text" = ANY ((ARRAY['volleyball'::character varying, 'basketball'::character varying, 'soccer'::character varying, 'softball'::character varying, 'baseball'::character varying, 'football'::character varying, 'track'::character varying, 'cross_country'::character varying, 'golf'::character varying, 'tennis'::character varying, 'bowling'::character varying, 'pickleball'::character varying, 'other'::character varying])::"text"[]))))
);


