COMMENT ON TABLE "public"."photo_metadata" IS 'Photo metadata with RLS: public read, service role write';



COMMENT ON COLUMN "public"."photo_metadata"."ImageUrl" IS 'Primary display URL from SmugMug (typically D size)';



COMMENT ON COLUMN "public"."photo_metadata"."OriginalUrl" IS 'Original full-resolution URL from SmugMug';



COMMENT ON COLUMN "public"."photo_metadata"."ThumbnailUrl" IS 'Thumbnail URL for previews (typically S or M size)';



COMMENT ON COLUMN "public"."photo_metadata"."photo_date" IS 'Actual photo capture date from EXIF (preferred for sorting)';



COMMENT ON COLUMN "public"."photo_metadata"."upload_date" IS 'When photo was uploaded to SmugMug';



COMMENT ON COLUMN "public"."photo_metadata"."date_added" IS 'When photo was added to album (fallback date)';



COMMENT ON COLUMN "public"."photo_metadata"."aspect_ratio" IS 'Width/height ratio for responsive layout (e.g., 1.5 for 3:2 aspect)';



COMMENT ON COLUMN "public"."photo_metadata"."sport_type" IS 'Sport classification: volleyball, basketball, soccer, portrait, etc.';



COMMENT ON COLUMN "public"."photo_metadata"."photo_category" IS 'Photo category: action, portrait, candid, celebration, warmup, ceremony';



COMMENT ON COLUMN "public"."photo_metadata"."jersey_number" IS 'Player jersey number extracted from photo via AI vision. NULL if not visible/applicable.';



COMMENT ON COLUMN "public"."photo_metadata"."embedding" IS '768-d vector. Phase 1: caption-derived (OpenRouter text-embedding-3-large @768) once backfilled; pre-Phase-1 rows hold enum-string-derived vectors. Query + write MUST share src/lib/ai/embeddings.ts:embedText() so vectors stay in one space.';



COMMENT ON COLUMN "public"."photo_metadata"."caption" IS 'AI-generated NL caption (<=30 words: visible jersey numbers/colors, action, scene). Source text for the `embedding` vector (Phase 1, vision-extraction v-next).';



COMMENT ON COLUMN "public"."photo_metadata"."quality_score" IS 'Generated weighted quality blend (sharpness .35 / composition .30 / emotional .25 / exposure .10). Drives the default "Best Photos" sort; mirrors calculateQualityScore() in src/lib/services/photo-scoring.ts.';



COMMENT ON COLUMN "public"."photo_metadata"."content_hash" IS 'sha256 hex digest of the original file bytes at ingest time. NULL for rows ingested before 2026-09-25 (or any row an ingest run has not yet (re)computed it for). UNIQUE among non-null values — see supabase/migrations/20260925210000_photo_metadata_content_hash.sql.';



COMMENT ON COLUMN "public"."photo_metadata"."image_embedding" IS '768-dimensional image embedding (google/gemini-embedding-2, OpenRouter) for semantic search — the primary search-ranking vector as of blueprint/decisions/0006. NULL until backfilled (scripts/backfill-image-embeddings.ts) or reprocessed by ingest. Distinct from `embedding`, which stays the caption-text embedding.';



COMMENT ON COLUMN "public"."photo_metadata"."sharpness_measured" IS 'Deterministic variance-of-Laplacian sharpness (src/lib/ai/sharpness.ts), computed in float math on a 768px greyscale resize. Companion to the model-scored `sharpness` column, not a replacement — `quality_score` and every existing `sharpness` consumer are unchanged.';



COMMENT ON COLUMN "public"."photo_metadata"."hdr_web_available" IS 'TRUE when a web-sized Ultra HDR (gain-map) JPEG for this photo exists in the photo-gallery-hdr R2 bucket at key hdr/${photo_id}.jpg. Set by scripts/ingest-album.ts only when the source file has a gain map AND the resize-preserving-gain-map pipeline (src/lib/ai/hdr-resize.ts) succeeded. FALSE (the default) means fall back to the Cloudflare Images variant, same as before this column existed.';



COMMENT ON COLUMN "public"."photo_metadata"."alt_text" IS 'Screen-reader / <img alt> sentence — who is doing what (team by uniform color, action, setting). Never contains a jersey number, a name, printed text from the frame, guessed identity, or aesthetic filler (src/lib/ai/alt-text-contract.ts). Distinct from `caption`, which MUST name jersey numbers for search (ADR 0006) — do not derive one from the other by post-processing. NULL until ingested under this extraction version or backfilled (scripts/backfill-alt-text.ts).';



CREATE MATERIALIZED VIEW "public"."album_popularity" AS
 WITH "album_events" AS (
         SELECT "e"."resolved_album_key" AS "album_key",
            "e"."photo_id",
            "e"."event_type",
            "e"."created_at",
            "w"."weight"
           FROM (("analytics_private"."effective_engagement_events" "e"
             JOIN "public"."engagement_weights" "w" ON (("w"."event_type" = "e"."event_type")))
             LEFT JOIN "public"."album_settings" "settings" ON (("settings"."album_key" = "e"."resolved_album_key")))
          WHERE (("e"."resolved_album_key" IS NOT NULL) AND ("e"."effective_classification" = ANY (ARRAY['audience'::"text", 'unclassified'::"text"])) AND (COALESCE("settings"."visibility", 'public'::"text") <> 'unlisted'::"text"))
        ), "sizes" AS (
         SELECT "photo_metadata"."album_key",
            ("count"(*))::numeric AS "total_photos"
           FROM "public"."photo_metadata"
          WHERE ("photo_metadata"."sharpness" IS NOT NULL)
          GROUP BY "photo_metadata"."album_key"
        )
 SELECT "ae"."album_key",
    "sum"(("ae"."weight" * "exp"(((- EXTRACT(epoch FROM ("now"() - "ae"."created_at"))) / 604800.0)))) AS "trending_score",
    "sum"("ae"."weight") AS "all_time_score",
    ("sum"("ae"."weight") / NULLIF("s"."total_photos", (0)::numeric)) AS "score_per_photo",
    "count"(DISTINCT "ae"."photo_id") AS "photos_engaged",
    "s"."total_photos",
    "max"("ae"."created_at") AS "last_event"
   FROM ("album_events" "ae"
     LEFT JOIN "sizes" "s" ON (("s"."album_key" = "ae"."album_key")))
  GROUP BY "ae"."album_key", "s"."total_photos"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."album_popularity" OWNER TO "postgres";


COMMENT ON COLUMN "public"."album_popularity"."all_time_score" IS 'Weighted sum over retained events (<=90d), after effective classification and current visibility.';



