ALTER TABLE "public"."album_teams" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."photo_popularity" AS
 SELECT "e"."photo_id",
    "sum"(("w"."weight" * "exp"(((- EXTRACT(epoch FROM ("now"() - "e"."created_at"))) / 604800.0)))) AS "trending_score",
    "sum"("w"."weight") AS "all_time_score",
    "count"(*) FILTER (WHERE ("e"."event_type" = 'view'::"text")) AS "views",
    "count"(*) FILTER (WHERE ("e"."event_type" = 'favorite'::"text")) AS "favorites",
    "count"(*) FILTER (WHERE ("e"."event_type" = 'download'::"text")) AS "downloads",
    "count"(*) FILTER (WHERE ("e"."event_type" = 'share'::"text")) AS "shares",
    "max"("e"."created_at") AS "last_event"
   FROM (("analytics_private"."effective_engagement_events" "e"
     JOIN "public"."engagement_weights" "w" ON (("w"."event_type" = "e"."event_type")))
     LEFT JOIN "public"."album_settings" "settings" ON (("settings"."album_key" = "e"."resolved_album_key")))
  WHERE (("e"."photo_id" IS NOT NULL) AND ("e"."effective_classification" = ANY (ARRAY['audience'::"text", 'unclassified'::"text"])) AND (COALESCE("settings"."visibility", 'public'::"text") <> 'unlisted'::"text"))
  GROUP BY "e"."photo_id"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."photo_popularity" OWNER TO "postgres";


COMMENT ON COLUMN "public"."photo_popularity"."all_time_score" IS 'Weighted sum over retained events (<=90d), after effective classification and current visibility.';



CREATE MATERIALIZED VIEW "public"."album_top_photo" AS
 SELECT DISTINCT ON ("pm"."album_key") "pm"."album_key",
    "pm"."photo_id",
    "pm"."cf_image_id",
    "popularity"."trending_score"
   FROM ("public"."photo_popularity" "popularity"
     JOIN "public"."photo_metadata" "pm" ON (("pm"."photo_id" = "popularity"."photo_id")))
  WHERE (("pm"."album_key" IS NOT NULL) AND ("pm"."cf_image_id" IS NOT NULL) AND ("pm"."sharpness" IS NOT NULL))
  ORDER BY "pm"."album_key", "popularity"."trending_score" DESC NULLS LAST, "pm"."photo_id"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."album_top_photo" OWNER TO "postgres";


