CREATE MATERIALIZED VIEW "public"."albums_summary" AS
 SELECT "album_key",
    "max"("album_name") AS "album_name",
    "count"(*) AS "photo_count",
    ("array_agg"(COALESCE("ThumbnailUrl", "ImageUrl") ORDER BY "upload_date" DESC) FILTER (WHERE (COALESCE("ThumbnailUrl", "ImageUrl") !~~ '%smugmug.com%'::"text")))[1] AS "cover_image_url",
    ("array_agg"("cf_image_id" ORDER BY "sharpness" DESC NULLS LAST))[1] AS "cover_cf_image_id",
    "array_agg"(DISTINCT "sport_type") FILTER (WHERE (("sport_type" IS NOT NULL) AND (("sport_type")::"text" <> 'unknown'::"text"))) AS "sports",
    "array_agg"(DISTINCT "photo_category") FILTER (WHERE (("photo_category" IS NOT NULL) AND (("photo_category")::"text" <> 'unknown'::"text"))) AS "categories",
    "count"(*) FILTER (WHERE ("sharpness" >= 0.7)) AS "portfolio_count",
    "round"("avg"("sharpness"), 2) AS "avg_quality_score",
    "mode"() WITHIN GROUP (ORDER BY "sport_type") AS "primary_sport",
    "mode"() WITHIN GROUP (ORDER BY "photo_category") AS "primary_category",
    "min"("photo_date") AS "earliest_photo_date",
    "max"("photo_date") AS "latest_photo_date",
    "max"("upload_date") AS "last_upload_date",
    "max"("enriched_at") AS "last_enriched_at"
   FROM "public"."photo_metadata" "p"
  WHERE (("album_key" IS NOT NULL) AND ("sharpness" IS NOT NULL))
  GROUP BY "album_key"
  ORDER BY ("count"(*)) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."albums_summary" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."analytics_collection_delivery_counters" (
    "bucket_date" "date" NOT NULL,
    "schema_version" smallint NOT NULL,
    "outcome" "text" NOT NULL,
    "count" bigint DEFAULT 0 NOT NULL,
    "reason" "text" NOT NULL,
    CONSTRAINT "analytics_collection_delivery_counters_count_check" CHECK (("count" >= 0)),
    CONSTRAINT "analytics_collection_delivery_counters_outcome_check" CHECK (("outcome" = ANY (ARRAY['accepted'::"text", 'rejected'::"text", 'duplicate'::"text"]))),
    CONSTRAINT "analytics_collection_delivery_counters_reason_check" CHECK (((("outcome" = 'rejected'::"text") AND ("reason" = ANY (ARRAY['known_crawler'::"text", 'invalid_json'::"text", 'invalid_event'::"text", 'unknown_target'::"text", 'target_lookup_failed'::"text", 'album_lookup_failed'::"text", 'accept_failed'::"text", 'not_recorded'::"text"]))) OR (("outcome" <> 'rejected'::"text") AND ("reason" = 'none'::"text")))),
    CONSTRAINT "analytics_collection_delivery_counters_schema_version_check" CHECK (("schema_version" = ANY (ARRAY[1, 2])))
);


ALTER TABLE "public"."analytics_collection_delivery_counters" OWNER TO "postgres";


COMMENT ON COLUMN "public"."analytics_collection_delivery_counters"."reason" IS 'Why the collector refused the event; none for accepted and duplicate. not_recorded marks rejections counted before this column existed, when no reason was kept. target_lookup_failed, album_lookup_failed and accept_failed answered 503: the event was not stored, and the browser retries it once.';



