CREATE OR REPLACE VIEW "public"."engagement_totals_30d" WITH ("security_invoker"='true') AS
 WITH "scoped" AS MATERIALIZED (
         SELECT "e"."event_type",
            "e"."photo_id",
            "e"."session_hash",
            "e"."effective_classification"
           FROM ("analytics_private"."effective_engagement_events" "e"
             LEFT JOIN "public"."album_settings" "settings" ON (("settings"."album_key" = "e"."resolved_album_key")))
          WHERE (("e"."created_at" >= ("now"() - '30 days'::interval)) AND (COALESCE("settings"."visibility", 'public'::"text") <> 'unlisted'::"text"))
        )
 SELECT "count"(*) FILTER (WHERE (("event_type" = 'view'::"text") AND ("photo_id" IS NOT NULL) AND ("effective_classification" = ANY (ARRAY['audience'::"text", 'unclassified'::"text"])))) AS "photo_opens",
    "count"(DISTINCT "session_hash") FILTER (WHERE ("effective_classification" = ANY (ARRAY['audience'::"text", 'unclassified'::"text"]))) AS "engaged_visitors",
    "count"(*) FILTER (WHERE (("event_type" = 'album_open'::"text") AND ("effective_classification" = ANY (ARRAY['audience'::"text", 'unclassified'::"text"])))) AS "album_opens",
    "count"(*) FILTER (WHERE (("event_type" = 'view'::"text") AND ("photo_id" IS NOT NULL) AND ("effective_classification" = 'suspected_automation'::"text"))) AS "automated_photo_opens"
   FROM "scoped";


ALTER VIEW "public"."engagement_totals_30d" OWNER TO "postgres";


COMMENT ON VIEW "public"."engagement_totals_30d" IS 'Headline 30-day analytics totals. Album opens and individual photo opens are separate; crawler sessions are excluded from reach and disclosed as automated_photo_opens.';



CREATE MATERIALIZED VIEW "public"."facet_base_counts" AS
 SELECT "dimension",
    "value",
    "count"(*) AS "count"
   FROM ( SELECT 'sport_type'::"text" AS "dimension",
            "pm"."sport_type" AS "value"
           FROM "public"."photo_metadata" "pm"
          WHERE (("pm"."sharpness" IS NOT NULL) AND ("pm"."sport_type" IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM "public"."album_settings" "s"
                  WHERE (("s"."visibility" = 'unlisted'::"text") AND ("s"."album_key" = "pm"."album_key"))))))
        UNION ALL
         SELECT 'photo_category'::"text" AS "text",
            "pm"."photo_category"
           FROM "public"."photo_metadata" "pm"
          WHERE (("pm"."sharpness" IS NOT NULL) AND ("pm"."photo_category" IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM "public"."album_settings" "s"
                  WHERE (("s"."visibility" = 'unlisted'::"text") AND ("s"."album_key" = "pm"."album_key"))))))
        UNION ALL
         SELECT 'play_type'::"text" AS "text",
            "pm"."play_type"
           FROM "public"."photo_metadata" "pm"
          WHERE (("pm"."sharpness" IS NOT NULL) AND ("pm"."play_type" IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM "public"."album_settings" "s"
                  WHERE (("s"."visibility" = 'unlisted'::"text") AND ("s"."album_key" = "pm"."album_key"))))))) "d"
  GROUP BY "dimension", "value"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."facet_base_counts" OWNER TO "postgres";


