CREATE MATERIALIZED VIEW "public"."popular_photos" AS
 SELECT "photo_id",
    "count"(*) AS "view_count",
    "count"(DISTINCT "date"("viewed_at")) AS "days_active",
    "max"("viewed_at") AS "last_viewed",
    "min"("viewed_at") AS "first_viewed"
   FROM "public"."photo_views"
  WHERE ("viewed_at" >= ("now"() - '30 days'::interval))
  GROUP BY "photo_id"
  ORDER BY ("count"(*)) DESC
  WITH NO DATA;


