CREATE OR REPLACE VIEW "public"."timeline_month_categories" WITH ("security_invoker"='true') AS
 SELECT "date_trunc"('month'::"text", "upload_date") AS "month_start",
    (EXTRACT(year FROM "date_trunc"('month'::"text", "upload_date")))::integer AS "year",
    (EXTRACT(month FROM "date_trunc"('month'::"text", "upload_date")))::integer AS "month",
    COALESCE("photo_category", 'unknown'::character varying) AS "photo_category",
    "count"(*) AS "photo_count"
   FROM "public"."photo_metadata"
  WHERE ("upload_date" IS NOT NULL)
  GROUP BY ("date_trunc"('month'::"text", "upload_date")), "photo_category";


ALTER VIEW "public"."timeline_month_categories" OWNER TO "postgres";


COMMENT ON VIEW "public"."timeline_month_categories" IS 'Category distribution per month with SECURITY INVOKER';



CREATE OR REPLACE VIEW "public"."timeline_month_sports" WITH ("security_invoker"='true') AS
 SELECT "date_trunc"('month'::"text", "upload_date") AS "month_start",
    (EXTRACT(year FROM "date_trunc"('month'::"text", "upload_date")))::integer AS "year",
    (EXTRACT(month FROM "date_trunc"('month'::"text", "upload_date")))::integer AS "month",
    COALESCE("sport_type", 'unknown'::character varying) AS "sport_type",
    "count"(*) AS "photo_count"
   FROM "public"."photo_metadata"
  WHERE ("upload_date" IS NOT NULL)
  GROUP BY ("date_trunc"('month'::"text", "upload_date")), "sport_type";


ALTER VIEW "public"."timeline_month_sports" OWNER TO "postgres";


COMMENT ON VIEW "public"."timeline_month_sports" IS 'Sport distribution per month with SECURITY INVOKER';



CREATE OR REPLACE VIEW "public"."timeline_months" WITH ("security_invoker"='true') AS
 WITH "monthly_base" AS (
         SELECT "date_trunc"('month'::"text", "photo_metadata"."upload_date") AS "month_start",
            (EXTRACT(year FROM "photo_metadata"."upload_date"))::integer AS "year",
            (EXTRACT(month FROM "photo_metadata"."upload_date"))::integer AS "month",
            "photo_metadata"."photo_id",
            "photo_metadata"."sport_type",
            "photo_metadata"."photo_category",
            "photo_metadata"."sharpness",
            "photo_metadata"."composition_score",
            "photo_metadata"."emotional_impact"
           FROM "public"."photo_metadata"
          WHERE ("photo_metadata"."upload_date" IS NOT NULL)
        )
 SELECT "month_start",
    "year",
    "month",
    "count"(*) AS "photo_count",
    "min"("month_start") AS "first_photo_date",
    "max"("month_start") AS "last_photo_date",
    "round"("avg"("sharpness"), 2) AS "avg_sharpness",
    "round"("avg"("composition_score"), 2) AS "avg_composition",
    "round"("avg"("emotional_impact"), 2) AS "avg_impact",
    "count"(*) FILTER (WHERE ("sharpness" >= 8.0)) AS "high_quality_count"
   FROM "monthly_base"
  GROUP BY "month_start", "year", "month";


ALTER VIEW "public"."timeline_months" OWNER TO "postgres";


COMMENT ON VIEW "public"."timeline_months" IS 'Timeline aggregation by month with SECURITY INVOKER';



CREATE MATERIALIZED VIEW "public"."timeline_months_mv" AS
 SELECT "date_trunc"('month'::"text", "upload_date") AS "month_start",
    (EXTRACT(year FROM "date_trunc"('month'::"text", "upload_date")))::integer AS "year",
    (EXTRACT(month FROM "date_trunc"('month'::"text", "upload_date")))::integer AS "month",
    "count"(*) AS "photo_count",
    "min"("upload_date") AS "first_photo_date",
    "max"("upload_date") AS "last_photo_date",
    "round"("avg"("sharpness"), 2) AS "avg_sharpness",
    "round"("avg"("composition_score"), 2) AS "avg_composition_score",
    "count"(*) FILTER (WHERE ("composition_score" >= (80)::numeric)) AS "high_quality_count"
   FROM "public"."photo_metadata"
  WHERE ("sharpness" IS NOT NULL)
  GROUP BY ("date_trunc"('month'::"text", "upload_date"))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."timeline_months_mv" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."timeline_months_mv" IS 'Timeline navigation data - intentionally public for gallery display. Linter warning acknowledged.';



