CREATE OR REPLACE VIEW "public"."view_source_30d" WITH ("security_invoker"='true') AS
 SELECT COALESCE("e"."source", 'direct'::"text") AS "source",
    "count"(*) AS "views"
   FROM ("analytics_private"."effective_engagement_events" "e"
     LEFT JOIN "public"."album_settings" "settings" ON (("settings"."album_key" = "e"."resolved_album_key")))
  WHERE (("e"."event_type" = 'view'::"text") AND ("e"."photo_id" IS NOT NULL) AND ("e"."created_at" >= ("now"() - '30 days'::interval)) AND ("e"."effective_classification" = ANY (ARRAY['audience'::"text", 'unclassified'::"text"])) AND (COALESCE("settings"."visibility", 'public'::"text") <> 'unlisted'::"text"))
  GROUP BY COALESCE("e"."source", 'direct'::"text");


ALTER VIEW "public"."view_source_30d" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."zero_result_searches_30d" WITH ("security_invoker"='true') AS
 SELECT "query_text",
    "count"(*) AS "searches",
    "max"("searched_at") AS "last_searched"
   FROM "public"."search_queries"
  WHERE (("results_count" = 0) AND ("searched_at" >= ("now"() - '30 days'::interval)))
  GROUP BY "query_text";


ALTER VIEW "public"."zero_result_searches_30d" OWNER TO "postgres";


