-- 3. Configuration rows the app needs (CONFIG_ROWS in scripts/dump-schema.mjs)
INSERT INTO public.engagement_weights (event_type, weight) VALUES
  ('download', 6),
  ('favorite', 4),
  ('share', 8),
  ('view', 1)
ON CONFLICT (event_type) DO NOTHING;
INSERT INTO public.analytics_site_action_summary_status (report_name) VALUES
  ('site_actions')
ON CONFLICT (report_name) DO NOTHING;

-- 4. Populate the materialized views once, so their scheduled concurrent refreshes can run
REFRESH MATERIALIZED VIEW "public"."album_popularity";
REFRESH MATERIALIZED VIEW "public"."photo_popularity";
REFRESH MATERIALIZED VIEW "public"."album_top_photo";
REFRESH MATERIALIZED VIEW "public"."albums_summary";
REFRESH MATERIALIZED VIEW "public"."facet_base_counts";
REFRESH MATERIALIZED VIEW "public"."popular_photos";
REFRESH MATERIALIZED VIEW "public"."timeline_months_mv";
REFRESH MATERIALIZED VIEW "public"."videos_summary";

-- 5. Scheduled jobs (pg_cron)
SELECT cron.schedule('analytics-reconcile-current-gallery-day', '*/30 * * * *', 'SELECT analytics_private.reconcile_current_gallery_day(statement_timestamp());');
SELECT cron.schedule('analytics-reconcile-daily', '*/30 * * * *', 'SELECT analytics_private.reconcile_due_days(now());');
SELECT cron.schedule('analytics-site-action-summary-refresh', '7,37 * * * *', 'SELECT analytics_private.refresh_site_action_summaries();');
SELECT cron.schedule('analytics-v2-prune', '23 3 * * *', 'SELECT analytics_private.prune_events_v2_at(now());');
SELECT cron.schedule('analytics-v2-revoked-browser-prune', '29 3 * * *', 'SELECT analytics_private.prune_revoked_analytics_browsers_at(now());');
SELECT cron.schedule('prune-engagement-events', '17 3 * * *', 'SELECT public.prune_engagement_events();');
SELECT cron.schedule('refresh-facet-base-counts', '*/30 * * * *', 'SELECT public.refresh_facet_base_counts();');
SELECT cron.schedule('refresh-popular-photos', '0 * * * *', 'REFRESH MATERIALIZED VIEW CONCURRENTLY popular_photos');
SELECT cron.schedule('refresh-popularity', '*/10 * * * *', 'SELECT public.refresh_popularity();');
